(window.GIM_TS=window.GIM_TS||{})["Chullin.2"]={"from":48,"a":[["\u0003בשהחמיץ\u0004 התמד היא ה\u0003מחלוקת\u0004 האם פטור ממעשר כשמצא כדי מידתו, ודווקא אז חייב במעשר, לשיטת ר' יהודה, אבל אם לא החמיץ — פטור. \u0003ומתניתין\u0004 \u0005[ומשנתנו]\u0006 המתייחסת אל התמד שהחמיץ כאל יין — כשיטת \u0003ר' יהודה\u0004 היא. \u0003וכן אמר ר' יוסי ברבי חנינא: בשהחמיץ מחלוקת.\u0004","\u0003ואמר רב נחמן אמר רבה בר אבוה\u0004 באותו ענין: \u0003תמד שלקחו\u0004 (שקנאו) \u0003בכסף\u0004 של \u0003מעשר\u0004 שני, ובאותה שעה שקנאו לא היה חמוץ, \u0003ולבסוף החמיץ\u0004 — \u0003קנה מעשר,\u0004 חלה עליו קדושת מעשר, ומעות המעשר שנתן עבורו נפדו ויצאו לחולין, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 מפני שבשעה שהחמיץ \u0003איגלאי מילתא למפרע דפירא\u0004 \u0005[נגלה הדבר למפרע ש\u0006בשעה שקנאו \u0005פרי]\u0006 \u0003הוא,\u0004 הראוי להילקח בכסף מעשר, ולא סתם מים, ופדיונו היה ראוי.","ושואלים: \u0003אלא,\u0004 לפי זה, \u0003מתניתין דקתני\u0004 \u0005[משנתנו שהוא שונה\u0006 בה\u0005]\u0006 \u0003החמיץ\u0004 התמד — \u0003אין\u0004 \u0005[כן],\u0006 ניקח בכסף מעשר ודמיו חולין, \u0003לא החמיץ\u0004 — \u0003לא,\u0004 והדמים נשארו בקדושתם, מדוע אנו אומרים כך בלשון פסוקה? \u0003דלמא אי שבקיה הוה\u0004 \u0005[שמא אם היה מניח אותו\u0006 זמן נוסף \u0005היה]\u0006 \u0003מחמיץ! אמר רבה:\u0004 מדובר במשנה \u0003כששייר ממנו\u0004 משהו מן התמד \u0003בכוס ולא החמיץ,\u0004 וידוע איפוא בוודאות שלא היה פרי בשעה שקנאו.","\u0003רבא אמר:\u0004 אין צורך להעמיד את המשנה באופן זה דווקא, אלא \u0003הא מני\u0004 \u0005[\u0006\u0005זו,\u0006 משנתנו, \u0005כשיטת מי היא]?\u0006 כשיטת \u0003ר' יוחנן בן נורי היא,\u0004 שהוא סבור שכל זמן שהתמד לא החמיץ בפועל יש לו דין של מים, ואילו רב נחמן הולך בשיטת החולקים עליו. ומהי אותה מחלוקת? \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 שלושה לוגים מים שאובים שנפלו למקוה שאין בו ארבעים סאה — פסלוהו. \u0003שלשה לוגין מים\u0004 שאובים \u0003חסר קורטוב\u0004 (משהו), שאין בשיעור זה כדי לפסול את המקוה, \u0003שנפל לתוכן קורטוב יין\u0004 אדום, וכך השלימם לשיעור שלושה לוגים, ונעשה \u0003מראיהן\u0004 (צבעם) של כל שלושת הלוגים \u0003כמראה יין,\u0004 \u0003ונפלו\u0004 \u0003למקוה\u0004 — \u0003לא פסלוהו,\u0004 משום שאין כאן שלושה לוגים שלמים של מים.","יתר על כן, \u0003שלשה לוגין מים\u0004 שאובים \u0003חסר קורטוב, שנפל לתוכן קורטוב חלב, ומראיהן\u0004 של כל שלושת הלוגים \u0003כמראה מים, ונפלו למקוה\u0004 — \u0003לא פסלוהו,\u0004 משום שאין אלו שלושה לוגים שלמים של מים.","\u0003רבי יוחנן בן נורי אומר: הכל הולך אחר המראה,\u0004 והואיל ולאותם שלושה לוגים מראה מים — דינם כמים, ופוסלים.","ואם כן, \u0003לאו אמר\u0004 \u0005[\u0006האם \u0005לא אומר]\u0006 \u0003ר' יוחנן: בתר חזותא אזלינן\u0004 \u0005[אחר המראה הולכים אנו]\u0006 למרות שידוע שיש שם חלב? \u0003הכא נמי זיל בתר חזותא\u0004 \u0005[כאן גם כן,\u0006 במשנתנו, \u0005לך אחר המראה]\u0006 של התמד, והרי גם אם סופו של התמד להחמיץ, מכל מקום כל זמן שלא החמיץ \u0003טעמא וחזותא דהאי מיא נינהו\u0004 \u0005[הטעם והמראה של\u0006 תמד \u0005זה\u0006 של \u0005מים הם],\u0006 ולכן דינו כמים. אבל רב נחמן סבור כדעת התנא הראשון במשנה זו, שלא המראה קובע, וכיון שלבסוף החמיץ והתברר שבשעת לקיחה היה פרי — קנה מעשר. ושבים למחלוקת ר' יהודה וחכמים, במי שנתן מים על גבי פסולת ענבים, ומצא כדי מידתו ולא יותר, שר' יהודה מחייבו במעשר, וחכמים פוטרים. ואמר רב נחמן שהמחלוקת היא בתמד שהחמיץ, אבל אם עדיין לא החמיץ — גם ר' יהודה אינו מחייב לעשרו.","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 דעה זו על דעת \u0003ר' אלעזר,\u0004 ש\u0003אמר ר' אלעזר: הכל מודים,\u0004 וגם ר' יהודה, \u0003שאין מפרישין עליו\u0004 על תמד זה, מעשר \u0003ממקום אחר,\u0004 מתמד אחר, \u0003אלא אם כן החמיץ.\u0004","ומכלל הדברים אתה למד ש\u0003קסבר\u0004 \u0005[סבור הוא]\u0006 ר' אלעזר ש\u0003ב\u0004ש\u0003לא החמיץ\u0004 היא ה\u0003מחלוקת.\u0004 \u0003ו\u0004מוסיף ר' אלעזר כי \u0003עד כאן לא\u0004 שמענו ש\u0003מחייב ר' יהודה\u0004 לעשר את התמד (שעדיין לא החמיץ) \u0003אלא מיניה וביה\u0004 \u0005[ממנו ובו],\u0006 שאם הוא עתיד להחמיץ — הרי זה מעשר, ואם לא — לא עשה ולא כלום. \u0003אבל\u0004 לעשר עליו \u0003מעלמא\u0004 \u0005[מבחוץ],\u0006 מתמד אחר שהחמיץ — \u0003לא,\u0004 והטעם הוא: \u0003דלמא\u0004 \u0005[שמא]\u0006 תמד זה לא יחמיץ, ובכך \u0003אתי לאפרושי\u0004 \u0005[יבוא להפריש]\u0006 \u0003מן החיוב על הפטור ומן הפטור על החיוב.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003התמד\u0004 שנטמא, \u0003עד שלא\u0004 (לפני) ש\u0003החמיץ\u0004 —"],["\u0003משיקו במים,\u0004 שנותן את הכלי ובו התמד במקוה, וכשנושקים מי התמד במי המקוה הריהם נטהרים, כדרך שמטהרים מים שנטמאו. אבל \u0003משהחמיץ\u0004 התמד — \u0003אין משיקו במים\u0004 לטהרו, שרק מים מיטהרים בהשקה, ולא משקים אחרים. \u0003אמר רבא: לא שנו\u0004 שהשקה מועילה לתמד קודם שהחמיץ, \u0003אלא\u0004 במקרה \u0003שתמדו\u0004 (שעשה את התמד) \u0003במים טהורים\u0004 שנתנם על פסולת הענבים, \u0003ו\u0004אחר כך \u0003נטמאו,\u0004 קודם שהחמיץ. \u0003אבל\u0004 אם היו המים \u0003טמאים מעיקרא\u0004 \u0005[מתחילה]\u0006 — \u0003לא\u0004 יועיל דבר זה.","\u0003אזל\u0004 \u0005[הלך]\u0006 \u0003רב גביהה מבי כתיל אמרה לשמעתא קמיה\u0004 \u0005[אמר את השמועה\u0006 הזאת של רבא \u0005לפני]\u0006 \u0003רב אשי,\u0004 ותמה: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 אם היו המים \u0003טמאין מעיקרא\u0004 \u0005[מתחילה]\u0006 ש\u0003לא\u0004 מועילה לתמד ההשקה — מפני \u0003דאמרינן\u0004 \u0005[שאומרים אנו]:\u0006 \u0003איידי דמיא יקירי שכני תתאי, ופירא קפי מלעיל\u0004 \u0005[מתוך שהמים כבדים\u0006 יותר \u0005הם מצויים למטה\u0006 בכלי, \u0005והפרי,\u0006 פסולת היין, \u0005צף מלמעלה],\u0006 \u0003ולא קא סלקא להו השקה למיא\u0004 \u0005[ו\u0006לכן \u0005לא עולה השקה למים],\u0006 שהרי אין מי המקוה נוגעים בהם. \u0003אי הכי\u0004 \u0005[אם כך],\u0006 אם היו המים \u0003טהורים ולבסוף נטמאו נמי\u0004 \u0005[גם כן]\u0006 יהיה בהם אותו דין, שהרי חלק הפרי הוא הצף מלמעלה!","\u0003אלא\u0004 טעם הדבר שמועילה במקרה זה השקה, הוא מפני שאנו מניחים שהם \u0003מבלבלי\u0004 \u0005[מבולבלים]\u0006 ומעורבים יחד, המים והפרי, ולפי זה, \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 כ\u0003שנטמאו תחילה —\u0004 הרי הם \u0003מבלבלי\u0004 \u0005[מבולבלים]\u0006 ומעורבים יחד, ותועיל להם ההשקה!","\u0003כל מקום שיש מכר,\u0004 שרשאי אדם למכור את בתו לשפחה, כלומר, כשהיא קטנה — \u0003אין קנס,\u0004 שאם נאנסה או נתפתתה, אין אביה מקבל את חמשים הכסף האמורים באונס נערה (דברים כב, כט). \u0003וכל מקום שיש קנס,\u0004 כשהיא נערה — \u0003אין\u0004 בו \u0003מכר,\u0004 שאין האב יכול למכור את בתו הנערה.","\u0003אמר רב יהודה אמר רב: זו,\u0004 משנתנו, \u0003דברי ר' מאיר\u0004 היא, \u0003אבל חכמים אמרו: יש\u0004 אפשרות של \u0003קנס\u0004 גם \u0003במקום\u0004 של \u0003מכר. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 בהבהרת מחלוקת זו: \u0003קטנה מבת יום אחד עד שתביא שתי שערות\u0004 במקום הערוה — \u0003יש לה מכר,\u0004 רשאי אביה למכור אותה לאמה, \u0003ואין לה קנס\u0004 אם נאנסה או נתפתתה, משום שעדין אינה בגדר נערה; \u0003משתביא שתי שערות עד שתיבגר,\u0004 ששה חדשים לאחר מכן — \u0003יש לה קנס,\u0004 משום שעדיין היא נערה, \u0003אבל\u0004 \u0003אין לה מכר,\u0004 אלו \u0003דברי רבי מאיר, שהיה רבי מאיר אומר: כל מקום שיש מכר\u0004 — \u0003אין קנס, וכל מקום שיש קנס\u0004 — \u0003אין מכר.\u0004 \u0003וחכמים אומרים: קטנה מבת שלש שנים ויום אחד עד שתיבגר\u0004 — \u0003יש לה קנס.\u0004 ותוהים: \u0003קנס\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 אבל \u0003מכר\u0004 — \u0003לא?\u0004 וכי אי אפשר למכור אותה בגיל הזה? והרי קטנה היא! ומשיבים: \u0003אימא\u0004 \u0005[אמור,\u0006 הסבר\u0005]\u0006 כך: יש לה \u0003אף קנס במקום מכר,\u0004 כלומר, גם מכר וגם קנס. \u0003כל מקום שיש\u0004 בו \u0003מיאון,\u0004 שילדה שהשיאוה אחיה או אמה (ולא אביה) יכולה למאן בבעלה ולצאת ממנו בלא גט, כלומר, כל זמן שהיא קטנה — \u0003אין חליצה,\u0004 שאם מת בעלה בלא בנים, והיא עומדת לפני אחיו ליבום — אינה יכולה לחלוץ. \u0003וכל מקום שיש חליצה,\u0004 משתביא שתי שערות — \u0003אין מיאון,\u0004 שאינה יוצאה מבעלה אלא בגט.","","","","\u0003אמר רב יהודה, אמר רב: זו\u0004 משנתנו \u0003דברי ר' מאיר\u0004 היא, \u0003אבל\u0004 \u0003חכמים אומרים: יש מיאון\u0004 גם \u0003במקום\u0004 שיש \u0003חליצה.\u0004 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003עד מתי הבת ממאנת?\u0004 — \u0003עד שתביא שתי שערות,\u0004 כלומר, כל זמן שהיא קטנה, אלו \u0003דברי ר' מאיר. ר' יהודה אומר:\u0004 אפילו לאחר מכן, \u0003עד שירבה השחור\u0004 במקום הערוה \u0003על הלבן,\u0004 ששער הערוה ניכר, ובשלב זה כבר יכולה לחלוץ, והיא דעת חכמים.","\u0003כל מקום שיש תקיעה\u0004 בערב שבת וחג, כדי להבטיל את העם ממלאכה, ולהבדיל בין קודש לחול — \u0003אין\u0004 בו \u0003הבדלה\u0004 בתפילה ועל הכוס, \u0003וכל מקום שיש הבדלה אין תקיעה.\u0004 כיצד? \u0003יום טוב שחל להיות בערב שבת\u0004 — \u0003תוקעין\u0004 בכניסת השבת, כדי להבטיל את העם ממלאכה המותרת ביום טוב ואסורה בשבת, ולהבדיל בין הקודש לקודש. \u0003ולא מבדילין\u0004 בליל השבת, שאין מבדילים אלא כשיוצאים מקודש לחול, או מקדושה חמורה לקדושה קלה יותר, וקדושת שבת חמורה משל יום טוב. אם חל יום טוב \u0003במוצאי שבת\u0004 — \u0003מבדילין,\u0004 אבל \u0003לא תוקעין\u0004 באותה שבת לקראת חשיכה.","","\u0003כיצד מבדילין\u0004 כשיום טוב חל במוצאי השבת? \u0003\"המבדיל בין קודש לקודש\",\u0004 ולא \"המבדיל בין קודש לחול\" כבכל מוצאי שבת. \u0003ר' דוסא אומר: \"בין קודש חמור לקודש הקל\".\u0004","שנינו שכשיום טוב חל בערב שבת תוקעים להודיע על כניסת השבת. ושואלים: \u0003היכי\u0004 \u0005[איך]\u0006 \u0003תוקע,\u0004 כיצד עושים את התקיעה? \u0003אמר רב יהודה: תוקע ומריע מתוך תקיעה\u0004 זו, כלומר, בתוך התקיעה משנה את הקול לתרועה, \u0003ורב אסי אמר: תוקע ומריע בנשימה אחת,\u0004 שאינו עושה אותן ברצף ממש, אך גם לא מפסיק בנשימה. \u0003אתקין\u0004 \u0005[התקין]\u0006 \u0003רב אסי ב\u0004עיר \u0003הוצל\u0004 לתקוע \u0003כשמעתיה\u0004 \u0005[כפי ההלכה שלו].\u0006","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על רב יהודה ורב אסי, ממה ששנינו בברייתא: \u0003יום טוב שחל להיות בערב שבת\u0004 — \u0003תוקעין ולא מריעין. מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה ש\u0003לא מריעין,\u0004 שאין עושים תרועה \u0003כלל?\u0004 ומשיבים: \u0003לא,\u0004 אלא \u0003רב יהודה מתרץ\u0004 ברייתא זו \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 \u0003ורב אסי מתרץ לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005].\u0006 ומפרטים, \u0003רב יהודה מתרץ לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 כך: \u0003לא מריעין\u0004 תרועה \u0003בפני עצמה, אלא\u0004 מריעים \u0003מתוך תקיעה. ורב אסי מתרץ לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 \u0003לא מריעין בשתי נשימות,\u0004 כלומר לא מפסיקים בין תקיעה לתקיעה בנשימה, כמו בכל ערב שבת, \u0003אלא\u0004 מריעין \u0003בנשימה אחת\u0004 עם התקיעה. שנינו במשנה: \u0003ו\u0004ביום טוב שחל להיות \u0003במוצאי שבת\u0004 מבדילים. ונחלקו חכמים בנוסח הבדלה זו. ושואלים: \u0003היכא אמר לה\u0004 \u0005[היכן אומר אותה]\u0006 את הלשון הזו של ההבדלה? \u0003אמר רב יהודה:\u0004 אומרים אותה \u0003בחתימתה\u0004 של הברכה, אבל את נוסח הברכה עצמה אומר כבכל מוצאי שבת: \"המבדיל בין קודש לחול, בין אור לחושך\" וכו'. \u0003וכן אמר רב נחמן: בחתימתה. ו\u0004אילו \u0003רב ששת בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי אמר: אף בפתיחתה\u0004 אומר כן, במקום הנוסח \"המבדיל בין קודש לחול\". ומעירים: \u0003ולית הלכתא כוותיה\u0004 \u0005[ואין הלכה כמותו].\u0006 ועל מה ששנינו \u0003ש\u0004\u0003רבי דוסא אומר:\u0004 בהבדלה משבת ליום טוב אומר \u0003\"בין קדש חמור לקדש הקל\",\u0004 מעירים: \u0003ולית הלכתא כוותיה\u0004 \u0005[ואין הלכה כמותו].\u0006 \u0003אמר ר' זירא: יום טוב שחל להיות באמצע שבת\u0004 (השבוע), \u0003אומר\u0004 לאחר יום טוב: \u0003\"המבדיל בין קדש לחול ובין אור לחשך ובין ישראל לגוים ובין יום השביעי לששת ימי המעשה\",\u0004 אף על פי שאין זו שבת, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 סדר הבדלות שתיקנו חכמים \u0003הוא מונה,\u0004 ולאו דווקא ההבדלה המיוחדת לאותו יום.","","","","",""],["\u0003השוחט\u0004 סימן \u0003אחד\u0004 קנה או ושט \u0003בעוף, ושנים בבהמה\u0004 — \u0003שחיטתו כשרה. ורובו של אחד כמוהו. רבי יהודה אומר: עד שישחוט את הוורידין,\u0004 כלי הדם הגדולים שבצואר. שחט \u0003חצי\u0004 סימן \u0003אחד בעוף, ואחד וחצי בבהמה\u0004 — \u0003שחיטתו פסולה. רוב אחד בעוף, ורוב שנים בבהמה,\u0004 רובו של כל אחד ואחד — \u0003שחיטתו כשרה.\u0004","ומדייקים בלשון המשנה, ששנינו: \u0003השוחט\u0004 אחד בעוף ושניים בבהמה, ומשמע: ב\u0003דיעבד\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003לכתחלה\u0004 — \u0003לא.\u0004 ותמהים: \u0003שנים בבהמה לכתחלה לא?\u0004 וכי \u0003עד כמה לשחוט וליזיל\u0004 \u0005[ישחוט וילך]?\u0006 והרי אין יותר משנים! ומשיבים, \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 לשון זו מתייחסת לשחיטת סימן \u0003אחד בעוף,\u0004 שלכתחילה צריך לשחוט שנים. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 לשון זו מתייחסת למה שנאמר ש\u0003רובו של אחד כמוהו,\u0004 שהוא רק בדיעבד, אבל לכתחילה צריך לשחוט את כל הסימן.","\u0003(כמ\"ש סימן\u0004 לשמות החכמים להלן: רב \u0003כ\u0004הנא, רב יי \u0003מ\u0004ר, דבי רב י \u0003ש\u0004מעאל","\u0003). אמר רב כהנא: מנין לשחיטה שהיא מן הצואר? שנאמר: \"ושחט את בן הבקר\"\u0004 (ויקרא א, ה), וכך נדרש הכתוב: \"ושחט\" — \u0003ממקום ש\u0004הוא \u0003שח\u0004 = מתכופף — שם \u0003חטהו,\u0004 טהרהו. ושואלים: \u0003ממאי דהאי\u0004 \u0005[מנין\u0006 אנו יודעים \u0005שזה]\u0006 הלשון \u0003\"חטהו\" לישנא דדכויי\u0004 \u0005[לשון טיהור]\u0006 \u0003הוא?\u0004 ומשיבים, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בטהרת צרעת הבתים: \u0003\"וחטא את הבית\"\u0004 (שם יד, כב). \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור],\u0006 \u0003מהכא\u0004 \u0005[מכאן]:\u0006 \u0003\"תחטאני באזוב ואטהר\"\u0004 (תהלים נא, ט), שמפורש הקשר בין חיטוי לטהרה.","ושואלים: אם הכוונה היא ממקום ששח, שמתכופף, \u0003ואימא\u0004 \u0005[ואמור]\u0006 שישחט אותו \u0003מזנבו!\u0004 ומשיבים: \u0003שח\u0004 — \u0003מכלל שזקוף בעינן\u0004 \u0005[צריכים אנו],\u0006 כלומר, דבר שיכול להיות גם זקוף וגם שחוח, \u0003והא\u0004 \u0005[וזה]\u0006 הזנב \u0003שח ועומד הוא,\u0004 כפוף כל הזמן. ומקשים: \u0003ואימא\u0004 \u0005[ואמור]:\u0006 שחיטה \u0003מאזנו\u0004 היא, שלפעמים היא זקופה ולפעמים מכופפת! ומשיבים: \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שיצא \u0003דם הנפש\u0004 בשחיטה, \u0003וליכא\u0004 \u0005[ואין כאן].\u0006 ומקשים: מדוע?","\u0003ואימא\u0004 \u0005[ואמור]:\u0006 \u0003דקרע ואזיל\u0004 \u0005[שקורע והולך]\u0006 מן האוזן \u0003עד\u0004 שמגיע למקום שיוצא \u0003דם הנפש! ותו\u0004 \u0005[ועוד]\u0006 יש לשאול: \u0003שהייה\u0004 באמצע השחיטה, שהיא פוסלת את השחיטה, וכן \u0003דרסה,\u0004 שחותך את הסימנים בלחיצה, \u0003חלדה,\u0004 שתוחב את הסכין בין הסימנים ושוחט, \u0003הגרמה,\u0004 ששוחט מחוץ למקום השחיטה, \u0003ועיקור,\u0004 שעוקר את הסימנים ושוחט, שגם הם חלק מהלכות שחיטה, \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 מן התורה? \u0003אלא\u0004 כל אלה הם \u0003גמרא\u0004 \u0005[מסורת,\u0006 הלכה למשה מסיני\u0005],\u0006 ואם כן צריך אתה לומר ש\u0003שחיטה מן הצואר נמי גמרא\u0004 \u0005[גם כן מסורת\u0006 היא, הלכה למשה מסיני\u0005],\u0006 ואין לה מקור בכתוב.","ושואלים: \u0003ו\u0004אם שחיטה מן הצוואר מסורת בלבד היא, \u0003קרא\u0004 \u0005[המקרא]\u0006 \"ושחט\" \u0003למאי אתא\u0004 \u0005[למה בא]?\u0006 ומשיבים: ללמד \u0003דלא לשוייה גיסטרא\u0004 \u0005[שלא יבתק אותו,\u0006 את הצוואר \u0005לשנים],\u0006 שאינו צריך אלא לחתוך את הסימנים, ולא יותר מכך.","\u0003רב יימר אמר,\u0004 מנין לשחיטה מן הצוואר? ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"וזבחת\u0004 מבקרך ומצאנך\" (דברים יב, כא), ודורשים: \u0003ממקום שזב\u0004 הדם \u0003חתהו\u0004 (שבור, חתוך אותו) כלומר, בצואר. ושואלים: \u0003מאי משמע דהאי\u0004 \u0005[מהיכן משמע שזה]\u0006 הלשון \u0003\"חתהו\" לישנא דמתבר\u0004 \u0005[לשון שבירה]\u0006 \u0003הוא?\u0004 ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אל תירא ואל תחת\"\u0004 (שם א, כא), כלומר, אל תישבר רוחך.","ומקשים: אם ממקום שזב צריך לשחוט, \u0003ואימא\u0004 \u0005[ואמור]\u0006 שישחט \u0003מחוטמו,\u0004 שליחה זבה משם, והרי הכתוב לא הזכיר דם! ומשיבים: \u0003זב על ידי חתוי\u0004 (שבירה, חיתוך) \u0003בעינן\u0004 \u0005[צריכים אנו],\u0006 \u0003והאי\u0004 \u0005[וזה\u0006 החוטם\u0005]\u0006 \u0003זב מאליו הוא.\u0004 ועוד מקשים, \u0003ואימא\u0004 \u0005[ואמור]:\u0006 שישחוט \u0003מלבו,\u0004 שידקור אותו בלבו! ואם כן אין מכאן ראיה. \u0003ותו\u0004 \u0005[ועוד]\u0006 יש לשאול: \u0003שהייה דרסה חלדה הגרמה ועיקור,\u0004 שגם הם חלק מהלכות שחיטה, \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 מן התורה? \u0003אלא\u0004 כל ההלכות הללו הן \u0003גמרא\u0004 \u0005[מסורת,\u0006 הלכה למשה מסיני\u0005],\u0006 ואם כן \u0003שחיטה מן הצואר נמי גמרא\u0004 \u0005[גם כן מסורת]\u0006 היא, ואין לה מקור מן הכתוב.","ושואלים: \u0003ו\u0004לפי זה, \u0003קרא למאי אתא\u0004 \u0005[הכתוב\u0006 \"וזבחת\" \u0005למה בא]?\u0006 ומשיבים: לומר \u0003דלא לשוייה גיסטרא\u0004 \u0005[שלא יבתק אותו,\u0006 את הצוואר \u0005לשנים].\u0006","\u0003דבי\u0004 \u0005[\u0006התנא \u0005מבית מדרשו]\u0006 של \u0003ר' ישמעאל תנא\u0004 \u0005[שנה]\u0006 ראיה אחרת לכך ששחיטה מן הצוואר: \u0003\"ושחט\"\u0004 (ויקרא א, ה) — \u0003אל תקרי\u0004 (תקרא) \u0003\"ושחט\" אלא \"וסחט\", ממקום ש\u0004הוא \u0003סח\u0004 (מדבר) — משם \u0003חטהו,\u0004 \u0003טהר אותו. והרי הקול יוצא מגרונו. ומקשים,\u0004","\u0003ואימא\u0004 \u0005[ואמור]\u0006 שישחט אותו \u0003מלשונו!\u0004 ומשיבים: \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שיצא \u0003דם הנפש\u0004 בשחיטה, \u0003וליכא\u0004 \u0005[ואין כאן]\u0006 כשחותך את הלשון. ושואלים: מדוע לא? \u0003ואימא\u0004 \u0005[ואמור]\u0006 \u0003דקרע ואזיל\u0004 \u0005[שהוא קורע והולך]\u0006 מן הלשון \u0003עד\u0004 שמגיע למקום שיוצא בו \u0003דם הנפש! ותו\u0004 \u0005[ועוד]\u0006 יש לשאול: \u0003שהייה דרסה חלדה הגרמה ועיקור מנלן\u0004 \u0005[מנין לנו]\u0006 שהם פוסלים את השחיטה? \u0003אלא\u0004 דברים אלה נלמדים מ\u0003גמרא\u0004 \u0005[מסורת,\u0006 הלכה למשה מסיני\u0005],\u0006 ואם כן \u0003שחיטה מן הצואר נמי גמרא\u0004 \u0005[גם כן ממסורת].\u0006","ושואלים: אם כן, \u0003וקרא למאי אתא\u0004 \u0005[הכתוב\u0006 ושחט \u0005למה הוא בא]?\u0006 ומשיבים: ללמד \u0003דלא לשוייה גיסטרא\u0004 \u0005[שלא יבתק אותו,\u0006 את הצוואר \u0005לשנים].\u0006","ומעירים: \u0003ותנא מייתי לה מהכא\u0004 \u0005[והתנא,\u0006 שונה הברייתות בבית המדרש, \u0005מביא לה\u0006 ראיה \u0005מכאן],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 בתורת כהנים, \u0003ר' חייא אמר: מנין לשחיטה מן הצואר? שנאמר\u0004 בקרבן העולה מן הבקר: \"וניתח אותה לנתחיה\" (ויקרא א, ו), ואחר כך: \u0003\"וערכו בני אהרן הכהנים את הנתחים\u0004 את הראש ואת הפדר (החלב) וכו' על המזבח\" (ויקרא א, ח),","\u0003שאין תלמוד\u0004 (צורך) \u0003לומר \"את הראש ואת הפדר\",\u0004 ו\u0003מה תלמוד לומר,\u0004 מה בא ללמדנו \u0003\"את הראש ואת הפדר\"? והלא ראש ופדר בכלל כל הנתחים היו,\u0004 ו\u0003למה יצאו?\u0004 אלא, \u0003לפי שנאמר\u0004 מתחילה: \u0003\"והפשיט את\u0004 (עור) \u0003העולה ונתח\u0004 אותה לנתחיה\" (שם ו), יכול אתה לומר: \u0003אין לי\u0004 שצריך לערוך על המזבח \u0003אלא\u0004 אותם \u0003נתחים שישנן בכלל הפשטה,\u0004 שהפשיט מהם את העור מתחילה, \u0003מנין לרבות את הראש, שכבר הותז\u0004 בשחיטה קודם לכן, ואינו בכלל הפשטה, אלא קרב כמות שהוא, שגם אותו עורכים על המזבח? \u0003תלמוד לומר: \"את ראשו ואת פדרו וערך\"\u0004 (שם יב).","ולענייננו, \u0003מדקאמר\u0004 \u0005[ממה ש\u0006ר' חייא \u0005אומר]\u0006 \u0003\"את הראש שכבר הותז\"\u0004 — \u0003מכלל\u0004 הדברים אתה למד שה\u0003שחיטה מן הצואר,\u0004 שהרי שם מותז הראש מן הגוף.","ולגופה של הברייתא תמהים: \u0003ותנא\u0004 \u0005[והתנא],\u0006 כיצד \u0003פתח\u0004 \u0005[הוא פותח]\u0006 \u0003ב\u0004כתוב \u0003\"ראש ופדר\"\u0004 שנאמר בעולה מן הבקר (ויקרא א, ח), \u0003ומסיים ב\u0004כתוב \u0003\"ראשו ופדרו\"\u0004 שנאמר בעולה מן הצאן (שם יב)? ומשיבים: באמת \u0003הכי קאמר\u0004 \u0005[כך\u0006 הוא \u0005אומר],\u0006 כך יש לגרוס בברייתא: \u0003מנין לרבות את הראש שכבר הותז? תלמוד לומר: \"את הראש ואת הפדר\"\u0004 (ולא \"את ראשו ואת פדרו\").","\u0003ו\u0004שואלים: \u0003\"ראשו ופדרו\"\u0004 שהוזכרו בעולה מן הצאן \u0003למה לי?\u0004 והרי כבר למדנו מעולת הבקר, שגם אותם עורכים על המזבח! ומשיבים: \u0003מיבעי ליה לכדתניא\u0004 \u0005[נצרך לו לכמו ששנויה\u0006 בברייתא\u0005]:\u0006 \u0003מנין לראש ופדר שקודמין לכל הנתחים\u0004 בהקרבתם על המזבח? \u0003תלמוד לומר: \"את ראשו ואת פדרו וערך\".\u0004"],["ושואלים: \u0003ופדר קמא\u0004 \u0005[הראשון]\u0006 \u0003דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003למה לי?\u0004 שהרי רק לראש שהוזכר שם הוצרכנו, ללמד שגם הוא טעון עריכה למרות שכבר הותז, אבל הפדר בכלל שאר הנתחים הוא! ומשיבים: \u0003מיבעי ליה לכדתניא\u0004 \u0005[נצרכה לו לכמו ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003כיצד הוא עושה\u0004 כשמעלה את הראש על המזבח? \u0003חופה\u0004 (מכסה) \u0003את הפדר על בית\u0004 (מקום) \u0003השחיטה,\u0004 המקום שבו נחתך הראש, \u0003ו\u0004כך \u0003מעלהו\u0004 על המזבח, \u0003וזהו דרך כבוד של מעלה,\u0004 שאין רואים את הצוואר המלוכלך בדם. ושבים לדיון העיקרי בסוגיה זו, מנין לשחיטה שהיא מן הצוואר.","ומעירים: \u0003והאי תנא מייתי לה מהכא\u0004 \u0005[ותנא זה מביא אותה מכאן],\u0006 ממה שאומר ר' אליעזר בברייתא, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 בסוף הפרשה העוסקת בנבלת הבהמה ונבלת העוף נאמר: \u0003\"זאת תורת הבהמה והעוף\"\u0004 (ויקרא יא, מו), ויש לשאול: \u0003וכי באיזו תורה שוותה בהמה לעוף ועוף לבהמה,\u0004 שהכתוב כורך אותם כאחד? והרי דיניהם שונים; \u0003בהמה\u0004 כשהיא נבילה \u0003מטמאה במגע ובמשא, עוף\u0004 כשהוא נבילה \u0003אינו מטמא במגע ובמשא!\u0004 וכן מצד אחר, \u0003עוף\u0004 שנעשה נבילה \u0003מטמא בגדים\u0004 של האוכל אותו, כשהוא נמצא \u0003ב\u0004\u0003בית הבליעה\u0004 שלו, ואילו \u0003בהמה אינה מטמאה בגדים\u0004 ב\u0003בית הבליעה!\u0004","ואם כן, \u0003באיזו תורה שוותה בהמה לעוף ועוף לבהמה? לומר לך: מה בהמה\u0004 יוצאת מידי טומאת נבילה \u0003בשחיטה\u0004 — \u0003אף עוף בשחיטה.\u0004 ושואלים: \u0003אי\u0004 (אם כן) נאמר גם: \u0003מה להלן\u0004 בבהמה, השחיטה כשרה דווקא \u0003ב\u0004שחיטת \u0003רוב שנים\u0004 (שני סימנים, הקנה והוושט) — \u0003אף כאן,\u0004 בעוף, דווקא \u0003ברוב שנים! תלמוד לומר: \"זאת\"\u0004 למעט, שלא בכל דבר הם שווים.","\u0003ר' אליעזר אומר: באיזו תורה שוותה בהמה לעוף ועוף לבהמה? לומר לך: מה עוף הכשרו\u0004 להקרבה ואכילה הוא \u0003מן הצואר,\u0004 שאמרה התורה בקרבן העוף שצריך למלוק את ראשו, והוא מן הצואר — \u0003אף בהמה הכשרה מן הצואר.\u0004","ויש לשאול: \u0003אי\u0004 (אם כן) שלמדים הכשר בהמה מהכשרו של העוף במליקה, נאמר גם: \u0003מה להלן\u0004 בעוף \u0003\"ממול עורף\",\u0004 כלומר, בצד העורף, מאחור — \u0003אף כאן,\u0004 בבהמה — השחיטה \u0003ממול עורף,\u0004 ולא בגרון? \u0003תלמוד לומר: \"ומלק את ראשו ממול ערפו ולא יבדיל\"\u0004 (ויקרא ה, ח), ומה שנאמר \"ראשו\" בא להדגיש: \u0003ראשו של זה ממול עורף, ואין ראשו של אחר\u0004 (בהמה) \u0003ממול עורף.\u0004","ושואלים: \u0003ור' אליעזר, האי\u0004 \u0005[\u0006הביטוי \u0005הזה]\u0006 \u0003\"זאת\",\u0004 שלדעת התנא הראשון בא למעט את ההשוואה של בהמה לעוף, \u0003מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו]?\u0006 ומשיבים: \u0003אי לאו\u0004 \u0005[אם לא]\u0006 \u0003\"זאת\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 עוד: \u0003מה עוף\u0004 הכשירו \u0003ב\u0004שחיטת \u0003סימן אחד,\u0004 שנאמר בחטאת העוף \"ולא יבדיל\" (שם) — \u0003אף בהמה\u0004 הכשרה \u0003בסימן אחד\u0004 בלבד, על כן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"זאת\"\u0004 לומר שיש הבדל בין עוף לבהמה.","ומעתה דנים במקורו של דין השחיטה בעוף חולין, שנאמר במשנתנו שהכשרו בסימן אחד. \u0003תני\u0004 \u0005[שנה]\u0006 \u0003בר קפרא: \"זאת תורת הבהמה והעוף\u0004 וכל נפש חיה הרומשת במים\" (ויקרא יא, מו) — \u0003הטיל הכתוב לעוף בין בהמה לדגים,\u0004 ואם כן \u0003לחייבו ב\u0004שחיטת \u0003שני סימנין\u0004 כבהמה \u0003אי אפשר\u0004 — \u0003שכבר הוקש\u0004 בכתוב זה \u0003לדגים,\u0004 שאין בהם שחיטה כלל. ומן הצד האחר, \u0003לפוטרו בלא כלום\u0004 כדגים \u0003אי אפשר\u0004 — \u0003שכבר הוקש לבהמה,\u0004 וכאמור לעיל, מפסוק זה עצמו למדנו ששחיטת בהמה היא מן הצואר ובשני סימנים. \u0003הא כיצד הכשרו\u0004 של עוף? \u0003ב\u0004שחיטת \u0003סימן אחד.\u0004","ושואלים: \u0003דגים\u0004 שמניחים בברייתא זו \u0003דלאו\u0004 \u0005[שלא]\u0006 \u0003בני שחיטה נינהו\u0004 \u0005[הם],\u0006 \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"הצאן ובקר ישחט להם אם את כל דגי הים יאסף להם\"\u0004 (במדבר יא, כב), ומכאן ש\u0003באסיפה בעלמא סגי להו\u0004 \u0005[בלבד די להם],\u0006 ואינם צריכים שחיטה.","\u0003אלא מעתה, גבי\u0004 \u0005[אצל]\u0006 \u0003שליו דכתיב\u0004 \u0005[שנאמר]\u0006 בו: \u0003\"ויאספו את השליו\"\u0004 (שם לב), \u0003הכי נמי דלאו\u0004 \u0005[כך גם כן תאמר שאינו]\u0006 \u0003ב\u0004מצות \u0003שחיטה? והא אמרת\u0004 \u0005[והרי אמרת]\u0006 ביחס לכל העופות: \u0003לפוטרו בולא כלום אי אפשר,\u0004 \u0003שכבר הוקש לבהמה!\u0004 ומשיבים: \u0003התם\u0004 \u0005[שם],\u0006 באסיפת השלו, \u0003לא כתיבא\u0004 \u0005[נאמרה]\u0006 \u0003אסיפה במקום\u0004 שהוזכרה \u0003שחיטה דאחריני\u0004 \u0005[של אחרים],\u0006 ולכן האסיפה המוזכרת שם אינה לשם שחיטה. ואילו \u0003הכא כתיבא\u0004 \u0005[כאן,\u0006 בדגים, \u0005כתובה]\u0006 \u0003אסיפה במקום שחיטה דאחריני\u0004 \u0005[של אחרים],\u0006 ומשמע מכך שדי להם באסיפה ולא בשחיטה.","אגב כך מביאים מה ש\u0003דרש עובר\u0004 אורח \u0003גלילאה\u0004 \u0005[מן הגליל]:\u0006 \u0003בהמה שנבראת מן היבשה\u0004 — \u0003הכשרה בשני סימנים, דגים שנבראו מן המים\u0004 — \u0003הכשירן בולא כלום,\u0004 שאינם זקוקים לשחיטה, \u0003עוף שנברא מן הרקק\u0004 (מן הביצה, שלולית) — \u0003הכשרו בסימן אחד. אמר רב שמואל קפוטקאה\u0004 \u0005[מקפוטקיא]:\u0006 \u0003תדע\u0004 שהעופות נבראו מן הרקק, \u0003שהרי עופות יש להן קשקשת ברגליהם, כדגים\u0004 שיש להם קשקשים. ובענין זה מביאים קטע מדיון שהיה בין הגמון (שליט) רומאי לבין רבן יוחנן בן זכאי.","\u0003ועוד שאלו\u0004 אותו הגמון, \u0003כתוב אחד אומר: \"ויאמר אלהים ישרצו המים שרץ נפש חיה ועוף יעופף\"\u0004 (בראשית א, כ) — \u0003אלמא ממיא איברו\u0004 \u0005[מכאן ש\u0006העופות \u0005מן המים נבראו],\u0006 \u0003וכתיב\u0004 \u0005[ו\u0006מצד אחר \u0005נאמר]:\u0006 \u0003\"ויצר ה' אלהים מן האדמה כל חית השדה ואת כל עוף השמים\u0004 ויבא אל האדם לראות מה יקרא לו\" (שם ב, יט), \u0003אלמא מארעא איברו\u0004 \u0005[מכאן שמן הארץ נבראו]!\u0006","\u0003אמר לו\u0004 רבן יוחנן בן זכאי: \u0003מן הרקק נבראו. ראה\u0004 רבן יוחנן את \u0003תלמידיו מסתכלים זה בזה\u0004 ותוהים, \u0003אמר להם: קשה בעיניכם שדחיתי את אויבי בקש\u0004 בטענה כלשהי, אף על פי שאינה אמת. לאמיתו של דבר, אף העופות \u0003מן המים נבראו, ולמה הביאן אל האדם?\u0004 כלומר, למה הוזכרו בפסוק \"ויצר ה' א-לקים מן האדמה... ויבא אל האדם\" — אין זה משום שנבראו גם הם מן האדמה, אלא הוזכרו שם משום שהביאם אל האדם \u0003לקרות להן שם.\u0004","\u0003ויש אומרים: בלשון אחר\u0004 שאמר לתלמידיו \u0003אמר\u0004 רבן יוחנן \u0003לאותו הגמון,\u0004 שהעופות נבראו מן המים. \u0003ובלשון הראשון,\u0004 שנבראו מן הרקק, \u0003אמר להן לתלמידיו, משום דכתיב\u0004 \u0005[שנאמר]\u0006 \"ואת כל עוף השמים\" \u0003על \"ויצר\u0004 ה' א-לקים מן האדמה\", ולא רק בגלל \u0003קריאת השמות.\u0004","ועוד בענין שחיטת העוף, \u0003אמר רב יהודה משום\u0004 \u0005[בשם]\u0006 \u0003ר' יצחק בן פנחס: אין\u0004 דין \u0003שחיטה לעוף מן התורה,\u0004 \u0003שנאמר:\u0004 \"ואיש... אשר יצוד ציד חיה או עוף וכו' ושפך את דמו וכסהו בעפר\" (ויקרא יז, יג), \u0003\"ושפך\"\u0004 — \u0003בשפיכה בעלמא סגי\u0004 \u0005[בלבד די].\u0006","ותוהים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003חיה נמי\u0004 \u0005[גם כן]\u0006 שהוזכרה בפסוק זה, תאמר שאין לה דין שחיטה מן התורה! ומשיבים: \u0003איתקש\u0004 \u0005[הוקשה]\u0006 החיה \u0003לפסולי המוקדשין\u0004 (בהמות קדשים שנפדו) שדינם בשחיטה, כאשר יבואר להלן (כח,א). ושואלים: אם על ההיקש אתה מסתמך, הרי \u0003עוף נמי איתקש\u0004 \u0005[גם כן הוקש]\u0006 \u0003לבהמה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"זאת תורת הבהמה והעוף\"\u0004 (ויקרא יא, מו), והבהמה ודאי דינה מן התורה בשחיטה! ומשיבים: \u0003הא כתיב\u0004 \u0005[הרי נאמר]\u0006 כאן: \u0003\"ושפך את דמו\"\u0004 (ויקרא יז, יג), וכפי שדייקנו מכאן — די בשפיכה בלבד.","ושואלים: \u0003ומאי חזית דשדייה ליה\u0004 \u0005[ומה ראית שאתה זורק אותו,\u0006 את הכתוב הזה\u0005]\u0006 \"ושפך את דמו\" \u0003על עוף? שדייה\u0004 \u0005[הטל אותו]\u0006 על \u0003חיה!\u0004 ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 לפרש אותו על עוף \u0003משום דסליק מיניה\u0004 \u0005[שעלה ממנו],\u0006 שנאמר: \"או עוף, ושפך את דמו\".","\u0003(סימן\u0004 לראיות המובאות בענין זה: \u0003נתנבל\u0004 בידו, צריך ל\u0003דם, במליקה\u0004 בסכין)","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי ר' יצחק בן פנחס ממה ששנינו ביחס למצות כיסוי הדם: \u0003השוחט\u0004 חיה או עוף \u0003ונתנבלה בידו\u0004 השחיטה, או \u0003הנוחר,\u0004 שחותך את הסימנים לאורכם, או \u0003המעקר,\u0004 שעוקר את הסימנים — \u0003פטור מלכסות\u0004 את הדם, מפני שאין זה מכשיר אותם לאכילה, ונאמר שם \"חיה או עוף אשר ייאכל\", שרק באופן זה דמם טעון כיסוי. \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 ש\u0003אין שחיטה לעוף מן התורה,\u0004 הלוא \u0003נחירתו זו היא שחיטתו\u0004 (כלומר, התרתו באכילה), שאין לו דרך שחיטה מסויימת, ואם כן \u0003ליבעי\u0004 \u0005[שיצטרך]\u0006 \u0003כסוי!\u0004 ומשיבים: \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 שמשנה זו נאמרה \u0003בעוף? לא,\u0004 רק \u0003בחיה\u0004 נאמרה, ולגבי חיה אין חולק שיש שחיטה מן התורה. ומציעים:","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נוספת ממה ששנינו בברייתא: \u0003השוחט\u0004 חיה או עוף \u0003וצריך לדם,\u0004 ולא לבעל החיים עצמו — \u0003חייב לכסות\u0004 את הדם. \u0003כיצד הוא עושה,\u0004 אם הוא בכל זאת רוצה להשתמש בדם? \u0003או נוחרו\u0004 את בעל החיים \u0003או עוקרו,\u0004 וכך אינו צריך לכסות את הדם."],["\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן \u0003בעוף, דקא בעי ליה לדמיה ליניכא\u0004 \u0005[שהוא צריך את דמו\u0006 כדי \u0005לטפל בעש]?\u0006 ומכאן שיש לעוף דין שחיטה מן התורה, שאם לא כן, מדוע אם נחרו ייפטר מכיסוי הדם? והרי גם נחירה כשרה בו! ודוחים: \u0003לא\u0004 בעוף מדובר כאן, אלא \u0003בחיה, דקא בעי ליה לדמיה ללכא\u0004 \u0005[שהוא צריך את דמו\u0006 \u0005לצבע אדום],\u0006 ואין מכאן ראיה.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו: \u0003מלק\u0004 הכהן עוף קדשים מן העורף \u0003בסכין,\u0004 ולא בצפורן כפי שציותה התורה — הרי העוף נעשה נבילה, ו\u0003מטמא בגדים\u0004 של האוכלו כשהוא נמצא ב\u0003בית הבליעה\u0004 שלו. \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 ש\u0003אין שחיטה לעוף מן התורה,\u0004 וכל דרך שחותך את הסימנים מוציאה אותה מידי טומאת נבילה, \u0003נהי נמי דכי תבר ליה\u0004 \u0005[גם אם אמנם כאשר\u0006 מולק בסכין ו\u0005שובר]\u0006 מתחילה את ה\u0003שדרה ו\u0004ה\u0003מפרקת\u0004 \u0003הויא לה\u0004 \u0005[נעשתה]\u0006 בכך \u0003טרפה,\u0004 מכל מקום \u0003תהני\u0004 \u0005[תועיל]\u0006 \u0003לה\u0004 ה\u0003סכין\u0004 שחותך בה אחר כך את הסימנים \u0003לטהרה מידי\u0004 טומאת \u0003נבלה!\u0004 אלא מכאן שרק שחיטה כדינה מכשירה את העוף, ולא אופן אחר של חיתוך הסימנים!","ומשיבים: אף שכך היא דעת התנא של משנה זו, מכל מקום \u0003הוא,\u0004 ר' יצחק בן פנחס, ש\u0003אמר\u0004 שאין שחיטה לעוף מן התורה — \u0003כי האי תנא\u0004 \u0005[כדעת תנא זה]\u0006 אמר, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 בענין פסולי המוקדשים (קרבנות שנפל בהם מום ונפדו), \u0003ר' אלעזר הקפר ברבי\u0004 (הגדול) \u0003אומר: מה תלמוד לומר:\u0004 \u0003\"אך כאשר יאכל את הצבי\u0004 ואת האיל כן תאכלנו\" (דברים יב, כב)? \u0003וכי מה למדנו מצבי ואיל מעתה\u0004 לפסולי המוקדשים?","אלא \u0003הרי זה\u0004 (צבי ואיל) \u0003בא ללמד\u0004 על פסולי המוקדשים, \u0003ונמצא למד\u0004 מהם, \u0003מקיש\u0004 (משווה) הכתוב \u0003צבי ואיל,\u0004 שהם חיות ולא בהמות, \u0003לפסולי המוקדשין: מה פסולי המוקדשין\u0004 דינם \u0003בשחיטה,\u0004 כדי להכשירם באכילה, שנאמר בהם \"וזבחת\" (שם כא) — \u0003אף צבי ואיל\u0004 דינם \u0003בשחיטה;\u0004 ומוסיף ר' אלעזר הקפר: \u0003ועוף אין לו\u0004 דין \u0003שחיטה מדברי תורה אלא מדברי סופרים.\u0004","ומעירים: \u0003מאן תנא דפליג עליה\u0004 \u0005[מיהו התנא שחולק עליו]\u0006 על \u0003רבי אלעזר הקפר,\u0004 וסבור שיש שחיטה לעוף מן התורה (כפי שהוכחנו מן המשנה בענין המולק בסכין)? שיטת \u0003רבי היא, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי אומר:\u0004 מה שנאמר \u0003\"וזבחת... כאשר צויתיך\"\u0004 (שם כא) — \u0003מלמד שנצטוה משה\u0004 על הלכות שחיטה, למרות שאינן מפורשות בתורה: \u0003על\u0004 חיתוך \u0003הושט ועל\u0004 חיתוך \u0003הקנה, ועל\u0004 שחיטת \u0003רוב\u0004 סימן \u0003אחד בעוף, ועל\u0004 שחיטת \u0003רוב שנים בבהמה.\u0004","שנינו במשנה שהשוחט סימן \u0003אחד בעוף\u0004 שחיטתו כשרה. \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בדבר, \u0003רב נחמן אמר:\u0004 בכל אחד משני הסימנים מדובר, \u0003או וושט או קנה. רב אדא בר אהבה אמר: וושט\u0004 דווקא \u0003ולא קנה.\u0004 ומסבירים את לשון המשנה לשיטת כל אחד מהם. \u0003רב נחמן אמר או וושט או קנה\u0004 — שהרי סימן \u0003אחד קתני\u0004 \u0005[הוא שונה],\u0006 \u0003אחד כל דהו\u0004 \u0005[כל שהוא,\u0006 איזה שיהיה\u0005].\u0006 ואילו לשיטת \u0003רב אדא בר אהבה\u0004 ש\u0003אמר וושט ולא קנה, מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003אחד\u0004 — \u0003מיוחד,\u0004 והוא הוושט.","\u0003(סימן\u0004 לראיות שמביאה הגמרא: \u0003שחט\u0004 את הגרגרת, שחט \u0003חצאין\u0004 — שני חצאי סימנין, שחט חצי \u0003גרגרת, פגימה\u0004 — היה חצי קנה פגום, \u0003דחטאת העוף\u0004 כיצד מולקים).","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על שיטת רב נחמן ממה ששנינו בברייתא: \u0003שחט את הוושט\u0004 בעוף \u0003ואחר כך נשמטה\u0004 (נעקרה ממקומה) \u0003הגרגרת\u0004 (הקנה) — הרי זו שחיטה \u0003כשרה;\u0004 אם \u0003נשמטה הגרגרת ואחר כך שחט את הוושט\u0004 — \u0003פסולה,\u0004 לפי שמשעה שנשמטה הגרגרת הריהי טריפה. \u0003שחט את הוושט ונמצאת\u0004 ה\u0003גרגרת שמוטה, ואינו יודע אם קודם שחיטה נשמטה אם לאחר שחיטה נשמטה\u0004 — \u0003זה היה מעשה\u0004 שאירע \u0003ואמרו\u0004 חכמים: \u0003כל ספק בשחיטה\u0004 — \u0003פסולה.\u0004 הרי שהתנא מזכיר שחיטה של וושט לבדו, שהיא כשירה, \u0003ואילו שחיטה בגרגרת לא קתני\u0004 \u0005[אינו שונה]!\u0006","ומשיבים: אין זה משום ששחיטת הגרגרת לבדה לא היתה מועילה, אלא התנא מביא מקרה זה דווקא, \u0003משום\u0004 שה\u0003גרגרת עבידא לאישתמוטי\u0004 \u0005[עשויה להישמט],\u0006 מה שאין כן הוושט.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נוספת ממה ששנינו בברייתא: \u0003שחט שני חצאי סימנין בעוף,\u0004 חצי וושט וחצי קנה — \u0003פסולה,\u0004 שצריך לשחוט רובו של סימן אחד לפחות; \u0003ואין צריך לומר\u0004 אם עשה כן \u0003בבהמה,\u0004 שכן בבהמה צריך לשחוט רוב של כל אחד מן הסימנים. \u0003ר' יהודה אומר: בעוף\u0004 אינו כשר \u0003עד שישחוט את הושט ו\u0004גם \u0003את הורידין\u0004 כדי שיצא הדם. הרי שר' יהודה מזכיר וושט דווקא ולא קנה! ומשיבים: גם כאן, אין זה משום ששחיטה בקנה לבדו לא תועיל, אלא הוא ענין של מציאות, \u0003משום\u0004 ש\u0003ושט סמוך לורידין.\u0004","ועוד מציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לשיטת רב נחמן ממה ששנינו בברייתא: \u0003שחט חצי גרגרת, ושהה כדי שחיטה אחרת, וגמר שחיטתו\u0004 — הרי זו \u0003כשרה,\u0004 ואין בזה פסול של שהייה בשחיטה. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן \u0003ב\u0004שחיטת \u0003עוף\u0004 שהכשרו בסימן אחד, \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 ש\u0003גמרה\u0004 את שחיטתו — \u0003גמרה\u0004 את שחיטת ה\u0003גרגרת\u0004 שהיא ראשונה לשחיטה? ומשמע שבשחיטת גרגרת בלבד כשרה! ודוחים: \u0003לא,\u0004 הכוונה היא \u0003בבהמה,\u0004 שצריך לשחוט בה שני סימנים, \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003גמרה\u0004 — \u0003גמרה לשחיטה כולה.\u0004","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו בברייתא: \u0003הרי שהיה חצי\u0004 ה\u0003קנה פגום\u0004 קודם השחיטה, \u0003והוסיף עליו\u0004 חיתוך \u0003כל שהוא וגמרו\u0004 — \u0003שחיטתו כשרה. מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן \u0003ב\u0004שחיטת \u0003עוף, ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003גמרו\u0004 — \u0003גמרו ל\u0004שחיטת רוב \u0003קנה?\u0004 משמע שבזה בלבד השחיטה כשרה! ודוחים: \u0003לא,\u0004 מדובר כאן \u0003בבהמה, ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003גמרו\u0004 — כוונתו \u0003גמרו לוושט\u0004 גם כן.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו בברייתא: \u0003כיצד מולקין חטאת העוף? חותך שדרה ומפרקת בלא רוב בשר עד שמגיע לוושט או לקנה; הגיע לוושט או לקנה\u0004 — \u0003חותך\u0004 בציפורנו \u0003סימן אחד ורוב בשר עמו, ובעולה\u0004 — חותך \u0003שנים\u0004 (שני סימנים) \u0003או רוב שנים.\u0004 הרי זו \u0003תיובתא\u0004 \u0005[קושיה\u0006 חמורה\u0005]\u0006 על דעת \u0003רב אדא בר אהבה,\u0004 שהרי מפורש שם \"או לוושט או לקנה\"! ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה]\u0006 חמורה היא, ונדחו דבריו.","ושואלים: \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה]\u0006 על מחלוקת זו? ותמהים: \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה]?!\u0006 הרי \u0003כדקאמרת\u0004 \u0005[כמו שאמרת],\u0006 שנדחו דברי רב אדא בר אהבה! ואומרים: משם אין הוכחה גמורה, \u0003דלמא שאני התם\u0004 \u0005[שמא שונה שם]\u0006 במליקה, \u0003דאיכא\u0004 \u0005[שיש]\u0006 כבר חיתוך \u0003שדרה ומפרקת\u0004 מתחילה, ודווקא במקרה זה חיתוך הקנה לבדו מועיל כדי לגמור את המליקה, מה שאין כן בשחיטת עוף חולין.","ואם כן, \u0003מאי\u0004 \u0005[מה הדין]?\u0006 ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 מן המסופר \u0003דההוא בר אווזא דהוה בי\u0004 \u0005[שברווז אחד שהיה בבית]\u0006 \u0003רבא אתא כי ממסמס קועיה דמא\u0004 \u0005[בא כאשר היה צווארו מלוכלך בדם],\u0006 \u0005ולא ידעו האם הוא טריפה, שנפסק הקנה או ניקב הוושט,\u0006 \u0003אמר רבא: היכי נעביד\u0004 \u0005[כיצד נעשה]\u0006 בברווז זה?"],["אם \u0003נשחטיה והדר נבדקיה\u0004 \u0005[נשחט אותו ואחר כך נבדוק אותו]\u0006 אם היה בקנה או בוושט נקב שעושה אותו טריפה — \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003במקום\u0004 שהיה ה\u0003נקב קשחיט\u0004 \u0005[הוא שוחט],\u0006 ואם כן, אי אפשר לדעת! אם תאמר שנחתוך את עורו באותו מקום, \u0003ו\u0004\u0003נבדקיה והדר נשחטיה\u0004 \u0005[נבדוק אותו\u0006 את הסימנים \u0005ואחר כך נשחט אותו]\u0006 — \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003רבה: וושט אין לו בדיקה מבחוץ\u0004 מצידו החיצוני, שהוא אדום, ונקב קטן אינו ניכר בו, \u0003אלא\u0004 בדיקתו \u0003מבפנים\u0004 בלבד, שצבעו שם לבן וטיפת דם ניכרת בו!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף בריה\u0004 \u0005[בנו]\u0006 של רבא: \u0003נבדקיה\u0004 \u0005[נבדוק אותו]\u0006 את ה\u0003קנה,\u0004 שאפשר לבדוק מבחוץ האם ניקב ברובו, \u0003ונשחטיה\u0004 \u0005[ונשחט אותו]\u0006 את ה\u0003קנה, ולכשריה\u0004 \u0005[ו\u0006כך \u0005נכשיר אותו]\u0006 את העוף, שהרי די לו בשחיטת סימן אחד, \u0003והדר לפכוה\u0004 \u0005[ואחר כך יהפכו]\u0006 את \u0003ה\u0004\u0003ושט\u0004 כדי לראות את צידו הפנימי, \u0003ולבדקיה\u0004 \u0005[ויבדקו אותו]\u0006 אם היה שם נקב. \u0003אמר רבא: חכים\u0004 \u0005[חכם]\u0006 \u0003יוסף ברי\u0004 \u0005[בני]\u0006 \u0003בטרפות כר' יוחנן.\u0004 ולענייננו נלמד, \u0003אלמא\u0004 \u0005[מכאן]\u0006 שסימן \u0003אחד דקאמר\u0004 \u0005[שהוא אומר]\u0006 במשנה שכשר בעוף, הוא \u0003או האי\u0004 \u0005[זה]\u0006 \u0003או האי\u0004 \u0005[זה],\u0006 או הוושט או הקנה.","שנינו במשנה: השוחט אחד בעוף ושנים בבהמה שחיטתו כשרה וכו'. \u0003ר' יהודה אומר: עד שישחוט\u0004 את הוורידין. \u0003אמר רב חסדא: לא אמר ר' יהודה אלא בעוף, הואיל וצולהו כולו כאחד,\u0004 ולכן צריך לחתוך את הוורידין כדי שיצא דמו, \u0003אבל בהמה, כיון דמנתחה\u0004 \u0005[שחותך אותה]\u0006 \u0003אבר אבר,\u0004 ומולח כדי להוציא את הדם — \u0003לא צריך.\u0004","ושואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 מכאן \u0003דטעמא\u0004 \u0005[שהטעם]\u0006 של \u0003רבי יהודה משום\u0004 איסור \u0003דם הוא,\u0004 שעושה כן רק כדי להוציא את הדם? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005],\u0006 \u0003רבי יהודה אומר: עד שישחוט את הוורידין,\u0004 משמע שהוא חלק מדין השחיטה!","ודוחים, \u0003אימא\u0004 \u0005[אמור]\u0006 שכוונתו: \u0003עד שינקב את הוורידין, ומאי\u0004 \u0005[ומהו]\u0006 לשון \u0003\"עד שישחוט\"\u0004 — \u0003עד שינקוב\u0004 אותם \u0003בשעת שחיטה,\u0004 שאז הדם זורם בוורידים ויוצא מהם.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא: \u0003וורידין בשחיטה, דברי ר' יהודה!\u0004 ודוחים: גם כאן \u0003אימא\u0004 \u0005[אמור]\u0006 שהכוונה היא: \u0003וורידין צריך לנקבן בשעת שחיטה, דברי רבי יהודה.\u0004","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו בברייתא אחרת, \u0003אמרו לו לרבי יהודה: מאחר שלא הוזכרו\u0004 ה\u0003וורידין אלא\u0004 משום שצריך \u0003להוציא מהן\u0004 את ה\u0003דם, מה לי בשחיטה מה לי שלא בשחיטה? מכלל\u0004 הדברים אתה למד ש\u0003רבי יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003בשחיטה\u0004 דווקא!","ודוחים: \u0003הכי קאמרי לה\u0004 \u0005[כך אומרים]\u0006 חכמים לר' יהודה: \u0003מה לי לנקבן בשעת שחיטה, מה לי לנקבן שלא בשעת שחיטה?\u0004 והרי יכול לנקבם מאוחר יותר! ומעירים: \u0003והוא,\u0004 ר' יהודה, \u0003סבר\u0004 \u0005[סבור]:\u0006 \u0003בשעת שחיטה אתי\u0004 \u0005[בא,\u0006 יוצא\u0005]\u0006 ה\u0003דם\u0004 כשמנקבם, משום \u0003דחיים\u0004 \u0005[שהוא חם],\u0006 \u0003שלא בשעת שחיטה לא אתי\u0004 \u0005[לא בא,\u0006 יוצא\u0005]\u0006 \u0003דם,\u0004 משום \u0003דקריר\u0004 \u0005[שהוא\u0006 כבר \u0005קר].\u0006","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה: וורידין ל\u0004שיטת \u0003רבי יהודה,\u0004 אם \u0003שהה בהן\u0004 באמצע ששחטם, או \u0003דרס בהן,\u0004 חתך אותם בלחיצה ולא בהולכה והבאה, \u0003מהו?\u0004 האם שחיטה פסולה היא, שהרי עשה בה שהייה ודרסה?","\u0003אמר ליה ההוא סבא\u0004 \u0005[לו זקן אחד]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רבי אלעזר, ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 כך \u0003אמר ליה ההוא סבא\u0004 \u0005[לו זקן אחד]\u0006 \u0003לרבי אלעזר, הכי\u0004 \u0005[כך]\u0006 \u0003אמר רבי יוחנן: מנקבן\u0004 את הוורידין \u0003בקוץ והן כשרין,\u0004 שאינם חלק מגוף השחיטה.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב חסדא,\u0004 שלא אמר ר' יהודה לשחוט את הוורידים אלא בעוף, ולא בבהמה: \u0003שחט שני חצאי סימנין בעוף\u0004 — \u0003פסול, ואין צריך לומר בבהמה. רבי יהודה אומר: בעוף עד שישחוט את הוושט ואת הוורידין.\u0004","שנינו במשנה: שחט \u0003חצי\u0004 סימן \u0003אחד בעוף\u0004 ואחד וחצי בבהמה — שחיטתו פסולה. \u0003אתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בשאלה הבאה, \u0003רב אמר:\u0004 \u0003מחצה על מחצה\u0004 כלומר, סימן שנשחט חציו בדיוק — דינו \u0003כרוב, רב כהנא אמר: מחצה על מחצה\u0004 — \u0003אינו כרוב.\u0004","ומסבירים את השיטות: \u0003רב אמר מחצה על מחצה\u0004 דינו \u0003כרוב\u0004 — \u0003הכי אמר ליה רחמנא\u0004 \u0005[כך אמר לו הקדוש ברוך הוא]\u0006 \u0003למשה: לא תשייר רובא\u0004 \u0005[אל תשייר רוב]\u0006 סימן שאינו שחוט, וכיון שחתך חצי הרי לא נשאר רוב. \u0003רב כהנא אמר מחצה על מחצה אינו כרוב\u0004 — \u0003הכי אמר ליה רחמנא\u0004 \u0005[כך אמר לו הקדוש ברוך הוא]\u0006 \u0003למשה: שחוט רובא\u0004 \u0005[את הרוב].\u0006","ומביאים ראיות (ו\u0003סימן\u0004 להן: \u0003חצי\u0004 סימן אחד בעוף, דברי רב \u0003קטינא,\u0004 שחט חצי \u0003גרגרת, פגימה\u0004 בחצי קנה).","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 שחט \u0003חצי אחד בעוף, ואחד וחצי בבהמה\u0004 — \u0003שחיטתו פסולה.\u0004 ומעתה, \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003מחצה על מחצה\u0004 דינו \u0003כרוב, אמאי\u0004 \u0005[מדוע]\u0006 \u0003פסול? הא עבד ליה\u0004 \u0005[הרי עשה]\u0006 \u0003רוב!\u0004 ומשיבים: דבר זה פסול \u0003מדרבנן\u0004 \u0005[מדברי סופרים],\u0006 \u0003דלמא לא אתי למעבד פלגא\u0004 \u0005[שמא לא יבוא לעשות\u0006 אפילו \u0005חצי],\u0006 ולכן צריך לעשות יותר.","\u0003אמר רב קטינא, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא לענין כלי חרס שנטמא, שאין לו טהרה אלא בשבירה: חילקו לשנים — החלק הגדול, שהוא רובו, טמא והקטן טהור. \u0003חלקו לשנים והן שוין\u0004 — \u0003שניהם טמאין\u0004 מספק, \u0003לפי שאי אפשר לצמצם,\u0004 לחתוך בדיוק, ובוודאי אחד מהם גדול יותר, אלא שאיננו יודעים איזה מהם; ונדייק מכאן:","\u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003אפשר לצמצם\u0004 — שני החלקים \u0003טהורין.\u0004 אבל אם מחצה נחשב כרוב, וכדברי רב, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003טהורין? זיל הכא איכא רובא\u0004 \u0005[לך לכאן\u0006 — \u0005יש רוב],\u0006 \u0003זיל הכא איכא רובא\u0004 \u0005[לך לכאן\u0006 — \u0005יש רוב]!\u0006","\u0003אמר רב פפא: תרי רובי בחד מנא ליכא\u0004 \u0005[שני רובים בכלי אחד אין\u0006\u0005,\u0006 לא ייתכנו\u0005],\u0006 ולכן אין לדון על מחצה כעל רוב. אבל ביחס לחיתוך קנה או ושט, אם שחט מחצה ייחשב הדבר כאילו שחט רוב, מפני שאין \"רוב\" אחר שסותר אותו.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו: \u0003שחט חצי גרגרת, ושהה בה\u0004"],["\u0003כדי\u0004 פרק זמן של \u0003שחיטה אחרת,\u0004 שהוא שיעור שהייה הפוסלת באמצע שחיטה, \u0003וגמרה\u0004 — \u0003שחיטתו כשרה.\u0004 \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 שדינו של \u0003מחצה על מחצה\u0004 הוא \u0003כרוב,\u0004 הרי כשנשחט חצי הקנה ולא המשיך בשחיטה — \u0003איטרפא לה\u0004 \u0005[נעשתה טריפה]\u0006 הבהמה, כדין פסוקת הגרגרת ברובה (להלן מב,א), ושוב לא תועיל לה שחיטה!","ודוחים: \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 שמדובר כאן \u0003ב\u0004שחיטת \u0003בהמה? לא,\u0004 מדובר \u0003ב\u0004שחיטת \u0003עוף,\u0004 שהכשרו בשחיטת סימן אחד, ולכן השחיטה כשרה \u0003ממה נפשך\u0004 \u0005[מהיכן שתרצה],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 אומר אתה ש\u0003מחצה על מחצה\u0004 דינו \u0003כרוב\u0004 — \u0003הא עביד ליה רובא\u0004 \u0005[הרי עשה\u0006 \u0005כבר את הרוב],\u0006 ועוף כשר ברובו של סימן אחד, ו\u0003אי\u0004 \u0005[אם]\u0006 \u0003מחצה על מחצה אינו כרוב\u0004 — \u0003לא עבד\u0004 \u0005[לא עשה]\u0006 \u0003ולא כלום,\u0004 שאינה טריפה עד שייפגם רובו של הקנה.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נוספת ממה ששנינו בברייתא: \u0003הרי שהיה חצי קנה פגום,\u0004 ושחט \u0003והוסיף עליו כל שהוא וגמרו\u0004 — \u0003שחיטתו כשרה. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 ש\u0003מחצה על מחצה\u0004 דינו \u0003כרוב,\u0004 מדוע תועיל לה השחיטה? הרי משעה שנפגם חציו — \u0003טרפה הויא\u0004 \u0005[היא]!\u0006","\u0003אמר רבא: שאני\u0004 \u0005[שונה]\u0006 הדבר \u0003לענין\u0004 הלכות \u0003טרפה, דבעינן\u0004 \u0005[שצריכים אנו]\u0006 \u0003רוב הנראה לעינים,\u0004 וכשחצי קנה בדיוק פגום אין זה רוב הנראה לעיניים. אבל לענין שחיטה אין צריך רוב הנראה לעינים, ולכן השוחט מחצה דינו כשוחט רוב.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 ולפי דבריך, \u0003ולא כל\u0004 ש\u0003כן הוא? ומה\u0004 לענין \u0003טרפה,\u0004 שיש מקרים שאפילו \u0003במשהו מיטרפא\u0004 \u0005[\u0006היא \u0005נעשית טריפה],\u0006 וכגון כשיש נקב קטן בוושט או בריאה, בכל זאת אומר אתה: \u0003היכא דבעינן רובא\u0004 \u0005[במקום שצריכים אנו רוב]\u0006 — \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיה \u0003רוב הנראה לעינים;\u0004 לענין \u0003שחיטה, דעד דאיכא רובא לא מיתכשרא\u0004 \u0005[שעד שיש רוב\u0006 סימן שחוט \u0005אינה מוכשרת]\u0006 — \u0003לא כל שכן דבעינן\u0004 \u0005[שצריכים אנו]\u0006 \u0003רוב הנראה לעינים?\u0004","\u0003אלא\u0004 יש לחזור ממה שאמרנו, ולומר \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל],\u0006 וגם לדעת רב, לענין שחיטה \u0003מחצה על מחצה אינו כרוב, וכי איתמר\u0004 \u0005[וכאשר נאמרה]\u0006 מחלוקת זו של \u0003רב ו\u0004של \u0003רב כהנא\u0004 — \u0003לענין\u0004 קרבן \u0003פסח אתמר\u0004 \u0005[נאמר],\u0006 שאם היו רוב ישראל טמאים — הפסח מוקרב ונאכל בטומאה (גם על ידי המועטים), ואם היו רוב ישראל טהורים — הטהורים לבדם עושים את הפסח בזמנו, והטמאים עושים פסח שני.","\u0003הרי שהיו ישראל\u0004 בערב הפסח \u0003מחצה טהורים ומחצה טמאים\u0004 — \u0003רב אמר: מחצה על מחצה\u0004 דינו לענין זה \u0003כרוב,\u0004 ולכן כולם עושים את הפסח בזמנו, הטהורים עושים אותו בטהרה, כאילו היו רוב טהורים, והטמאים עושים בטומאה, כאילו היו רוב טמאים. \u0003ורב כהנא אמר: מחצה על מחצה אינו כרוב,\u0004 ולכן הטהורים עושים את הראשון בטהרה, והטמאים עושים פסח שני, כדין יחידים שנטמאו.","ושואלים: \u0003והתם מאי טעמא\u0004 \u0005[ושם מה הטעם]\u0006 של \u0003רב,\u0004 שהוא נותן למחצה דין רוב, ואין הטמאים נדחים לפסח שני? ומשיבים, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בדין הפסח השני: \u0003\"איש איש כי יהיה טמא לנפש\"\u0004 (במדבר ט, י), לומר ש\u0003איש,\u0004 כלומר, יחיד, \u0003נדחה\u0004 לפסח שני, \u0003ואין ציבור נדחין,\u0004 ואותם מחצה טמאים, אינם נחשבים כיחידים, אלא כציבור.","שנינו במשנה: שחט \u0003רוב\u0004 סימן \u0003אחד בעוף\u0004 ורוב שנים בבהמה שחיטתו כשרה. ושואלים: והרי \u0003תנינא חדא זימנא\u0004 \u0005[\u0006כבר \u0005שנינו פעם אחת]\u0006 בתחילת המשנה: \u0003רובו של אחד כמוהו!\u0004","\u0003(הכש פשח סימן\u0004 לשמות האמוראים להלן: רב \u0003ה\u0004ושעיה, רב \u0003כ\u0004הנא, רב \u0003ש\u0004ימי, רב \u0003פ\u0004 פא, רב \u0003א\u0004 שי","\u0003) אמר רב הושעיא:\u0004 היה הדבר צריך להיאמר פעמיים, \u0003חדא\u0004 \u0005[\u0006פעם \u0005אחת]\u0006 \u0003בחולין וחדא\u0004 \u0005[ו\u0006פעם \u0005אחת]\u0006 \u0003בקדשים. וצריכא\u0004 \u0005[וצריך]\u0006 שייאמרו שניהם, \u0003דאי אשמועינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 ב\u0003חולין,\u0004 היינו אומרים: \u0003התם הוא דסגי ליה ברובא\u0004 \u0005[שם הוא שדי ברוב],\u0006 \u0003משום דלאו\u0004 \u0005[שלא]\u0006 \u0003לדם הוא צריך,\u0004 אלא רק למעשה השחיטה, \u0003אבל קדשים,\u0004 ש\u0003לדם הוא צריך,\u0004 כדי לזרוק אותו על המזבח — \u0003אימא לא תיסגי ליה ברובא עד דאיכא כוליה\u0004 \u0005[אמור שלא יהיה לו די ברוב עד שיש\u0006 שחיטה של \u0005כולו].\u0006","ולהיפך, \u0003ואי אשמועינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 ב\u0003קדשים,\u0004 היינו אומרים שדווקא שם צריך לשחוט רוב סימן, \u0003משום\u0004 ש\u0003לדם הוא צריך, אבל חולין\u0004 ש\u0003לדם לא צריך\u0004 — \u0003אימא בפלגא סגי ליה\u0004 \u0005[אמור שבחצי\u0006 סימן \u0005די לו],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 בשניהם שרובו של סימן כמוהו.","ושואלים: לפי הסבר זה, \u0003הי\u0004 \u0005[איזה]\u0006 מחלקי המשנה עוסק \u0003בחולין והי\u0004 \u0005[ואיזה]\u0006 \u0003בקדשים?\u0004","\u0003אמר רב כהנא: מיסתברא רישא\u0004 \u0005[מסתבר\u0006 לומר שב\u0005תחילה]\u0006 מדובר \u0003בחולין וסיפא\u0004 \u0005[ובסוף]\u0006 \u0003בקדשים. ממאי\u0004 \u0005[ממה]\u0006 אתה למד זאת? \u0003מדקתני\u0004 \u0005[ממה שהוא שונה]\u0006 בתחילת המשנה \u0003\"השוחט\u0004 אחד בעוף ושנים בבהמה\", \u0003ואי סלקא דעתך רישא\u0004 \u0005[ואם עולה בדעתך\u0006 שב\u0005תחילה]\u0006 מדובר \u0003בקדשים, \"המולק\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]\u0006 על העוף, שהרי דינו של עוף קדשים במליקה דווקא!","ומקשים: \u0003אלא מאי\u0004 \u0005[מה]\u0006 אתה אומר, \u0003סיפא\u0004 \u0005[\u0006שה\u0005סוף]\u0006 מדבר \u0003בקדשים?\u0004 הרי מה שנאמר שם: \u0003\"רוב אחד בעוף ורוב שנים בבהמה\u0004 \u0003שחיטתו כשרה\", \"מליקתו כשרה\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]\u0006 על העוף! ומשיבים: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה],\u0006 \u0003איידי דסליק\u0004 \u0005[מתוך שעלה,\u0006 יצא\u0005]\u0006 \u0003מבהמה,\u0004 שהוא שונה: \"רוב אחד בעוף ורוב שנים בבהמה\" — \u0003תנא נמי\u0004 \u0005[שנה גם כן]:\u0006 \u0003\"שחיטתו כשרה\". אלא רישא\u0004 \u0005[בתחילה],\u0006 \u0003מכדי\u0004 \u0005[הואיל]\u0006 ו\u0003על עוף קאי\u0004 \u0005[הוא עומד,\u0006 מתייחס\u0005],\u0006 שבו הוא פותח את המשנה: \"השוחט אחד בעוף ושנים בבהמה\", \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 שמדובר \u0003בקדשים, \"המולק\u0004 אחד בעוף ושוחט שנים בבהמה\" \u0003מיבעי ליה\u0004 \u0005[צריך לו\u0006 לומר\u0005]!\u0006 אלא מכאן שחלק זה של המשנה עוסק בחולין.","\u0003רב שימי בר אשי אמר:\u0004 מה שה\u0003רישא\u0004 \u0005[ההתחלה]\u0006 של המשנה עוסקת \u0003בחולין\u0004 נלמד \u0003מהכא\u0004 \u0005[מכאן],\u0006 \u0003דקתני\u0004 \u0005[שהוא שונה]\u0006 בה: סימן \u0003אחד בעוף, ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 שמדובר \u0003בקדשים\u0004 — \u0003הא איכא\u0004 \u0005[הרי יש]\u0006 \u0003עולת העוף, דבעי\u0004 \u0005[שצריך]\u0006 למלוק בה \u0003שני סימנים!\u0004","ודוחים: \u0003אלא\u0004 לפי טעם זה, \u0003מאי\u0004 \u0005[מה]\u0006 אתה אומר, \u0003סיפא\u0004 \u0005[בסוף]\u0006 מדובר \u0003בקדשים?\u0004 הרי נאמר שם \u0003רוב אחד בעוף,\u0004 וכי די בכך? \u0003הא איכא\u0004 \u0005[הרי יש]\u0006 \u0003עולת העוף דבעי\u0004 \u0005[שצריך]\u0006 למלוק בה \u0003שני סימנין!\u0004 ומשיבים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"רוב אחד\"\u0004 — \u0003רוב\u0004 של \u0003כל אחד ואחד\u0004 מן הסימנים בעוף. ומוסיפים: \u0003ובדין הוא דליתני\u0004 \u0005[שהיה צריך לשנות]\u0006 במפורש \u0003רוב שנים,\u0004 ואולם, \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 \u0003חטאת\u0004 העוף \u0003דסגי ליה בחד סימן\u0004 \u0005[שדי לו ב\u0006חיתוך \u0005סימן אחד]\u0006 — \u0003משום הכי לא פסיקא ליה\u0004 \u0005[משום כך לא פסוק,\u0006 חתוך \u0005לו]\u0006 הדבר, לשנות רוב שנים, אלא שנה באופן שניתן להבינו גם בסימן אחד וגם בשנים.","\u0003רב פפא אמר:\u0004 מה ש\u0003רישא\u0004 \u0005[תחילת]\u0006 המשנה עוסקת \u0003בחולין\u0004 נלמד \u0003מהכא\u0004 \u0005[מכאן],\u0006 \u0003דקתני\u0004 \u0005[שהוא שונה]\u0006 שם, \u0003רבי יהודה אומר: עד שישחוט את הורידין, ו\u0004מכלל הדברים אתה למד ש\u0003פליגי רבנן עליה\u0004 \u0005[חלוקים חכמים עליו],\u0006 ואינם מצריכים לשחוט את הוורידים. ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 שמדובר \u0003בחולין\u0004 — \u0003שפיר\u0004 \u0005[יפה],\u0006 מובן הדבר. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שמדובר \u0003בקדשים, אמאי פליגי רבנן עליה\u0004 \u0005[מדוע חלוקים חכמים עליו]?\u0006 הלוא \u0003הוא עצמו,\u0004 השוחט את הקדשים, \u0003לדם הוא צריך,\u0004 כדי לזורקו על המזבח!","\u0003רב אשי אמר:\u0004 מה ש\u0003סיפא\u0004 \u0005[סופה]\u0006 של המשנה עוסק \u0003בקדשים\u0004 נלמד \u0003מהכא\u0004 \u0005[מכאן],\u0006 \u0003דקתני\u0004 \u0005[שהוא שונה]\u0006 בהמשך למשנה זו: \u0003השוחט שני ראשין כאחד\u0004 — \u0003שחיטתו כשרה.\u0004 ונדייק: לשון \u0003השוחט,\u0004 משמעה: ב\u0003דיעבד\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 אבל \u0003לכתחלה\u0004 — \u0003לא.\u0004","ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 שמדובר \u0003בקדשים\u0004 — \u0003היינו\u0004 \u0005[זה הטעם]\u0006 ש\u0003לכתחלה לא\u0004 — \u0003משום\u0004 מה \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רב יוסף\u0004 בברייתא: מה שנאמר בשחיטת קדשים \"לרצונכם תזבחהו\" (ויקרא יט, ה), יש בו שני ציוויים: \u0003\"תזבח\"\u0004 — \u0003שלא יהא שנים שוחטים זבח אחד, \"תזבחהו\"\u0004 \u0003—\u0004 \u0003שלא יהא אחד שוחט שני זבחים\u0004 כאחד,","\u0003ו\u0004בפירוש דרשה זו \u0003אמר רב כהנא:\u0004 אף שהקרי הוא \"תזבחוהו\" בלשון רבים, \u0003\"תזבחהו\" כתיב\u0004 \u0005[כתוב].\u0006 \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שתחילת המשנה עוסקת \u0003בחולין\u0004 — \u0003אפילו לכתחלה נמי\u0004 \u0005[גם כן]\u0006 יכולים שנים לשחוט כאחד!","ומוסיפים: \u0003ואף ר' שמעון בן לקיש סבר\u0004 ש\u0003רישא\u0004 \u0005[תחילת\u0006 המשנה\u0005]\u0006 עוסקת \u0003בחולין וסיפא\u0004 \u0005[וסופה]\u0006 \u0003בקדשים.\u0004 ש\u0003אמר ר' שמעון בן לקיש: מאחר ששנינו\u0004 בתחילת המשנה \u0003רובו של אחד כמוהו, למה שנינו\u0004 שוב: \u0003רוב אחד בעוף ורוב שנים בבהמה?\u0004","ומסביר, \u0003לפי ששנינו\u0004 במסכת יומא, בעבודת הכהן הגדול ביום הכפורים: \u0003הביאו לו את התמיד, קרצו\u0004 (שחטו) אבל לא השלים את השחיטה, אלא שחט רוב שנים, \u0003ומירק\u0004 (גמר) כהן \u0003אחר שחיטתו על ידו\u0004 (עבורו), \u0003יכול\u0004 אם \u0003לא מירק\u0004 אחר את השחיטה \u0003יהא\u0004 הזבח \u0003פסול? לכך שנינו\u0004 בסוף המשנה שלנו: שחט \u0003רוב אחד בעוף ורוב שנים בבהמה\u0004 שחיטתו כשרה. הרי שגם לדעתו סוף המשנה עוסק בקדשים.","כיון שהזכרנו את דברי ריש לקיש דנים בהם: \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003יכול לא מירק יהא פסול?\u0004"],["ותמהים: איך אפשר היה לומר זאת? \u0003אם כן,\u0004 שאי אפשר בלא המירוק, \u0003הויא ליה\u0004 \u0005[תהיה זאת]\u0006 \u0003עבודה באחר,\u0004 שאינו כהן גדול, \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003כל עבודת יום הכפורים אינן כשרות אלא בו\u0004 בכהן הגדול!","ומסבירים: \u0003הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003יכול\u0004 אם לא מירק \u0003יהא פסול מדרבנן\u0004 \u0005[מדברי סופרים]?\u0006 \u0003דסלקא דעתך אמינא\u0004 \u0005[שהיה עולה על דעתך לומר]:\u0006 \u0003איכא\u0004 \u0005[יש]\u0006 גם \u0003פסול מדרבנן\u0004 \u0005[מדברי חכמים]\u0006 בדברים אלה, \u0003לכך\u0004 חזרנו ו\u0003שנינו\u0004 במשנתנו: \u0003רוב אחד בעוף ורוב שנים בבהמה\u0004 שחיטתו כשרה. ושואלים: \u0003ומאחר\u0004 ש\u0003אפילו פסולא דרבנן ליכא\u0004 \u0005[פסול מדברי חכמים אין כאן],\u0006 \u0003למה לי למרק\u0004 באחר? ומשיבים: \u0003מצוה\u0004 לכתחילה \u0003למרק,\u0004 לסיים את השחיטה.","\u0003אמר ר' שמעון בן לקיש משום לוי סבא\u0004 \u0005[הזקן]:\u0006 \u0003אינה לשחיטה אלא בסוף\u0004 כלומר, רק גמר השחיטה הוא הקרוי שחיטה. \u0003ורבי יוחנן אמר: ישנה לשחיטה מתחלה ועד סוף\u0004 שמ \u0003תחילת השחיטה עד סיומה —\u0004 הכל קרוי שחיטה.","ובהגדרת תחום המחלוקת המדוייק, \u0003אמר רבא: הכל מודים, היכא\u0004 \u0005[במקום]\u0006 ש\u0003שחט\u0004 בבהמה \u0003סימן אחד גוי,\u0004 \u0003ו\u0004אחר כך שחט \u0003סימן אחד ישראל\u0004 — \u0003שהיא פסולה,\u0004 גם אם נאמר שאינה לשחיטה אלא בסוף, ומדוע? \u0003שהרי\u0004 כשבא ישראל לשחוט כבר \u0003נעשה בה מעשה טרפה ביד גוי,\u0004 שכיון ששחיטתו פסולה עשאה בכך טריפה.","וכן \u0003בעולת העוף\u0004 שצריך למלוק בה שני סימנים, \u0003נמי\u0004 \u0005[גם כן],\u0006 \u0003היכא דמליק\u0004 \u0005[במקום שהוא מולק]\u0006 בתחילה \u0003סימן אחד למטה\u0004 מאמצע המזבח, וכדין חטאת העוף, \u0003ו\u0004אחר כך מולק \u0003סימן אחד למעלה,\u0004 כדין עולת העוף — \u0003פסולה\u0004 העולה, גם למי שסבור שאינה לשחיטה (ולמליקה) אלא בסוף, \u0003שהרי עשה בה מעשה חטאת העוף\u0004 \u0003למטה,\u0004 ובכך נפסלה לעולה.","\u0003לא נחלקו אלא כגון ששחט\u0004 בקדשים \u0003סימן אחד בחוץ\u0004 (מחוץ למקדש) \u0003וסימן אחד בפנים,\u0004 ובזה יש משמעות למחלוקת: \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003ישנה לשחיטה מתחלה ועד סוף\u0004 — הרי הוא \u0003מיחייב\u0004 \u0005[מתחייב]\u0006 על תחילת השחיטה משום שחיטת קדשים בחוץ, ואילו \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003אינה לשחיטה אלא בסוף\u0004 — \u0003לא מיחייב\u0004 \u0005[אינו מתחייב],\u0006 משום שסוף השחיטה שהוא הקובע נעשה בפנים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה בר שימי: מר\u0004 \u0005[החכם]\u0006 \u0003לא אמר הכי\u0004 \u0005[כך],\u0006 \u0003ומנו\u0004 \u0005[ומי הוא]\u0006 חכם זה? \u0003רב יוסף,\u0004 שהוא אומר: \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003שחט סימן אחד בחוץ וסימן אחד בפנים\u0004 — \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003פסול\u0004 כלומר, חייב משום שחיטת חוץ, ולדעת הכל, \u0003שהרי עשה בה מעשה חטאת העוף בחוץ,\u0004 שהכשרה של חטאת העוף בסימן אחד.","\u0003לא נחלקו אלא כגון ששחט מיעוט\u0004 שני ה\u0003סימנין בחוץ וגמרו בפנים, למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003ישנה לשחיטה מתחלה ועד סוף\u0004 — \u0003מיחייב\u0004 \u0005[מתחייב]\u0006 משום שחיטת חוץ, שהרי כל שלב של השחיטה קרוי שחיטה להתחייב עליו, אבל \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003אינה לשחיטה\u0004 \u0003אלא בסוף\u0004 — \u0003לא מיחייב\u0004 \u0005[אינו מתחייב],\u0006 שהרי הסוף היה במקום הראוי.","\u0003מתיב\u0004 \u0005[מקשה על כך]\u0006 \u0003רבי זירא\u0004 ממה ששנינו: \u0003כל העסוקין ב\u0004מלאכת ה\u0003פרה\u0004 אדומה \u0003מתחלה ועד סוף\u0004 — \u0003מטמאין בגדים\u0004 שהם נוגעים בהם באותה שעה, \u0003ופוסלין אותה\u0004 את הפרה \u0003במלאכה אחרת\u0004 שהם עושים בשעה שהם עוסקים בה.","ומפרטים: אם \u0003אירע בה פסול בשחיטתה\u0004 — \u0003בין קודם פסולה\u0004 (קודם שנפסלה) \u0003בין לאחר פסולה אינה מטמאה בגדים\u0004 של העוסקים בה, שכל עוד לא נשחטה אינה קרויה פרה אדומה לטמא את העוסקים בה. אבל אם אירע פסול \u0003בהזאתה,\u0004 כשהיזה מדמה כנגד פתחו של ההיכל, הרי \u0003קודם פסולה\u0004 (קודם שנפסלה) — \u0003מטמאה בגדים\u0004 של אלו שעסקו בה באותה שעה, \u0003לאחר פסולה\u0004 — שוב \u0003אינה מטמאה בגדים,\u0004 שרק פרה כשרה מטמאה את העוסקים בה.","\u0003ו\u0004מעתה, \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 ש\u0003ישנה לשחיטה מתחלה ועד סוף,\u0004 וכל שלב שבה קרוי שחיטה — \u0003לפלוג נמי\u0004 \u0005[שיחלק גם כן]\u0006 \u0003בשחיטתה\u0004 כמו בהזאה: \u0003אירע בה פסול בשחיטה\u0004 — \u0003קודם פסולה מטמאה בגדים,\u0004 שהרי נעשתה בה שחיטה, \u0003לאחר פסולה\u0004 — \u0003אינה מטמאה בגדים!\u0004","\u0003אמר רבא: נתקלקלה שחיטה קאמרת\u0004 \u0005[אומר אתה]?\u0006 \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 \u0003דאגלאי מלתא\u0004 \u0005[שהתגלה הדבר]\u0006 \u0003למפרע דלאו\u0004 \u0005[שלא]\u0006 \u0003שחיטה היא כלל,\u0004 ולכן אינה מטמאה.","\u0003אמר רבא: אי קשיא\u0004 \u0005[אם קשה]\u0006 \u0003לי\u0004 ממשנה זו בענייננו — \u0003הא קשיא\u0004 \u0005[\u0006דבר \u0005זה קשה]\u0006 \u0003לי: למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003אינה לשחיטה אלא בסוף, לפלוג\u0004 \u0005[שיחלק]\u0006 אפילו \u0003בהכשרה\u0004 של ה\u0003פרה\u0004 כלומר, כשלא נפל בה פסול, \u0003כגון\u0004 ש\u0003שחטוה בתרי גברי\u0004 \u0005[בשני אנשים],\u0006 זה התחיל וזה סיים, \u0003דגברא קמא\u0004 \u0005[ש\u0006את \u0005האיש הראשון]\u0006 \u0003לא מטמאה\u0004 הפרה, שהרי לפי שיטה זו לא נעשתה בה עדיין שחיטה, \u0003וגברא בתרא\u0004 \u0005[ו\u0006את \u0005האיש האחרון]\u0006 \u0003מטמאה!\u0004","\u0003אמר רב יוסף: תרי גברי בחד זיבחא קאמרת\u0004 \u0005[שני אנשים בזבח אחד אתה אומר]?\u0006 \u0003בר מיניה דההוא\u0004 \u0005[חוץ מ\u0006ענין \u0005זה],\u0006 שאין להביא ממנו ראיה, מפני שאין עושים כן בקדשים, ולא בפרה אדומה שדינה לענין זה כקדשים, \u0003דתנינא\u0004 \u0005[ששנינו]\u0006 על הכתוב \"לרצונכם תזבחוהו\" (ויקרא יט, ה): \u0003\"תזבח\"\u0004 שנאמר בציווי זה — כוונתו \u0003שלא יהו שנים שוחטין זבח אחד, \"תזבחהו\"\u0004 — \u0003שלא יהא אחד שוחט שני זבחים,\u0004 אלא זבח אחד בלבד.","\u0003ואמר רב כהנא:\u0004 טעם הדבר שדורשים את הכתוב כמצוה על היחיד — מפני ש\u0003\"תזבחהו\"\u0004 בלשון יחיד \u0003כתיב\u0004 \u0005[כתוב],\u0006 למרות שהוא נקרא \"תזבחוהו\".","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: לאו אתמר עלה\u0004 \u0005[\u0006וכי \u0005לא נאמר עליה]\u0006 על ברייתא זו, \u0003אמר רבה בר בר חנה אמר רבי יוחנן: זו\u0004 הברייתא היא \u0003דברי רבי אלעזר ברבי שמעון\u0004"],["\u0003סתימתאה\u0004 \u0005[הסתום,\u0006 שדבריו נאמרו בסתם\u0005]\u0006 בלא הזכרת שמו, \u0003אבל חכמים אומרים: שנים שוחטים זבח אחד,\u0004 ולשיטתם עומדת הקושיה בעינה: אם אין שחיטה אלא לבסוף מדוע לא תחלק המשנה בשחיטת פרה אדומה על ידי שנים, שהפרה מטמאה את האחרון ששחטה, ולא את הראשון!","\u0003ו\u0004כן \u0003ל\u0004דעת \u0003רבי אלעזר ברבי שמעון,\u0004 הסבור שאין שנים שוחטים זבח אחד, \u0003נמי לפלוג\u0004 \u0005[גם כן נחלק]\u0006 בשחיטה עצמה, \u0003כגון\u0004 ש\u0003שחט חד גברא\u0004 \u0005[אדם אחד]\u0006 \u0003בשני סודרים,\u0004 שלאחר שהתחיל לשחוט פשט את סודרו ולבש סודר אחר, \u0003דסודר קמא\u0004 \u0005[ש\u0006את \u0005הסודר הראשון]\u0006 \u0003לא מטמא, ו\u0004את ה\u0003סודר בתרא\u0004 \u0005[האחרון]\u0006 \u0003מטמא,\u0004 שהרי אינה לשחיטה אלא בסוף! \u0003אלא\u0004 צריך לומר כי ברייתא זו, רק \u0003בפסולא\u0004 של \u0003פרה קא מיירי\u0004 \u0005[הוא עוסק],\u0006 כשאירע בה פסול, אבל \u0003בהכשרה\u0004 כשהיא נעשית בכשרות \u0003לא קא מיירי\u0004 \u0005[אינו עוסק],\u0006 ואין מכאן ראיה.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב אידי בר אבין\u0004 על השיטה שאינה לשחיטה אלא לבסוף, ממה ששנינו בענין השוחט את קרבן הפסח על החמץ (כשחמץ ברשותו), שאם שחטו לשמו ובזמנו, בערב פסח אחר חצות — לוקה משום \"לא תזבח על חמץ דם זבחי\" (שמות כג, יח), ואם שחטו שלא לשמו, ובכך פסלו — פטור משום שחיטה על החמץ. \u0003ו\u0004אם שחטו על החמץ \u0003במועד\u0004 כלומר, בחג הפסח, הרי אם שחטו \u0003לשמו\u0004 — \u0003פטור,\u0004 מפני שקרבן פסח פסול הוא, שנשחט לאחר זמנו. אבל אם שחטו \u0003שלא לשמו,\u0004 אלא לשם קרבן שלמים — \u0003חייב,\u0004 מפני שהוא כשר כקרבן שלמים, ובשעת איסור חמץ נאסר לשחוט כל קרבן כשחמץ ברשותו.","\u0003והוינן\u0004 \u0005[והיינו עוסקים,\u0006 מתקשים\u0005]\u0006 \u0003בה:\u0004 יש לדייק מכאן כי \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 כששחט אותו במועד במפורש \u0003שלא לשמו\u0004 — חייב, \u0003הא סתמא\u0004 \u0005[הרי\u0006 אם שחט \u0005אותו סתם]\u0006 בלי לפרש — \u0003פטור,\u0004 וכדין פסח שנשחט לאחר זמנו;","\u0003ואמאי\u0004 \u0005[ומדוע]\u0006 \u0003פטור?\u0004 הלוא קרבן \u0003פסח\u0004 שנעשה בסתם \u0003בשאר ימות השנה\u0004 שלא בערב פסח — קרבן \u0003שלמים הוא,\u0004 והרי גם אם שחט שלמים על החמץ בשעת איסורו, עובר על \"לא תשחט על חמץ\"! \u0003שמע מינה\u0004 \u0005[\u0006האם \u0005נלמד מכאן]\u0006 ש\u0003פסח בשאר ימות השנה בעי\u0004 \u0005[צריך]\u0006 \u0003עקירה\u0004 משמו הראשון, שיאמר שהוא מקריבו לשלמים, כדי להחשיבו כקרבן שלמים?","\u0003ואמר ר' חייא בר גמדא, נזרקה\u0004 תשובה \u0003מפי\u0004 ה\u0003חבורה\u0004 של החכמים שעסקו בדבר, \u0003ו\u0004כך \u0003אמרו:\u0004 אין מכאן ראיה, שכן \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה עוסקים אנו]?\u0006 \u0003כגון שהיו\u0004 ה\u0003בעלים\u0004 של אותו פסח \u0003טמאי מתים,\u0004 שהם \u0003נדחין לפסח שני\u0004 בארבעה עשר באייר, \u0003דסתמא\u0004 \u0005[שסתמו]\u0006 של אותו פסח \u0003לשמו קאי\u0004 \u0005[הוא עומד],\u0006 מפני שהוא מיועד לפסח שני. \u0003והאי\u0004 \u0005[ו\u0006דווקא \u0005פסח זה]\u0006 \u0003הוא דבעי\u0004 \u0005[שצריך]\u0006 \u0003עקירה\u0004 משמו הראשון, ואם לא עשה כן — קרבן פסח פסול הוא, ופטור כששחטו על החמץ במועד, \u0003הא\u0004 \u0005[אבל]\u0006 קרבן פסח \u0003אחר\u0004 שעבר זמנו — \u0003לא בעי\u0004 \u0005[אינו צריך]\u0006 \u0003עקירה,\u0004 ואם שחטו בסתם — דינו כשוחט שלמים.","ומעתה לענייננו: פסח זה שמיועד לפסח שני, ושחטו במועד על החמץ, ופטור משום שהוא קרבן פסח פסול, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 ש\u0003ישנה לשחיטה מתחלה ועד סוף\u0004 — משום כך הוא פטור, מפני ש\u0003איפסיל ליה\u0004 \u0005[נפסל לו]\u0006 כבר \u0003מתחלת\u0004 ה\u0003שחיטה,\u0004 כדין פסח שנשחט שלא בזמנו. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 ש\u0003אינה לשחיטה אלא בסוף,\u0004 מדוע יהיה פטור אם נשחט על החמץ? והלוא \u0003כיון\u0004 ש\u0003שחט ביה פורתא\u0004 \u0005[בו מעט]\u0006 כבר \u0003אידחי ליה\u0004 \u0005[\u0006\u0005נדחה לו]\u0006 \u0003מפסח,\u0004 שאי אפשר כבר להקריב אותו לפסח שני, שהרי כבר החל לשוחטו, ואם כן, \u0003אידך כי קא שחיט\u0004 \u0005[השאר שהוא שוחט]\u0006 בסתם — \u0003שלמים קא שחיט\u0004 \u0005[הוא שוחט]\u0006 על החמץ!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 אין מכאן ראיה, שכן \u0003נהי דאידחי ליה\u0004 \u0005[גם אם אמנם נדחה]\u0006 לאחר תחילת השחיטה \u0003מ\u0004להיות קרבן \u0003פסח, מדמי פסח מי אידחי\u0004 \u0005[האם נדחה]?\u0006 הרי עדיין יכול לפדותו קודם גמר שחיטה, ולקנות בדמיו כבש אחר לפסח שני, וכיון שכן, סתם שחיטה שלו היא לשם פסח.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שאינו יכול לפדותו לאחר שהחל לשוחטו, שהרי \u0003בעי\u0004 \u0005[צריך]\u0006 הקרבן \u0003העמדה והערכה\u0004 בפני כהן כדי לפדותו, וכבש זה שנשחט אינו יכול לעמוד על רגליו — דבר זה אינו מעכב, \u0003והתנן\u0004 \u0005[ו\u0006כן \u0005שנינו\u0006\u0005]:\u0006 \u0003שחט בה שנים\u0004 סימנים \u0003או רוב שנים ועדיין היא מפרכסת\u0004 — \u0003הרי היא כחיה לכל דבריה,\u0004 וניתן לפדותה, כל זמן שלא מתה ממש.","\u0003אמר רב יהודה אמר רב: השוחט בשנים ושלשה מקומות\u0004 לאורך הצואר, ויש בכולם יחד שיעור שחיטה — \u0003שחיטתו כשרה.\u0004 והוסיף רב יהודה: \u0003כי אמריתה קמיה\u0004 \u0005[כאשר אמרתי\u0006 את ההלכה הזו \u0005לפני]\u0006 \u0003שמואל, אמר לי: בעינן\u0004 \u0005[צריכים אנו]\u0006 שתהיה \u0003שחיטה מפורעת,\u0004 גלויה וניכרת, \u0003וליכא\u0004 \u0005[ואין כאן],\u0006 כיון שהשחיטה היא בכמה מקומות.","ומעירים, \u0003ואף ר' שמעון בן לקיש סבר\u0004 \u0005[סבור]:\u0006 \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003שחיטה מפורעת,\u0004 ש\u0003אמר ר' שמעון בן לקיש: מנין לשחיטה שהיא\u0004 צריכה להיות \u0003מפורעת? שנאמר: \"חץ שחוט לשונם מרמה דבר\"\u0004 (ירמיהו ט, ז), וכשם שחץ חותך במקום אחד, כך גם השחיטה צריכה להיות במקום אחד.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רבי אלעזר\u0004 ממה ששנינו במשנה: \u0003שנים אוחזין בסכין ושוחטין, אפילו\u0004 היה \u0003אחד מלמעלה ואחד מלמטה\u0004 — \u0003שחיטתו כשרה.\u0004 והבין ר' אלעזר שמדובר כשכל אחד מהם אוחז בסכין אחרת ושוחט במקום אחר בצוואר, אחד למעלה ואחד למטה. ולפי דברי שמואל ור' אלעזר, \u0003אמאי\u0004 \u0005[מדוע]\u0006 שחיטתם כשרה? \u0003והא ליכא\u0004 \u0005[והרי אין כאן]\u0006 \u0003שחיטה מפורעת,\u0004 שהרי כל אחד מהם שוחט במקום אחר!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה: משנתינו\u0004 זו עוסקת \u0003בסכין אחד ושני בני אדם,\u0004 שמחזיקים בה משני צדדים ועושים חתך אחד באלכסון, מלמעלה למטה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבי אבא: אי הכי\u0004 \u0005[אם כך],\u0006 \u0003היינו דתני עלה\u0004 \u0005[\u0006\u0005זה ששנו עליה]\u0006 על משנה זו: \u0003אין חוששין שמא יטרפו זה על זה\u0004 אינו מובן. שכן \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 שמדובר \u0003בשתי סכינין ושני בני אדם\u0004 — \u0003שפיר\u0004 \u0005[יפה,\u0006 מובן הדבר\u0005],\u0006 \u0003מהו דתימא\u0004 \u0005[מהו שתאמר]:\u0006 \u0003ליחוש דלמא סמכי אהדדי\u0004 \u0005[נחשוש שמא יסמכו זה על\u0006 שחיטתו של \u0005זה],\u0006 \u0003והאי לא אתי למעבד רובא והאי לא אתי למעבד רובא\u0004 \u0005[וזה לא יבוא לעשות\u0006 חיתוך \u0005רוב\u0006 סימנים \u0005וזה לא יבוא לעשות\u0006 חיתוך \u0005רוב\u0006 סימנים\u0005],\u0006 ונמצא שעושים אותה טריפה, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 ש\u0003אין חוששין.\u0004","\u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שמדובר \u0003בסכין אחת ושני בני אדם, האי\u0004 \u0005[זה]\u0006 הביטוי \u0003\"אין חוששין שמא יטרפו זה על זה\"\u0004 אין לו מקום כאן, \u0003אלא\u0004 \u0003\"שמא ידרוסו זה על זה\" מיבעי ליה\u0004 \u0005[צריך הוא\u0006 לומר\u0005],\u0006 שהחשש הוא שמא מתוך שזה מושך לכאן וזה לכאן, ידחקו את הסכין על הסימנים, ויהיה בכך פסול של דריסה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבי אבין, תני\u0004 \u0005[שנה]:\u0006 \u0003אין חוששין\u0004"],["\u0003שמא ידרוסו זה על זה.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003ר' אבין\u0004 על שיטה זו, שצריך שחיטה מפורעת וגלויה ברצף אחד, ממה ששנינו בברייתא: \u0003שחט את הוושט למטה\u0004 בחלקו התחתון של הצוואר, \u0003ואת הקנה למעלה\u0004 בצוואר, \u0003או את הוושט למעלה ואת הקנה למטה\u0004 — \u0003שחיטתו כשרה.\u0004 ולדרך זו יש לשאול: \u0003אמאי\u0004 \u0005[מדוע]\u0006 שחיטתו כשרה? \u0003והא ליכא\u0004 \u0005[והרי אין זו]\u0006 \u0003שחיטה מפורעת!\u0004","ואומרים: \u0003הוא מותיב לה\u0004 \u0005[מקשה את הקושיה הזו],\u0006 \u0003והוא מפרק לה\u0004 \u0005[מתרץ אותה]:\u0006 כאן לא מדובר בשחיטה בשני מקומות, אלא \u0003בשחיטה העשויה כ\u0004חודו של \u0003קולמוס\u0004 כלומר, בחיתוך אחד באלכסון, שמתחיל למעלה וחותך באלכסון את שני הסימנים, וכך יש שחיטה מפורעת.","מסופר, \u0003ההוא תורא דאישחט\u0004 \u0005[שור אחד שנשחט]\u0006 \u0003בשנים ושלשה מקומות, על\u0004 \u0005[נכנס]\u0006 \u0003רב יצחק בר שמואל בר מרתא\u0004 לחנות, \u0003שקל משופרי שופרי\u0004 \u0005[ולקח מהחלק הטוב שבטוב]\u0006 שבאותו שור, ובכך הוכיח שהוא סבור שהיא כשרה לכתחילה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבי זירא:\u0004 על ידי מעשיך \u0003למדתנו רבינו\u0004 ש\u0003משנתינו,\u0004 המכשירה כששנים אוחזים בסכין ושוחטים, אחד למעלה ואחד למטה, עוסקת \u0003בשני סכינין ושני בני אדם,\u0004 שכל אחד שוחט במקום אחר.","\u0003אמר רב יהודה אמר רב:\u0004 אם השוחט \u0003החליד\u0004 (תחב) \u0003את הסכין\u0004 בתוך הצוואר \u0003בין סימן לסימן,\u0004 בין הקנה לוושט שמתחתיו, \u0003ופסקו\u0004 (וחתכו), ששחט תחילה את הוושט, ואחר כך הוציא את הסכין וחזר ושחט את הקנה כדרכו — \u0003שחיטתו\u0004 \u0003פסולה.\u0004 אבל אם החליד את הסכין \u0003תחת העור\u0004 של הצוואר, ואז שחט כדרכו את שני הסימנים — שחיטתו \u0003כשרה.\u0004","ועל הדין הראשון שואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו\u0006 בכך\u0005]?\u0006 \u0003תנינא\u0004 \u0005[\u0006הרי \u0005שנינו]\u0006 דבר זה במפורש: \u0003או החליד את הסכין תחת\u0004 הסימן \u0003השני ופסקו\u0004 — \u0003ר' ישבב אומר:\u0004 הרי זו \u0003נבלה\u0004 המטמאה את הנוגע בה או את הנושא אותה, ואילו \u0003ר' עקיבא אומר: טרפה\u0004 היא, שאסורה באכילה, אבל אינה נבילה ואינה מטמאה. ומכל מקום, הכל מודים ששחיטה פסולה היא!","ומשיבים: \u0003אי ממתניתין\u0004 \u0005[אם ממשנתנו\u0006 בלבד\u0005]\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה אמורים]\u0006 דווקא במקרה שתוחב את הסכין תחת הסימן השני, וחותך אותו \u0003מלמטה למעלה,\u0004 מכיוון העורף לכיוון הצוואר, \u0003דלא קעביד\u0004 \u0005[שאינו עושה זאת]\u0006 \u0003כדרך שחיטה,\u0004 שהיא מן הצוואר לכיוון העורף. \u0003אבל\u0004 אם הוא תוחב את הסכין בין שני הסימנים, וחותך את הסימן התחתון \u0003מלמעלה למטה,\u0004 ומוציא את הסכין, וחוזר וחותך את הקנה באופן זה, \u0003דקעביד\u0004 \u0005[שהוא עושה]\u0006 \u0003כדרך שחיטה\u0004 — \u0003אימא שפיר דמי\u0004 \u0005[אמור שהוא כשר],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שכל שהחליד את הסכין הרי זה פסול.","על מה שאמר רב יהודה בשם רב ש\u0003תחת העור\u0004 — \u0003כשרה,\u0004 מעירים: \u0003בי\u0004 \u0005[\u0006החכמים מ\u0005בית\u0006 מדרשו של\u0005]\u0006 \u0003רב אמרי\u0004 \u0005[אמרו]\u0006 בשם רב: כשתוחב את הסכין \u0003תחת העור\u0004 וכך שוחט \u0003איני יודע\u0004 מה דינו, ושמא חלדה היא זו ופסולה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 לחכמים: \u0003לבי\u0004 \u0005[ל\u0006דעת \u0005בית מדרשו]\u0006 של \u0003רב, דאמרי\u0004 \u0005[שאומרים]:\u0006 \u0003תחת העור איני יודע,\u0004 אם החליד את הסכין \u0003תחת מטלית\u0004 שהיתה כרוכה על צוואר הבהמה, ואחר כך שחט, \u0003מהו?\u0004 האם גם בזה חשש לפסול חלדה? וכן אם החליד \u0003תחת צמר מסובך\u0004 שבצוואר הכבש, \u0003מהו?\u0004 שאלות אלו לא נפתרו ונשארו ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא:\u0004 אם \u0003החליד\u0004 את הסכין ושחט כך רק את \u0003מיעוט\u0004 ה\u0003סימנים,\u0004 אבל רובם נשחט כראוי, \u0003מהו\u0004 דינו? שאלה זו לא נפתרה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003השוחט שני ראשין כאחד\u0004 — \u0003שחיטתו כשרה.\u0004 היו \u0003שנים אוחזין בסכין ושוחטים\u0004 בהמה אחת, \u0003אפילו אחד למעלה ואחד למטה\u0004 — \u0003שחיטתו כשרה. התיז את הראש בבת אחת,\u0004 ולא עשה כדרך שחיטה, בדרך הולכה והבאה של הסכין — הרי זו שחיטה \u0003פסולה. היה שוחט\u0004 בדרך שחיטה, \u0003ו\u0004בתוך כך \u0003התיז את הראש בבת אחת,\u0004 קודם שהספיק להחזירה, \u0003אם יש בסכין\u0004 אורך \u0003מלא צואר\u0004 הבהמה — \u0003כשרה,\u0004 אבל בפחות מזה לא ייתכן שחתך את הסימנים אלא בדריסה, שהיא שחיטה פסולה.","\u0003היה שוחט\u0004 כדרכו \u0003והתיז שני ראשין בבת אחת, אם יש בסכין מלא צואר אחד\u0004 — \u0003כשרה. במה דברים אמורים\u0004 שיש לחשוש לאורך הסכין? \u0003בזמן שהוליך\u0004 את הסכין \u0003ולא הביא\u0004 (החזיר), \u0003או הביא ולא הוליך, אבל אם הוליך והביא, אפילו\u0004 היה אורך הסכין \u0003כל שהוא, אפילו באיזמל,\u0004 שהוא סכין קטנה — \u0003כשרה.\u0004","שנינו במשנה כי אם התיז את הראש — שחיטתו פסולה. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין דברים אלה]?\u0006 \u0003אמר שמואל, דאמר קרא\u0004 \u0005[שאמר המקרא]:\u0006 \u0003\"חץ שחוט לשונם מרמה דבר\"\u0004 (ירמיהו ט, ז) ששחיטה נעשית כדרך מעופו של החץ, במשיכה, ולא בדרך של דריסה או הכאה.","\u0003וכן\u0004 \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל:\u0004 נאמר \u0003\"ושחט\"\u0004 (ויקרא א, ה) — \u0003אין \"ושחט\" אלא ומשך,\u0004 שמושך את הסכין על צואר הבהמה, \u0003וכן הוא אומר: \"זהב שחוט\"\u0004 (מלכים א י, טז), שמשמעו זהב שמושכים אותו, כדרך שעושים צורפים, \u0003ואומר: \"חץ שחוט לשונם מרמה דבר\".\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 כוונת\u0005]\u0006 \u0003\"ואומר\"?\u0004 מה נוסף בראיה האחרת? ומסבירים: \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003\"זהב שחוט\"\u0004 אין משמעו משוך, אלא \u0003שנטווה כחוט הוא,\u0004 שהוא רך, ועל שם כך הוא קרוי \"שחוט\" — \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 מן הכתוב: \u0003\"חץ שחוט לשונם\"\u0004 שהכוונה היא לדבר שנמשך.","מסופר, \u0003רבא הוה בדיק ליה גירא\u0004 \u0005[היה בודק לו חץ]\u0006 \u0003לר' יונה בר תחליפא,\u0004 לוודא שאין בו פגימות, \u0003ושחט בה עופא בהדי דפרח\u0004 \u0005[ו\u0006היה \u0005שוחט בו עוף\u0006 בתוך כדי מעופו\u0005].\u0006 ושואלים: \u0003ודלמא עביד\u0004 \u0005[ושמא עשה]\u0006 \u0003חלדה,\u0004 שנכנס החץ לתוך הצוואר בתוך הסימנים, ולא חתך את הסימנים בדרך הליכתו! ומשיבים: \u0003חזינן\u0004 \u0005[רואים אנו]\u0006"],["\u0003גידפי דמיפרמי\u0004 \u0005[הנוצות\u0006 שבקדמת הצואר \u0005שהן כרותות],\u0006 וכך ניכר שהחץ עשה פעולה של שחיטה בדרך הליכתו, ולא נתחב בסימנים.","ושואלים: וכיצד התיר רב לשחוט ציפור במעופה? \u0003והא בעי\u0004 \u0005[והרי צריך]\u0006 לקיים בדם הציפור מצות \u0003כסוי\u0004 הדם! \u0003וכי תימא דמכסו ליה\u0004 \u0005[ואם תאמר שמכסים אותו]\u0006 במקום שבו הוא נמצא, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' זירא אמר רב: השוחט צריך שיתן עפר למטה,\u0004 קודם השחיטה, \u0003ועפר למעלה, שנאמר: \"וכסהו בעפר\"\u0004 (ויקרא יז, יג), \"וכסהו \u0003עפר\" לא נאמר אלא \"בעפר\",\u0004 שהדם יהיה בתוך העפר — \u0003מלמד שהשוחט צריך שיתן עפר למטה ועפר למעלה!\u0004","ומשיבים: מדובר במקרה \u0003דמזמין ליה\u0004 \u0003לעפר דכולה פתקא\u0004 \u0005[שמזמן\u0006 מתחילה \u0005את העפר של כל הבקעה]\u0006 לצורך מצות כיסוי הדם.","שנינו במשנה: \u0003היה שוחט והתיז\u0004 את הראש בבת אחת, אם יש באורך הסכין מלא צוואר — כשרה. \u0003אמר רבי זירא:\u0004 צריך שיהיה שם \u0003מלא צואר ו\u0004גם \u0003חוץ לצואר.\u0004","איבעיא להו \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 האם הכוונה היא שיהיה שם \u0003מלא צואר וחוץ לצואר\u0004 גם כן \u0003כמלא צואר, דהוו לה תרי צוארי\u0004 \u0005[שהרי זה\u0006 ביחד כאורך \u0005שני צווארים],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 כוונתו \u0003מלא צואר וחוץ לצואר\u0004 רק \u0003משהו?\u0004","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בהמשך המשנה: \u0003היה שוחט והתיז שני ראשין בבת אחת, אם יש לסכין מלא צואר אחד\u0004 — \u0003כשר.\u0004 ונברר: \u0003מאי\u0004 \u0005[מה פירוש]\u0006 \u0003מלא צואר אחד? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003מלא צואר אחד ותו לא\u0004 \u0005[ולא עוד],\u0006 דבר זה לא ייתכן, שכן \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 אם \u0003בבהמה אחת בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003מלא צואר וחוץ לצואר, בשתי בהמות סגי להו\u0004 \u0005[די להם]\u0006 \u0003כמלא צואר אחד? אלא פשיטא\u0004 \u0005[פשוט]\u0006 שהכוונה היא ל\u0003מלא צואר\u0004 אחד \u0003חוץ\u0004 \u0003לשני צוארין.\u0004","\u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שמה ששנינו: אם יש בסכין \u0003מלא צואר\u0004 כוונתו \u0003חוץ לצואר\u0004 עצמו, ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","שנינו במשנה: \u0003במה דברים אמורים\u0004 שרק אם יש בסכין מלא צוואר ויותר שחיטתו כשרה — \u0003בזמן שהוליך ולא הביא,\u0004 אבל אם הוליך והביא, אפילו כל שהוא, אפילו באיזמל — שחיטתו כשרה. \u0003אמר רב מנשה:\u0004 מדובר \u0003באיזמל שאין לו קרנים\u0004 מצידיו, אבל אם יש לו קרנים, מתוך שהאיזמל קטן, יש לחשוש שאתן קרנים ינקבו את הסימנים, או ייכנסו ביניהם ויפסלו את השחיטה בחלדה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אויא לרב מנשה: מחטא מאי\u0004 \u0005[מחט מהי]?\u0006 האם אפשר לשחוט כשמוליך חודה של מחט על הצוואר? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מחטא מבזע בזע\u0004 \u0005[המחט קורעת],\u0006 שהחוד עושה נקב בצואר, ואינה חותכת.","שאל אותו: \u0003מחטא דאושכפי\u0004 \u0005[מחט של סנדלרים],\u0006 שהיא שטוחה, ושפתיה חדות, והוליכה והביאה, \u0003מאי\u0004 \u0005[מה\u0006 דינה\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003תנינא\u0004 \u0005[שנינו]\u0006 במשנתנו: אבל אם הוליך והביא, \u0003אפילו\u0004 בסכין \u0003כל שהוא\u0004 שחיטתה כשרה, \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 בא הדבר לרבות אפילו \u0003מחטא דאושכפי\u0004 \u0005[מחט של סנדלרים]?\u0006 ודוחים: \u0003לא,\u0004 הכוונה היא ל\u0003איזמל,\u0004 שהוא גדול יותר. ומקשים: הלוא \u0003איזמל בהדיא קתני לה\u0004 \u0005[במפורש הוא שונה אותה],\u0006 מיד אחר כך, ובוודאי בא לרבות דבר נוסף! ומשיבים: התנא \u0003פרושי קא מפרש\u0004 \u0005[מפרש הוא את דבריו]:\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003כל שהו\u0004 — \u0003איזמל.\u0004","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר, \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר שמתחילה מדובר ב\u0003מחטא דאושכפי\u0004 \u0005[מחט של סנדלרים],\u0006 \u0003השתא מחטא דאושכפי שריא\u0004 \u0005[עכשיו,\u0006 הרי \u0005מחט של סנדלרים מותרת]\u0006 בשחיטה, \u0003איזמל מיבעיא\u0004 \u0005[נצרכה]\u0006 המשנה לומר ששוחטים בה? ודוחים: מכאן אין ראיה, ויש לומר ש\u0003איזמל אצטריכא ליה\u0004 \u0005[הוצרך לו\u0006 לומר\u0005]\u0006 שהוא כשר גם כן, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003ליגזר\u0004 \u0005[שנגזור]\u0006 על \u0003איזמל שאין לו קרנים אטו\u0004 \u0005[משום]\u0006 \u0003איזמל שיש לו קרנים,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 התנא שאין אומרים כן, וניתן לשחוט באיזמל רגיל.","\u0003נפלה סכין ושחטה\u0004 מעצמה, \u0003אף על פי ששחטה כדרכה\u0004 — \u0003פסולה, שנאמר: \"וזבחת... ואכלת\"\u0004 (דברים כז, ז), לומר: רק \u0003מה שאתה זובח אתה אוכל,\u0004 ולא מה שנזבח מאליו.","שנינו: נפלה סכין ושחטה — פסולה. ומדייקים: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 אם \u0003נפלה\u0004 ושחטה — השחיטה פסולה, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003הפילה הוא\u0004 ושחטה — השחיטה \u0003כשרה, ואף על גב דלא מיכוין\u0004 \u0005[ואף על פי שאינו מתכוון]\u0006 לשחיטה.","ואם כן, \u0003מאן תנא דלא בעינן\u0004 \u0005[מיהו התנא\u0006 הסבור \u0005שאין אנו צריכים]\u0006 \u0003כוונה לשחיטה? אמר רבא:\u0004 שיטת \u0003ר' נתן היא, דתני\u0004 \u0005[ששנה]\u0006 \u0003אושעיא זעירא דמן חבריא\u0004 \u0005[הקטן שבחבורה]:\u0006 \u0003זרק סכין\u0004 על מנת \u0003לנועצה בכותל, והלכה ו\u0004בתוך כך \u0003שחטה כדרכה\u0004 — ר' נתן מכשיר בשחיטה זו, \u0003וחכמים פוסלים.\u0004 ומוסיפים, \u0003הוא,\u0004 אושעיא זעירא דמן חבריא, \u0003תני לה\u0004 \u0005[שנה\u0006 את הברייתא \u0005הזו]\u0006 בשם רבו, \u0003והוא\u0004 הוסיף ו\u0003אמר לה\u0004 \u0005[\u0006ביחס \u0005אליה]:\u0006 \u0003הלכה כר' נתן.\u0004","ושואלים: \u0003והא\u0004 \u0005[והרי\u0006 כבר\u0005]\u0006 \u0003אמרה רבא חדא זימנא\u0004 \u0005[פעם אחת],\u0006 שמשנתנו כשיטת ר' נתן! \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 בפרק הראשון של מסכת זו: \u0003וכולן ששחטו ואחרים רואין אותן\u0004 — \u0003שחיטתן כשרה,\u0004 ובכלל זה חרש שוטה וקטן, שאין להם דעת. \u0003ואמרינן\u0004 \u0005[ואמרנו]\u0006 על כך: \u0003מאן תנא דלא בעי\u0004 \u0005[מיהו התנא\u0006 הסבור \u0005שלא צריך]\u0006 \u0003כוונה לשחיטה? ואמר רבא: ר' נתן היא.\u0004 ואם כן כבר למדנו שזו דעת משנתנו!","ומשיבים: \u0003צריכא\u0004 \u0005[צריך]\u0006 הדבר להיאמר בשני המקרים, \u0003דאי אשמועינן התם\u0004 \u0005[שאם היה משמיע לנו שם\u0006 בלבד\u0005],\u0006 לגבי חרש שוטה וקטן, הייתי אומר כי הטעם שהשחיטה כשרה הוא \u0003משום דקא מיכוין\u0004 \u0005[שהוא מתכוון]\u0006 על כל פנים \u0003לשום חתיכה\u0004 (חיתוך) \u0003בעולם,\u0004 למרות שאינו מתכוון לשחיטה, \u0003אבל הכא\u0004 \u0005[כאן],\u0006 כשמפיל את הסכין, \u0003דלא קא מיכוין\u0004 \u0005[שאינו מתכוון]\u0006 אפילו לחתוך — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 תהיה השחיטה כשרה.","ומצד שני, \u0003ואי אשמעינן הכא\u0004 \u0005[ואם היה משמיע לנו כאן],\u0006 שאם הפיל סכין ושחטה שחיטתו כשרה, הייתי אומר כי טעם הדבר הוא \u0003משום\u0004 שהחיתוך \u0003קאתי\u0004 \u0005[בא]\u0006 על כל פנים \u0003מכח בן דעת, אבל התם\u0004 \u0005[שם],\u0006 בחרש שוטה וקטן ששחטו, \u0003דלא קאתי\u0004 \u0005[שלא בא]\u0006 \u0003מכח בן דעת\u0004 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 תהיה השחיטה כשרה, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 הדבר להיאמר.","משנתנו הובאה כראיה במחלוקת אמוראים בענין אחר. וכך \u0003אתמר\u0004 \u0005[נאמר]:\u0006 \u0003נדה ש\u0004לאחר שפסק דמה \u0003נאנסה וטבלה,\u0004 כלומר, טבלה שלא ברצונה, \u0003אמר רב יהודה אמר רב: טהורה\u0004 היא \u0003לביתה\u0004 כלומר, מותרת לבעלה, \u0003ו\u0004אולם \u0003אסורה לאכול בתרומה\u0004 אם היתה כהנת, משום שלענין אכילת תרומה בטהרה אין טבילה זו נחשבת. \u0003ור' יוחנן אמר: אף לביתה לא טהרה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן, ל\u0004שיטת \u0003רב\u0004 ש\u0003אמר: טהורה לביתה ואסורה לאכול בתרומה,\u0004 תמוה הדבר: אם לענין \u0003עון\u0004 שיש בו \u0003כרת\u0004 (ביאה על אישה נדה) \u0003הותרה,\u0004 לענין \u0003איסור מיתה\u0004 בידי שמים שיש באכילת תרומה בטומאה \u0003מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]?\u0006 ומדוע תיאסר?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 תרומה צריכה כוונה להיטהר משום שהיא קודש, ואילו \u0003בעלה חולין הוא, וחולין לא בעי\u0004 \u0005[צריך]\u0006 \u0003כוונה\u0004 לטהרתו. \u0003ומנא תימרא\u0004 \u0005[ומנין אתה אומר]\u0006 שחולין אינם צריכים כוונה? \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003גל שנתלש\u0004 מן הים, \u0003ובו\u0004 בגל הזה היו שיעור של \u0003ארבעים סאה,\u0004 כשיעור מקוה, \u0003ונפל\u0004 הגל \u0003על האדם ועל הכלים\u0004 הטמאים — הריהם \u0003טהורין\u0004 שנטהרו בכך. \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 דינו של ה\u0003אדם דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003כלים, מה כלים\u0004 נטהרים למרות \u0003דלא מיכווני\u0004 \u0005[שאינם מתכוונים]\u0006 — \u0003אף אדם\u0004 המוזכר כאן \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא בעי\u0004 \u0005[אינו צריך]\u0006 \u0003כוונה\u0004 כדי להיטהר בכך?","ודוחים: \u0003ממאי\u0004 \u0005[ממה]\u0006 אתה מוכיח זאת? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003ב\u0004אדם \u0003יושב ומצפה עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שהוא מצפה \u0003אימתי יתלש הגל\u0004 ויעבור עליו."],["\u0003ו\u0004לפי זה יש לדון על \u0003כלים דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003אדם, מה אדם\u0004 מדובר \u0003דבעינן\u0004 \u0005[שצריכים אנו]\u0006 \u0003כוונה, אף כלים נמי\u0004 \u0005[גם כן]\u0006 מדובר \u0003דקא מכוין להו\u0004 \u0005[שמתכוון להם]\u0006 \u0003אדם\u0004 שייטהרו בכך!","\u0003וכי תימא\u0004 \u0005[ואם תאמר,\u0006 תקשה\u0005]\u0006 על פירוש זה: אם \u0003ביושב ומצפה\u0004 מדובר \u0003מאי למימרא\u0004 \u0005[מה\u0006 בא \u0005לומר]?\u0006 מה חידוש יש בדבר?","על כך יש להשיב, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003ליגזר\u0004 \u0005[נגזור]\u0006 שלא יטהר הגל, גזירה \u0003משום חרדלית של גשמים,\u0004 מפל של מי גשמים שאינו מטהר. \u0003אי נמי\u0004 \u0005[או גם כן],\u0006 \u0003ליגזר\u0004 \u0005[נגזור]\u0006 שלא יטהרו ה\u0003ראשין\u0004 של הגלים עצמם, כשהם נופלים על האדם והכלים המונחים על הקרקע, גזירה \u0003אטו\u0004 \u0005[משום]\u0006 ה\u0003כיפין,\u0004 הגל כשהוא באויר, שהוא עשוי כמין כיפה, שאין מטבילים שם כלים, \u0003קא משמע לן דלא גזרינן\u0004 \u0005[משמיע לנו שאין אנו גוזרים]!\u0006","ומעירים: \u0003ומנא תימרא דלא מטבלינן\u0004 \u0005[ומנין אתה אומר שאין מטבילים אנו]\u0006 \u0003בכיפין\u0004 של הגל? \u0003דתנן\u0004 \u0005[ששנינו]:\u0006 \u0003מטבילין בראשין ואין מטבילין בכיפין,\u0004 לפי \u0003שאין מטבילין באויר,\u0004 אלא בקרקע.","וחוזרים ושואלים: \u0003אלא\u0004 \u0003חולין דלא בעי\u0004 \u0005[שלא צריך]\u0006 \u0003כוונה\u0004 לטהרתם \u0003מיהא מנלן\u0004 \u0005[על כל פנים מנין לנו]?\u0006 ומשיבים, ממה \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003פירות שנפלו\u0004 בלא כוונה \u0003לתוך אמת המים, ופשט מי שידיו טמאות\u0004 את ידיו \u0003ונטלן\u0004 את הפירות — \u0003ידיו\u0004 של אותו אדם \u0003טהורות\u0004 לאכילת חולין, משום שנטבלו במים, למרות שלא נתכוון להדיח ולטהר, \u0003ו\u0004אילו ה\u0003פירות אינן ב\"כי יותן\"\u0004 (ויקרא יא, לח), אינם מוכשרים על ידי מים אלה לקבלת טומאה, מפני שלא רצה במים שעליהם, ואין מים מכשירים אלא לרצון.","\u0003ואם\u0004 פשט את ידו לאמת המים \u0003בשביל שיודחו\u0004 ידיו, ונטל את הפירות — גם \u0003ידיו טהורות,\u0004 וגם ה\u0003פירות ב\"כי יותן\",\u0004 מפני שרצה במים אלה. על כל פנים, מן הדין הראשון מוכח שאין צורך בכוונה כדי להיטהר לחולין, שהרי פשט ידיו כדי ליטול את הפירות, ובכל זאת ידיו טהורות.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לרב נחמן\u0004 ממה ששנינו במשנה: מי ש\u0003טבל ל\u0004אכילת \u0003חולין\u0004 בטהרה \u0003והוחזק\u0004 (נתכוון להיטהר) \u0003ל\u0004אכילת \u0003חולין\u0004 — \u0003אסור ל\u0004אכילת \u0003מעשר\u0004 שני. וממה שנאמר \"הוחזק לחולין\" נדייק: \u0003הוחזק\u0004 לחולין — \u0003אין\u0004 \u0005[כן],\u0006 מותר בחולין, \u0003לא הוחזק\u0004 — \u0003לא\u0004 הותר אף בחולין!","השיב לו רב נחמן: אין לדייק מכאן שצריך כוונה לחולין, אלא \u0003הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003אף על פי שהוחזק לחולין\u0004 — \u0003אסור למעשר.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 רבא ממה ששנינו באותה משנה: \u0003טבל ולא הוחזק\u0004 — \u0003כאילו לא טבל. מאי לאו\u0004 \u0005[האם אין\u0006 הכוונה\u0005]:\u0006 \u0003כאילו לא טבל כלל,\u0004 אפילו לחולין?","השיב לו רב נחמן: \u0003לא, כאילו לא טבל למעשר, אבל טבל לחולין. הוא\u0004 רבא \u0003סבר\u0004 \u0005[סבור\u0006 היה\u0005]:\u0006 \u0003דיחויי קא מדחי ליה\u0004 \u0005[דחיה הוא שדוחה אותו]\u0006 רב נחמן, ואין זה הפירוש האמיתי, \u0003נפק דק ואשכח\u0004 \u0005[יצא דקדק ומצא],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 מפורשת כדבריו: \u0003טבל ולא הוחזק\u0004 — \u0003מותר לחולין ואסור למעשר.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: לימא תיהוי תיובתא\u0004 \u0005[האם נאמר\u0006 ש\u0005תהיה קושיה]\u0006 על דברי \u0003רבי יוחנן מהא\u0004 \u0005[מ\u0006ברייתא \u0005זו],\u0006 שהרי נאמר בה שטבילה ללא כוונה מועילה לחולין, ואילו הוא אמר (בתחילת הסוגיה) שנדה שטבלה בלא כוונה אסורה גם לבעלה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003ר' יוחנן הוא\u0004 ש\u0003אמר\u0004 הלכה זו, \u0003כ\u0004שיטת \u0003ר' יונתן בן יוסף\u0004 אמרה.","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 בענין צרעת הבגד, \u0003ר' יונתן בן יוסף אומר:\u0004 בגד שהיה בו נגע, והוסגר לשבוע ולא נשתנה הנגע — צריך לכבסו ולהסגירו למשך שבוע נוסף. ואם לאחר אותו שבוע סר הנגע, צריך לטובלו כדי לטהרו כאמור: \u0003\"וכובס\u0004 שנית וטהר\" (ויקרא יג, נח). ולכאורה, די היה לכתוב: \"וכובס וטהר\", \u0003מה תלמוד\u0004 (צורך) \u0003לומר \"שנית\"?\u0004 אלא בכך \u0003מקיש\u0004 משווה הכתוב \u0003תכבוסת שניה לתכבוסת ראשונה: מה תכבוסת ראשונה\u0004 היא \u0003לדעת,\u0004 שנאמר: \"וצוה הכהן וכבסו את אשר בו הנגע\" (שם) — \u0003אף תכבוסת שניה,\u0004 שעניינה טבילת הבגד לטהרו — צריכה להיעשות \u0003לדעת.\u0004","ושואלים: \u0003אי\u0004 (אם כן) נאמר גם: \u0003מה להלן\u0004 בתכבוסת הראשונה \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שתהא דווקא ל\u0003דעת כהן, אף כאן בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003דעת כהן! תלמוד לומר:\u0004 \"וכובס שנית \u0003וטהר\"\u0004 (שם נח), \u0003מכל מקום.\u0004 הרי שלשיטת ר' יונתן בן יוסף טבילה לטהרת בגד חולין צריכה גם כן כוונה, וכשיטתו הולך ר' יוחנן, שמצריך כוונה לטבילה בחולין.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב שימי בר אשי: ומי אמר\u0004 \u0005[והאם אומר]\u0006 \u0003ר' יוחנן הכי\u0004 \u0005[כך],\u0006 שצריך כוונה בחולין? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן: הלכה כסתם משנה.\u0004","\u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה שלנו\u0005]\u0006 העוסקת בשחיטת חולין: \u0003נפלה סכין\u0004 מעצמה \u0003ושחטה, אף על פי ששחטה כדרכה\u0004 — שחיטה \u0003פסולה\u0004 היא. \u0003והוינן בה\u0004 \u0005[והיינו עוסקים בה]:\u0006 \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 במקרה ש\u0003נפלה\u0004 מעצמה הדין כן, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003הפילה הוא\u0004 — \u0003כשרה, ואף על גב דלא מיכוין\u0004 \u0005[ואף על פי שאינו מתכוון]\u0006 לשחוט. \u0003ואמרינן\u0004 \u0005[ואמרנו]\u0006 על כך: \u0003מאן תנא דלא בעי\u0004 \u0005[מיהו התנא\u0006 של המשנה \u0005שלא מצריך]\u0006 \u0003כוונה לשחיטה? אמר רבא: ר' נתן היא!\u0004","ומשיבים: \u0003בשחיטה\u0004 של חולין \u0003אפילו ר' יונתן בן יוסף\u0004 מודה שאין צורך בכוונה, ומדוע? \u0003מדגלי רחמנא\u0004 \u0005[מ\u0006תוך \u0005שגילתה התורה]\u0006 שה\u0003מתעסק בקדשים,\u0004 ששוחט אותם בלא כוונה — \u0003פסול,\u0004 שנאמר \"לרצונכם תזבחו\" (ויקרא יט, ה), ופירושו: לדעתכם, \u0003מכלל\u0004 הדברים אתה למד שב\u0003חולין לא\u0004 \u0003בעינן\u0004 \u0005[אין אנו צריכים]\u0006 \u0003כוונה.\u0004","אגב כך שואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 החולקים על ר' נתן, ולדעתם אם הפיל את הסכין ושחטה — שחיטתו פסולה, מה הם משיבים לטענה זאת? ומשיבים: \u0003נהי דלא בעינן\u0004 \u0005[\u0006גם \u0005אם אמנם\u0006 לדעתם \u0005אין אנו צריכים]\u0006 בחולין \u0003כוונה לזביחה,\u0004 להתיר את הבהמה באכילה, כמו שנאמר בקדשים \"לרצונכם תזבחו\", מכל מקום כוונה \u0003לחתיכה\u0004 (לחיתוך) \u0003בעינן\u0004 \u0005[צריכים אנו],\u0006 ואין די שיתכוון להפיל סכין.","\u0003אמר רבא: בהא זכנהו\u0004 \u0005[בזה ניצחם]\u0006 \u0003ר' נתן לרבנן\u0004 \u0005[לחכמים],\u0006 שכן \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 בשחיטת חולין \u0003\"וחתכת\"? \"וזבחת\" כתיב\u0004 \u0005[נאמר]\u0006 (דברים יב, כא), ואם כן \u0003אי בעינן\u0004 \u0005[אם צריכים אנו]\u0006 \u0003כוונה לחתיכה\u0004 — \u0003אפילו לזביחה נמי ליבעי\u0004 \u0005[גם כן נצטרך],\u0006 \u0003אי לא בעינן\u0004 \u0005[אם לא צריכים אנו]\u0006 \u0003כוונה לזביחה\u0004 — \u0003לחתיכה נמי לא ליבעי\u0004 \u0005[גם כן לא נצטרך].\u0006 ושבים לתחילת הדיון, בנדה שטבלה מתוך אונס, שמוסכם שהיא אסורה לאכול בתרומה, מפני שלא התכוונה לכך, אלא שנחלקו רב ור' יוחנן האם היא טהורה לבעלה.","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003נדה שנאנסה וטבלה? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003דאנסה\u0004 \u0005[שהכריחה]\u0006 אותה \u0003חבירתה ואטבלה\u0004 \u0005[והטבילה אותה],\u0006 הרי \u0003כוונה\u0004 של \u0003חברתה כוונה מעלייתא\u0004 \u0005[מעולה]\u0006 היא, ומועילה לנטבלת!","\u0003ועוד,\u0004 במקרה כזה \u0003בתרומה נמי אכלה\u0004 \u0005[גם כן אוכלת],\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003החרשת, והשוטה, והסומא, ושנטרפה דעתה,\u0004 שאינן יודעות להיטהר מנידתן, אם יש להן ידידות \u0003פקחות\u0004 — \u0003מתקנות\u0004 \u0003אותן\u0004 לבודקן אם טהורות הן, ולהטבילן, והן \u0003אוכלות בתרומה!\u0004","\u0003אמר רב פפא: ל\u0004שיטת \u0003ר' נתן,\u0004 שאינו מצריך כוונה בשחיטת חולין, ואפילו לא כוונה לחיתוך, מדובר כגון \u0003שנפלה\u0004 לאונסה \u0003מן הגשר\u0004 לנהר, שלא היתה שם כוונה כלל. \u0003ולרבנן\u0004 \u0005[ול\u0006שיטת \u0005חכמים],\u0006 הסבורים שלענין שחיטה צריך כוונה על כל פנים לחיתוך, מדובר \u0003שירדה\u0004 לנהר כדי \u0003להקר\u0004 (לצנן עצמה), ולא לשם טהרה, שכיון שהתכוונה על כל פנים לרחיצה, תועיל טבילתה לענין חולין.","ועוד בענין מחלוקת ר' נתן וחכמים, \u0003אמר רבא: שחט פרה\u0004 אדומה \u0003ושחט בהמה אחרת עמה\u0004 באותה שעה — לדברי הכל פסולה הפרה האדומה."],["\u0003נשחטה בהמה אחרת עמה\u0004 בלא מתכוון, \u0003ל\u0004דעת \u0003ר' נתן\u0004 המכשיר שחיטת חולין בלא כוונה — ה\u0003פרה\u0004 האדומה \u0003פסולה,\u0004 משום שנעשתה מלאכה אחרת יחד עם שחיטתה, וה\u0003בהמה\u0004 האחרת \u0003כשרה.\u0004 ואילו \u0003ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים],\u0006 הסבורים ששחיטה ללא כוונה אינה קרויה שחיטה — ה\u0003פרה כשרה,\u0004 מפני שלא נעשתה מלאכה אחרת עם שחיטתה, וה\u0003בהמה\u0004 האחרת \u0003פסולה,\u0004 מפני שנשחטה בלא כוונה.","ותמהים: הרי כל זה \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומשיבים: \u0003נשחטה בהמה אחרת לר' נתן איצטריכא ליה\u0004 \u0005[הוצרכה לו],\u0006 לומר שהיא פסולה. שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003\"ושחט אותה\"\u0004 (במדבר יט, ג) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 והמלה \"אותה\" באה להדגיש: אותה דווקא, \u0003ולא אותה וחבירתה, והיכי דמי\u0004 \u0005[וכיצד הוא]\u0006 האיסור? \u0003כגון ששחט שתי פרות\u0004 אדומות \u0003בהדי הדדי\u0004 \u0005[יחדיו],\u0006 \u0003אבל\u0004 אם שחט עמה \u0003בהמה\u0004 של \u0003חולין\u0004 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 שאין זה בכלל \"ולא אותה וחבירתה\", על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 רב פפא שגם זה בכלל.","והוסיף רבא: אם \u0003חתך דלעת עמה,\u0004 עם שחיטת הפרה האדומה — \u0003דברי הכל פסולה,\u0004 שהרי עשה עמה מלאכה אחרת במתכוון. ואם \u0003נחתכה דלעת עמה\u0004 בלא מתכוון — \u0003דברי הכל כשרה,\u0004 שאין זו מלאכה הפוסלת, וגם אין בזה משום \"אותה\" ולא אותה וחבירתה.","\u0003נפלה\u0004 ה\u0003סכין\u0004 באמצע השחיטה \u0003והגביהה,\u0004 או \u0003נפלו כליו\u0004 (בגדיו) באמצע \u0003והגביהן,\u0004 וכן אם קודם השחיטה \u0003השחיז את הסכין ו\u0004בשל כך \u0003עף\u0004 (התעייף) קודם שגמר את השחיטה, ו\u0003בא חבירו ושחט,\u0004 בכל אלה \u0003אם שהה\u0004 בשעת השחיטה פרק זמן \u0003כדי שחיטה\u0004 — \u0003פסולה. ר' שמעון אומר: אם שהה כדי ביקור\u0004 (בדיקה).","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 שהה \u0003כדי שחיטה? אמר רב: כדי שחיטת בהמה אחרת.\u0004","\u0003אמרי ליה\u0004 \u0005[אמרו לו]\u0006 \u0003רב כהנא ורב אסי לרב:\u0004 האם שהייה הפוסלת היא \u0003כדי שחיטת בהמה ל\u0004פסול שחיטת \u0003בהמה, ו\u0004שהייה כדי שחיטת \u0003עוף ל\u0004פסול שחיטת \u0003עוף, או דלמא\u0004 \u0005[שמא]\u0006 \u0003אף\u0004 כדי שחיטת \u0003בהמה לעוף,\u0004 שאם שהה בפחות מכדי שחיטת בהמה אינו פוסל אף בשחיטת עוף?","\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003לא הוה בדיחנא ביה בחביבי\u0004 \u0005[לא היתה דעתי בדוחה כל כך בדודי,\u0006 ר' חייא\u0005],\u0006 כשלמדתי אצלו הלכות אלה, כלומר, לא היה בסבר פנים יפות עמי, \u0003דאישייליה\u0004 \u0005[שאשאל אותו]\u0006 שאלה זו, ואין לי אלא מה ששמעתי.","ומעירים: וכן \u0003אתמר\u0004 \u0005[נאמרה]\u0006 מחלוקת אמוראים בענין זה, \u0003אמר רב:\u0004 שהייה הפוסלת היא \u0003כדי שחיטת בהמה לבהמה ועוף לעוף, ושמואל אמר: אפילו\u0004 שהייה כדי שחיטת \u0003בהמה לעוף. וכן כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין אמר ר' יוחנן: אפילו\u0004 שהייה כדי שחיטת \u0003בהמה לעוף.\u0004","\u0003ר' חנניא אמר:\u0004 השהייה הפוסלת היא \u0003כדי שיביא בהמה אחרת וישחוט.\u0004 ותוהים: \u0003יביא אפילו מעלמא\u0004 \u0005[מהעולם],\u0006 ממקום אחר? אם כן \u0003נתת דבריך לשיעורין,\u0004 שלעיתים מצויה בהמה במקום קרוב ולעיתים במקום רחוק!","\u0003אמר רב פפא:\u0004 בהמה ה\u0003עומדת\u0004 לפניו \u0003להטיל\u0004 אותה מיד לארץ כדי לשוחטה \u0003איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 שלדעת ר' חנניא כל שלא שהה כדי שיעור הטלה על הארץ ושחיטה — אין זה פוסל.","\u0003אמרי במערבא משמיה\u0004 \u0005[אמרו בארץ ישראל משמו]\u0006 של \u0003ר' יוסי בר' חנינא:\u0004 שיעור השהייה הפוסלת הוא \u0003כדי שיגביהנה\u0004 לבהמה מן הארץ, ויחזור \u0003וירביצנה\u0004 (יוריד אותה לארץ) \u0003וישחוט,\u0004 ושיעור הזמן הנצרך לשם כך בבהמה \u0003דקה\u0004 גורם \u0003ל\u0004פסול שחיטת בהמה \u0003דקה, ו\u0004הזמן הנצרך לעשות כן בבהמה \u0003גסה\u0004 גורם \u0003ל\u0004פסול שחיטת בהמה \u0003גסה.\u0004","\u0003אמר רבא: השוחט בסכין רעה\u0004 שאינה מחודדת יפה (אך אינה פגומה), \u0003אפילו\u0004 היה שוחט משום כך את הבהמה במשך \u0003כל היום כולו\u0004 — שחיטתו \u0003כשרה.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: שהיות\u0004 רבות בתוך שחיטה אחת, שאין בכל אחת מהן שיעור שהייה פסולה, \u0003מהו שיצטרפו\u0004 לשיעור שהייה שלם כדי לפסול?","ותוהים: \u0003ותפשוט לה מדידיה\u0004 \u0005[ותפתור לו\u0006 לרבא \u0005את הבעיה מ\u0006דברי \u0005עצמו],\u0006 שהכשיר שחיטה הנמשכת במשך כל היום כולו, ומכאן שאין שהיות מצטרפות! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 מדובר כש\u0003לא שהה\u0004 כלל באמצע, שהיה שוחט והולך בלי הפסק.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נתן:\u0004 אם \u0003שהה במיעוט סימנין,\u0004 שלאחר ששחט את רובם שהה ואחר כך גמר את השחיטה, \u0003מהו?\u0004 שאלה זו לא נפתרה ונשארה \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","שנינו במשנתנו, \u0003ר' שמעון אומר: אם שהה כדי ביקור\u0004 (בדיקה) — השחיטה פסולה. ושואלים: \u0003מאי\u0004 \u0005[מה פירוש]\u0006 \u0003כדי ביקור? אמר ר' יוחנן: כדי ביקרו של חכם,\u0004 שיבוא ויבדוק את הסכין אם היא כשרה. ומקשים: \u0003אם כן, נתת דבריך לשיעורין,\u0004 שפעמים החכם רחוק ופעמים קרוב! \u0003אלא\u0004 הכוונה היא: \u0003כדי ביקור\u0004 של \u0003טבח\u0004 (שוחט) \u0003חכם,\u0004 כלומר, כדי הזמן שלוקח לשוחט עצמו כשהוא חכם לבדוק את סכינו.","\u0003שחט את הוושט\u0004 כדרכו, בהולכה והבאה, \u0003ופסק\u0004 (חתך) \u0003את הגרגרת\u0004 (הקנה) שלא בדרך שחיטה, \u0003או פסק את הגרגרת ואחר כך שחט את הוושט, או שחט אחד מהן\u0004 מן הסימנים \u0003והמתין לה עד שמתה, או ש\u0004לאחר ששחט אחד מהם \u0003החליד\u0004 (תחב) \u0003את הסכין תחת\u0004 הסימן \u0003השני ופסקו\u0004 (וחתכו) מלמטה למעלה, בכל המקרים האלו, שהשחיטה פסולה, נחלקו חכמים מה דינה של הבהמה, \u0003ר' ישבב אומר:\u0004 בהמה זו \u0003נבלה\u0004 היא, ומטמאה את הנוגע בה או נושא אותה. \u0003ר' עקיבא אומר: טרפה\u0004 היא, שאסורה באכילה, אך אינה קרויה נבילה, מאחר שהפסול היה במהלך שחיטה.","\u0003כלל אמר ר' ישבב משום\u0004 (בשם) \u0003ר' יהושע: כל שנפסלה בשחיטתה,\u0004 שנשחטה שלא כראוי — הריהי \u0003נבלה, כל ששחיטתה\u0004 נעשתה \u0003כראוי, ודבר אחר גרם לה ליפסל\u0004 — הריהי \u0003טרפה. ו\u0004כששמע דבר זה \u0003הודה לו רבי עקיבא\u0004 לדבריו.","שנינו במשנה: \u0003שחט את הוושט וכו', והודה לו רבי עקיבא.\u0004 לר' ישבב שאם פסק (חתך) את הגרגרת — נבילה היא ולא טריפה. \u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה לכך\u0005],\u0006 מה ששנינו במשנה להלן, \u0003אלו טרפות בבהמה:\u0004"],["\u0003נקובת הוושט, ופסוקת הגרגרת,\u0004 הרי שפסוקת הגרגרת טריפה היא ולא נבילה, ואם חזר בו ר' עקיבא, כשיטת מי היא משנה זו?","\u0003אמר רבא, לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003כאן\u0004 במשנתנו, מדובר כ\u0003ששחט\u0004 את הוושט \u0003ולבסוף פסק\u0004 את הגרגרת, ו\u0003כאן\u0004 ב\"אלו טרפות\", מדובר \u0003שפסק\u0004 את הגרגרת \u0003ולבסוף שחט\u0004 את הוושט. ומהו ההבדל? אם \u0003שחט\u0004 תחילה את הוושט \u0003ולבסוף\u0004 לאחר מכן \u0003פסק\u0004 את הגרגרת — \u0003נפסלת ב\u0004מהלך ה\u0003שחיטה היא,\u0004 ולכן יש לה דין נבילה, כמו הכלל ששנה ר' ישבב במשנתנו, אם \u0003פסק ולבסוף שחט\u0004 — \u0003כי\u0004 \u0005[כמו]\u0006 ש\u0003דבר אחר גרם לה ליפסל\u0004 קודם שחיטה \u0003דמיא\u0004 \u0005[נחשבת],\u0006 ולכן יש לה דין טריפה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב אחא בר הונא לרבא\u0004 ממה ששנינו בברייתא: \u0003שחט את הוושט ופסק את הגרגרת\u0004 (הקנה), או \u0003פסק\u0004 תחילה \u0003את הגרגרת ואחר כך שחט את הוושט\u0004 — \u0003נבלה.\u0004 הרי שאין הבדל בין זה לזה, וגם אם פסק את הגרגרת מתחילה נבילה היא!","אמר לו, \u0003אימא\u0004 \u0005[אמור,\u0006 הסבר\u0005]\u0006 כך את המקרה השני: או פסק את הגרגרת, \u0003וכבר שחט את הוושט מעיקרא\u0004 \u0005[מתחילה],\u0006 ודווקא בכגון זה הרי זו נבילה, שהרי התחיל בשחיטה, אבל אם פסק את הגרגרת מתחילה — טריפה היא.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אחא, \u0003שתי תשובות בדבר: חדא\u0004 \u0005[אחת],\u0006 \u0003דהיינו קמייתא\u0004 \u0005[ש\u0006אם כן \u0005זו היא\u0006 בדיוק ההלכה \u0005הראשונה]:\u0006 שחט את הוושט ופסק את הגרגרת! \u0003ועוד, הא תנן\u0004 \u0005[הרי שנינו]\u0006 במפורש במשנתנו: פסק את הגרגרת \u0003ואחר כך\u0004 שחט את הוושט, שהיא נבילה!","\u0003אלא אמר רבא:\u0004 מה ששנינו להלן \"אלו טרפות\" — אין הכוונה דווקא לטריפות, אלא \u0003אלו אסורות קתני\u0004 \u0005[הוא שונה],\u0006 \u0003ויש מהן נבלות,\u0004 כגון פסוקת הגרגרת, ששנינו במשנתנו שהיא נבילה, \u0003ויש מהן טרפות.\u0004","ומקשים: אם הוא מונה את כל האסורות, וגם הנבילות, \u0003וליחשוב נמי\u0004 \u0005[ושימנה גם כן]\u0006 את זו של \u0003חזקיה,\u0004 ש\u0003אמר חזקיה:\u0004 אם \u0003עשאה גיסטרא,\u0004 שחתכה לשנים — הריהי \u0003נבלה!\u0004 \u0003וליחשוב נמי\u0004 \u0005[ו\u0006כן \u0005שימנה גם כן]\u0006 מה שאמר \u0003ר' אלעזר,\u0004 ש\u0003אמר רבי אלעזר:\u0004 אם \u0003נטלה\u0004 ה\u0003ירך וחלל שלה\u0004 ניכר — הרי זו \u0003נבלה!\u0004","ומשיבים: \u0003כי קתני\u0004 \u0005[כאשר הוא שונה]\u0006 ברשימה זו נבילות, הרי זו \u0003נבלה דלא\u0004 \u0005[שאינה]\u0006 \u0003מטמאה מחיים,\u0004 אלא רק במותה, \u0003אבל נבלה\u0004 ש\u0003מטמאה\u0004 כבר \u0003מחיים לא קתני\u0004 \u0005[אינו שונה],\u0006 ושתי אלו נחשבות נבילה כבר בחייהן, כאילו כבר מתו.","\u0003ר' שמעון בן לקיש אמר,\u0004 יש לחלק באופן אחר: \u0003כאן,\u0004 ששנינו במשנתנו שאם חתך תחילה את הגרגרת ואחר כך שחט את הוושט נבילה היא, מדובר \u0003ששחט\u0004 את הוושט \u0003במקום\u0004 ש\u0003חתך\u0004 את הגרגרת, \u0003כאן,\u0004 ששנינו ב\"אלו טרפות\" שטריפה היא, מדובר \u0003ששחט שלא במקום\u0004 ש\u0003חתך.\u0004 וטעם הדבר: אם \u0003שחט במקום\u0004 ה\u0003חתך\u0004 — \u0003נפסלה בשחיטה היא,\u0004 ודינה כנבילה, אבל אם שחט \u0003שלא במקום חתך\u0004 — \u0003כי\u0004 \u0005[כמו]\u0006 ש\u0003דבר אחר גרם לה ליפסל\u0004 מתחילה \u0003דמיא\u0004 \u0005[נחשבת],\u0006 ולכן שחיטת הוושט מועילה לטהרה מטומאת נבילה.","ושואלים: \u0003ומי אמר\u0004 \u0005[והאם אומר]\u0006 \u0003ר' שמעון בן לקיש הכי\u0004 \u0005[כך],\u0006 ששחיטה יכולה להועיל לאחר שנפסק הקנה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' שמעון בן לקיש: שחט את הקנה ואחר כך ניקבה הריאה,\u0004 קודם ששחט את הוושט — \u0003כשרה,\u0004 אינה טריפה משום כך \u0003אלמא כמאן דמנחא בדיקולא דמיא\u0004 \u0005[מכאן ש\u0006לאחר שחיטת הקנה \u0005נחשבת\u0006 הריאה התלויה בקנה \u0005כאילו\u0006 ניטלה מן הבהמה יחד עם הקנה ו\u0005מונחת בסל],\u0006 ומה שאירע בה אינו משפיע על דינה של הבהמה. ולפי זה, \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 כשנפסקה הגרגרת (הקנה) בתחילת השחיטה, נאמר שהגרגרת \u0003כמאן דמנחא בדיקולא דמיא\u0004 \u0005[כמי שמונחת בסל\u0006 היא \u0005נחשבת],\u0006 ואין בבהמה אלא סימן אחד העומד לשחיטה הוושט, ולא תועיל שחיטת סימן אחד להוציאה מידי נבילה!","\u0003אלא אמר ר' חייא בר אבא אמר ר' יוחנן: לא קשיא\u0004 \u0005[אין זה קשה],\u0006 \u0003כאן\u0004 ששנינו ב\"אלו טרפות\" שפסוקת הגרגרת היא טריפה, מדובר \u0003קודם חזרה,\u0004 לפני שחזר בו ר' עקיבא מדבריו, \u0003כאן\u0004 במשנתנו מדובר \u0003לאחר חזרה. ו\u0004אף על פי שחזר בו ר' עקיבא, \u0003משנה\u0004 ראשונה ששנינו \u0003לא זזה ממקומה.\u0004","ודנים \u0003גופא\u0004 \u0005[\u0006ל\u0005גופה]\u0006 של ההלכה שהזכרנו, \u0003אמר ר' שמעון בן לקיש: שחט את הקנה ואחר כך ניקבה הריאה\u0004 — הבהמה \u0003כשרה. אמר רבא: לא אמר ר' שמעון בן לקיש\u0004 שהיא כשרה \u0003אלא ב\u0004שניקבה ה\u0003ריאה\u0004 בלבד, \u0003הואיל וחיי ריאה תלויה בקנה,\u0004 וכיון שנשחט הקנה רואים אותה כאילו ניטלה מן הבהמה, וכל פגם שנעשה בה אינו פוסל. \u0003אבל\u0004 אם נעשה נקב \u0003בבני מעיים\u0004 לאחר שחיטת הקנה — \u0003לא,\u0004 שאין חיותם תלויה בקנה אלא בוושט, והוא נשחט לאחר הקנה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' זירא: מאחר ש\u0004כאשר \u0003נולדו בה סימני טרפה\u0004 לאחר שהחלה השחיטה \u0003התרת\u0004 אותה, \u0003מה לי\u0004 אם היה נקב \u0003בריאה מה לי\u0004 אם היה \u0003בבני מעיים!\u0004 אלא בכל אופן אינה נעשית טריפה לאחר שהחלה השחיטה.","ומעירים: \u0003והדר ביה\u0004 \u0005[וחזר בו]\u0006 \u0003ר' זירא\u0004 מדבריו, \u0003דבעי\u0004 \u0005[ששאל]\u0006 \u0003ר' זירא: ניקבו בני מעיים בין\u0004 שחיטת \u0003סימן לסימן, מהו? מי\u0004 \u0005[האם]\u0006 \u0003מצטרף סימן ראשון לסימן שני לטהרה\u0004 בשחיטה זו \u0003מידי נבלה, או לא?\u0004","\u0003ואמרינן\u0004 \u0005[ואמרנו]\u0006 על כך, \u0003לאו היינו דבעי\u0004 \u0005[האם לא זו\u0006 השאלה \u0005ששאל]\u0006 החכם \u0003אילפא:\u0004 השוחט בהמה מעוברת ו\u0003הוציא\u0004 ה\u0003עובר את ידו\u0004 מן הרחם \u0003בין\u0004 שחיטת \u0003סימן לסימן,\u0004 ובכך נעשתה היד טריפה, \u0003מהו\u0004 הדין?"],["\u0003מי\u0004 \u0005[האם]\u0006 \u0003מצטרף סימן ראשון\u0004 בשחיטה \u0003לסימן שני לטהרה\u0004 על כל פנים \u0003מידי נבלה או לא?\u0004","ועל כל פנים, \u0003עד כאן לא איבעיא לן\u0004 \u0005[לא נשאלה לנו,\u0006 לר' זירא\u0005]\u0006 השאלה, כשניקבו בני המעיים לאחר שנשחט סימן אחד, \u0003אלא\u0004 כדי \u0003לטהרה מידי נבלה, אבל באכילה\u0004 היא \u0003אסורה,\u0004 שטריפה היא. ומכאן שחזר בו ר' זירא ממה שאמר שאם נולדו בבהמה סימני טריפה לאחר שחיטת הקנה אין היא נאסרת משום טריפה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בר רב לרבינא: דלמא\u0004 \u0005[שמא]\u0006 \u0003לעולם לא הדר ביה\u0004 \u0005[לא חזר בו]\u0006 ר' זירא, וגם מתחילה היה סבור שהיא נעשית טריפה לאחר שחיטת סימן אחד, \u0003ור' זירא\u0004 שאמר לרבא: מאחר שנולדו בה סימני טריפה התרת, מה לי בריאה מה לי בבני מעיה — \u0003לדבריו,\u0004 לפי שיטתו, של \u0003רבא קאמר\u0004 \u0005[הוא אומר],\u0006 שחילק כן בדעת ריש לקיש, \u0003וליה לא סבירא ליה\u0004 \u0005[ו\u0006אולם \u0005לו\u0006 לר' זירא עצמו הוא \u0005אינו סבור כן],\u0006 אלא לדעתו, גם לאחר שנשחט סימן אחד בבהמה הריהי נעשית טריפה.","ושבים לדבריו של ריש לקיש, שלאחר שנשחט הקנה נחשבת הריאה כמי שניטלה מן הבהמה ו\"מונחת בסל\", ואם ניקבה קודם שנגמרה השחיטה — אין זה עושה את הבהמה טריפה. \u0003אמר רב אחא בר יעקב, שמע מינה\u0004 \u0005[למד ממנה]\u0006 \u0003מ\u0004דבריו של \u0003ר' שמעון בן לקיש: מזמנין\u0004 את \u0003ישראל על בני מעיים\u0004 של בהמה שנשחטה, שיבוא ויאכל עמו, \u0003ואין מזמנין\u0004 את ה\u0003גוים על בני מעיים\u0004 של בהמה שנשחטה, מפני שהם אסורים עליהם באכילה.","\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 אצל \u0003ישראל\u0004 ש\u0003בשחיטה תליא מילתא\u0004 \u0005[תלוי הדבר],\u0006 שהשחיטה שציותה התורה היא המתירה את הבהמה באכילה, \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 \u0003שחיטה מעלייתא\u0004 \u0005[מעולה,\u0006 כשרה\u0005]\u0006 שנשחטו רוב שני הסימנים — \u0003אישתרי להו\u0004 \u0005[הותרו להם]\u0006 בני המעיים, אף שהבהמה עדיין לא מתה לגמרי. ואילו \u0003גוים\u0004 ש\u0003בנחירה\u0004 (בהריגה) של הבהמה \u0003סגי להו\u0004 \u0005[די להם],\u0006 כדי שלא לעבור על אכילת אבר מן החי, שגם הם אסורים בו, הואיל \u0003ובמיתה תליא מילתא\u0004 \u0005[תלוי הדבר],\u0006 ורק אחרי שהבהמה מתה לגמרי היא מותרת להם, ולא על ידי שחיטה, \u0003הני\u0004 \u0005[אותם]\u0006 בני מעיים, שלאחר שחיטת הסימנים נחשבים כאילו הוצאו מגוף הבהמה בעודה חיה — \u0003כאבר מן החי דמו\u0004 \u0005[נחשבים],\u0006 ולכן הם אסורים עליהם באכילה.","\u0003אמר רב פפא: הוה יתיבנא קמיה\u0004 \u0005[הייתי יושב לפני]\u0006 \u0003רב אחא בר יעקב, ובעי דאימא ליה\u0004 \u0005[ורציתי לומר לו]:\u0006 לפי דבריך הרי זה תמוה, \u0003מי איכא מידי\u0004 \u0005[האם יש דבר]\u0006 ש\u0003לישראל שרי\u0004 \u0005[מותר]\u0006 \u0003ולגוי אסור? ולא אמרי ליה\u0004 \u0005[ולא אמרתי לו],\u0006 לא שאלתי אותו שאלה זו, מפני \u0003דאמינא\u0004 \u0005[שאמרתי]\u0006 בלבי: \u0003הא טעמא קאמר\u0004 \u0005[הרי טעם הוא אומר\u0006 לדבריו\u0005],\u0006 ומה לי לשאול.","ומעירים: \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 ש\u0003לא כ\u0004דברי \u0003רב אחא בר יעקב: הרוצה לאכול מבהמה\u0004 עוד \u0003קודם שתצא נפשה,\u0004 שעשה כן לשם רפואה — \u0003חותך כזית בשר מבית\u0004 (ממקום) \u0003השחיטה\u0004 \u0003ומולחו יפה יפה ומדיחו יפה יפה, וממתין לה עד שתצא נפשה\u0004 של הבהמה \u0003ואוכלו,\u0004 ודבר זה \u0003אחד גוי ואחד ישראל מותרין בו.\u0004 משמע שאין חילוק בזה בין ישראל לגוי.","ומעירים: \u0003מסייע ליה\u0004 \u0005[לו]\u0006 הדבר \u0003לרב אידי בר אבין,\u0004 ש\u0003אמר רב אידי בר אבין אמר ר' יצחק בר אשיאן: הרוצה שיבריא\u0004 ויתחזק, \u0003חותך כזית בשר מבית שחיטתה של בהמה ומולחו יפה יפה ומדיחו יפה יפה,\u0004 \u0003וממתין לה עד שתצא נפשה,\u0004 ו\u0003אחד גוי ואחד ישראל מותרין בו.\u0004","\u0003השוחט בהמה חיה ועוף ולא יצא מהן דם\u0004 בזמן השחיטה — הרי הם \u0003כשרים,\u0004 וכיון שלא יצא מהם דם הריהם \u0003נאכלין בידים מסואבות\u0004 (טמאות), כלומר, בלא נטילת ידים, \u0003לפי שלא הוכשרו\u0004 לקבל טומאה על ידי ה\u0003דם,\u0004 ואין אוכל מקבל טומאה אלא אם בא עליו אחד משבעה משקים, ובהם דם. \u0003ר' שמעון אומר: הוכשרו\u0004 לקבל טומאה \u0003בשחיטה\u0004 עצמה.","ומדייקים: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 מפני ש\u0003לא יצא מהן דם\u0004 הריהם נאכלים בידיים מסואבות, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003יצא מהן דם\u0004 — \u0003אין נאכלים בידים מסואבות.\u0004 ויש לתמוה: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 הלוא סתם \u0003ידים\u0004 בדרגת \u0003שניות\u0004 לטומאה \u0003הן, ואין שני\u0004 לטומאה שנגע בחולין \u0003עושה שלישי\u0004 \u0003בחולין\u0004 שנגע בהם, אינו מטמא אותם כלל, אלא רק בתרומה וקדשים!","ומוסיפים: \u0003וממאי\u0004 \u0005[ומנין]\u0006 ש\u0003ב\u0004בהמה חיה ועוף של \u0003חולין עסקינן\u0004 \u0005[עוסקים אנו],\u0006 ולא בקדשים, שסתם ידים מטמאות אותן? \u0003דקתני\u0004 \u0005[ש\u0006הרי \u0005הוא שונה]\u0006 בה \u0003חיה,\u0004 ש\u0003אילו\u0004 היה מדובר ב\u0003קדשים, חיה בקדשים מי איכא\u0004 \u0005[האם יש]?\u0006 הרי אין קרבן מן החיה! \u0003ותו\u0004 \u0005[ועוד],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 מדובר \u0003בקדשים, כי\u0004 \u0005[כאשר]\u0006 \u0003לא יצא מהן דם כשרה\u0004 היא? והרי בקדשים \u0003הוא עצמו לדם הוא צריך,\u0004 לצורך זריקה על המזבח, וקרבן שלא נזרק דמו לא הורצה!","\u0003ותו\u0004 \u0005[ועוד],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 מדובר \u0003בקדשים, כי\u0004 \u0005[כאשר]\u0006 \u0003יצא מהן דם מי\u0004 \u0005[האם]\u0006 \u0003מכשיר\u0004 הוא לקבל טומאה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' חייא בר אבא אמר רבי יוחנן: מנין לדם קדשים שאינו מכשיר\u0004 אוכלים לקבל טומאה? \u0003שנאמר: \"על הארץ תשפכנו כמים\"\u0004 (דברים יב, טז), ומכאן אנו למדים ש\u0003דם שנשפך כמים,\u0004 שאין בו שימוש, כלומר, דם חולין — הוא \u0003מכשיר\u0004 אוכלים לקבל טומאה, כמים שהזכיר הכתוב בענין זה (\"וכי יותן מים על זרע\" וכו'. ויקרא יא, לח), אבל דם \u0003שאינו נשפך כמים,\u0004 דם הקדשים, שמקבלים אותו בכלי לשם זריקה על המזבח — \u0003אינו מכשיר!\u0004","\u0003ותו\u0004 \u0005[ועוד]\u0006 יש לשאול: \u0003אי\u0004 \u0005[אם]\u0006 מדובר \u0003בקדשים,\u0004 הרי גם \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003לא יצא מהם דם לא מתכשרי\u0004 \u0005[אינם מוכשרים]\u0006 לקבל טומאה, מכל מקום \u0003ליתכשרי\u0004 \u0005[שיהיו מוכשרים]\u0006 לקבלת טומאה \u0003בחיבת הקדש, דקיימא לן\u0004 \u0005[שמוחזק בידינו]\u0006 ש\u0003חיבת הקדש מכשרתן\u0004 לקדשים לקבל טומאה, אף על פי שלא באו עליהם משקים!","\u0003אמר רב נחמן אמר רבה בר אבוה: הכא\u0004 \u0005[כאן]\u0006 במשנתנו \u0003בחולין שלקחן\u0004 (קנה אותם) בירושלים \u0003בכסף מעשר\u0004 שני \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שיש להם קדושת מעשר שני, ושני עושה בהם שלישי. \u0003ו\u0004משנה זו ש\u0003לא כ\u0004שיטת \u0003ר' מאיר\u0004 היא, \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006"],["\u0003כל הטעון ביאת מים,\u0004 טבילה או נטילת ידים, \u0003מדברי סופרים,\u0004 אף שמן התורה הוא טהור — הריהו שני לטומאה, ש\u0003מטמא את הקדש,\u0004 כגון בשר קדשים, \u0003ופוסל את התרומה,\u0004 והיא עצמה טמאה, אבל אינה מטמאה תרומה אחרת שנגעה בה, \u0003ומותר בחולין ובמעשר\u0004 שני, אלו \u0003דברי ר' מאיר,\u0004","\u0003וחכמים אוסרים במעשר.\u0004 ומכאן שלשיטתם מעשר חמור מן החולין, ושני שנגע במעשר עושה אותו שלישי, וכשיטת משנתנו.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב שימי בר אשי: ממאי\u0004 \u0005[ממה,\u0006 מנין\u0005]\u0006 מסיק אתה שכך היא דעת חכמים? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003פליגי רבנן עליה\u0004 \u0005[חלוקים חכמים עליו]\u0006 על \u0003רבי מאיר אלא ב\u0004יחס ל\u0003אכילת מעשר,\u0004 שאסור לשני לטומאה לאכול מעשר, \u0003אבל בנגיעה\u0004 ב\u0003מעשר ו\u0004כן ב\u0003אכילה\u0004 של \u0003חולין לא פליגי\u0004 \u0005[אינם חולקים],\u0006 וגם הם מתירים, שלדעתם אין שני שנגע במעשר עושה אותו שלישי לפוסלו.","\u0003והא\u0004 \u0005[ו\u0006הרי \u0005זו]\u0006 ששנינו במשנתנו — בענין \u0003נגיעה היא, מדקתני\u0004 \u0005[ממה שהוא שונה]\u0006 בלשון \u0003\"נאכלין בידים מסואבות\",\u0004 ולא \"אוכלים אותם בידים מסואבות\"; \u0003מי לא עסקינן\u0004 \u0005[האם אין אנו עוסקים]\u0006 במקרה \u0003דקא ספי ליה חבריה\u0004 \u0005[שמאכיל אותו חבירו]\u0006 שידיו מסואבות, והאוכל עצמו אינו נוגע בהם? ודווקא מפני שלא הוכשרו בדם הותר לגעת בהם בידים מסואבות, אבל אם הוכשרו בדם — אסור לנגוע בהם בידים מסואבות! ואם כן לא ניתן להעמיד את משנתנו בבשר שנקנה בכסף מעשר שני.","\u0003אלא אמר רב פפא: הכא\u0004 \u0005[כאן]\u0006 במשנתנו, \u0003בידים\u0004 שהן \u0003תחלות\u0004 (בדרגת ראשון) לטומאה \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שמטמאות את החולין (אם הוכשרו), \u0003ו\u0004משנתנו שיטת \u0003ר' שמעון בן אלעזר היא,\u0004 הסבור שיש ידים שהן נחשבות תחילה לטמא את החולין. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 כשאמרו חכמים שידים נחשבות תחלות לטומאה, \u0003אין\u0004 אומרים שה\u0003ידים\u0004 \u0003תחלות ל\u0004ענין \u0003חולין,\u0004 אלא רק לענין תרומה וקדשים. \u0003ר' שמעון בן אלעזר אומר משום\u0004 (בשם) \u0003ר' מאיר:\u0004 כשאמרו חכמים ש\u0003ידים\u0004 הן \u0003תחלות,\u0004 לטמא אוכלים — הרי זה \u0003לחולין, ו\u0004כשאמרו שהן \u0003שניות\u0004 — הרי זה \u0003לתרומה\u0004 לפוסלה.","ותוהים: \u0003תחלות לחולין\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003לתרומה\u0004 — \u0003לא?\u0004 כיצד אפשר לומר שראשון לטומאה לא יטמא את התרומה? אלא \u0003הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 כשאמרו שהן \u0003תחלות\u0004 — \u0003אף לחולין\u0004 נאמר הדבר, אבל כשגזרו עליהן שתהיינה \u0003שניות\u0004 — \u0003לתרומה אין\u0004 \u0005[כן]\u0006 נאמר הדבר, שהן פוסלות אותה, \u0003לחולין\u0004 — \u0003לא,\u0004 שאין שני עושה שלישי בחולין.","ושואלים: \u0003ומי איכא\u0004 \u0005[והאם יש]\u0006 \u0003ידים\u0004 שהן \u0003תחלות\u0004 לטומאה? ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 משנה\u0005]:\u0006 \u0003הכניס ידיו\u0004 בלבד \u0003לבית המנוגע\u0004 בנגע צרעת — \u0003ידיו תחלות\u0004 לטומאה, כאילו היה נכנס כולו לבית, שנאמר בו שהוא טמא (ויקרא יד, מו), אלו \u0003דברי ר' עקיבא, וחכמים אומרים: ידיו שניות.\u0004","ומסבירים את המחלוקת: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003ביאה במקצת\u0004 לבית המנוגע — \u0003לא שמה\u0004 (אינה נקראת) \u0003ביאה,\u0004 לטמא את הנכנס, ולכן מי שהכניס רק ידיו לבית אינו נטמא כלל מדין תורה. \u0003והכא\u0004 \u0005[וכאן]\u0006 \u0003בגזירה\u0004 שגזרו חכמים לטמא את \u0003ידיו\u0004 כשהכניסם לבית המנוגע, \u0003אטו\u0004 \u0005[משום]\u0006 כל \u0003גופו,\u0004 כדי שלא יבוא להיכנס כל גופו לבית המנוגע, \u0003קא מיפלגי\u0004 \u0005[חלוקים הם],\u0006","\u0003מר\u0004 \u0005[חכם זה,\u0006 ר' עקיבא\u0005]\u0006 \u0003סבר\u0004 \u0005[סבור]:\u0006 כשגזרו על \u0003ידיו\u0004 — \u0003כגופו שוינהו רבנן\u0004 \u0005[עשו אותם חכמים],\u0006 ולכן הן תחילות לטומאה, \u0003ומר\u0004 \u0005[וחכם זה,\u0006 חכמים\u0005]\u0006 \u0003סבר\u0004 \u0005[סבור]:\u0006 \u0003ידים\u0004 שנכנסו לבית המנוגע \u0003—\u0004 \u0003כידים דעלמא\u0004 \u0005[בכלל]\u0006 \u0003שוינהו רבנן\u0004 \u0005[עשו אותם חכמים],\u0006 ככל ידים שגזרו עליהם חכמים טומאה, שהן שניות לטומאה.","ושואלים: אם כן, מדוע מעמידים את משנתנו כר' אלעזר בר' שמעון? \u0003ולוקמה\u0004 \u0005[ושיעמיד אותה]\u0006 את משנתנו \u0003כר' עקיבא,\u0004 ש\u0003אמר: ידיו תחלות הויין\u0004 \u0005[הן]!\u0006 ומשיבים: \u0003דלמא כי קאמר\u0004 \u0005[שמא כאשר אומר]\u0006 \u0003ר' עקיבא\u0004 שידים תחילות לטומאה — \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 \u0003בתרומה וקדשים, דחמירי\u0004 \u0005[שהם חמורים],\u0006 \u0003אבל ל\u0004ענין \u0003חולין\u0004 אף הוא מודה ש\u0003שניות הויין\u0004 \u0005[הן].\u0006","ומקשים: \u0003וליהויין נמי\u0004 \u0005[ו\u0006אף אם \u0005יהיו גם כן]\u0006 \u0003שניות,\u0004 נוכל להעמיד את משנתנו כדעתו, \u0003דהא שמעינן ליה\u0004 \u0005[שהרי\u0006 כבר \u0005שמענו אותו]\u0006 את \u0003ר' עקיבא\u0004 ש\u0003אמר: שני עושה שלישי בחולין.\u0004 ולפי שיטתו, אם היה הבשר מוכשר בדם אינו רשאי לאוכלו בידים מסואבות, שהן שניות לטומאה!","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005],\u0006 \u0003בו ביום\u0004 שמינו את ר' אלעזר בן עזריה לראשות הישיבה ביבנה, \u0003דרש ר' עקיבא:\u0004 מה שנאמר בטומאת השרצים \u0003\"וכל כלי חרש\u0004 אשר יפול מהם אל תוכו, כל אשר בתוכו \u0003יטמא\"\u0004 (ויקרא יא, לו), יש לדייק בו: \u0003\"טמא\" לא נאמר\u0004 על מה שבתוך הכלי, \u0003אלא \"יטמא\"\u0004 — \u0003לטמא אחרים, לימד על ככר\u0004 שבתוך הכלי שהשרץ נפל לתוכו, שהוא \u0003שני\u0004 לטומאה, \u0003שהוא עושה שלישי בחולין!\u0004","ומשיבים: \u0003דלמא הני מילי\u0004 \u0005[שמא דברים אלה],\u0006 ששני עושה שלישי, נאמרו \u0003בטומאה\u0004 \u0003דאורייתא\u0004 \u0005[שמן התורה],\u0006 כגון שרץ, \u0003אבל בדרבנן\u0004 \u0005[ב\u0006טומאה שמ \u0005דברי סופרים]\u0006 \u0003לא,\u0004 וטומאת סתם ידים שבמשנתנו מדברי סופרים היא.","הסבר אחר למשנתנו \u0003אמר ר' אלעזר אמר ר' הושעיא:\u0004 הכא \u0005[כאן]\u0006 שדייקנו כי בשר חולין שהוכשר בדם השחיטה אינו נאכל בידים מסואבות, שהן שניות לטומאה, מפני שהן גורמות לו טומאה — \u0003בחולין שנעשו על טהרת הקדש עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שנוהגים בה דיני טהרה כאילו היו קדשים, ויש בהם שלישי לטומאה. \u0003ו\u0004משנתנו היא ש\u0003לא כ\u0004דעת \u0003ר' יהושע,\u0004 שהוא סבור שאין שני עושה בהם שלישי. \u0003דתניא\u0004 \u0005[ששנויה\u0006 משנה\u0005],\u0006 \u0003ר' אליעזר אומר:\u0004 האדם \u0003האוכל אוכל\u0004 (מאכל) שהוא \u0003ראשון\u0004 לטומאה — נעשה הוא עצמו \u0003ראשון\u0004 לטומאה, וכן האוכל אוכל \u0003שני\u0004 — נעשה \u0003שני,\u0004 וכן האוכל \u0003שלישי\u0004 — נעשה \u0003שלישי.\u0004","\u0003ר' יהושע אומר: האוכל אוכל\u0004 שהוא \u0003ראשון, ו\u0004כן האוכל אוכל שהוא \u0003שני\u0004 — הריהו נעשה \u0003שני\u0004 לטומאה. אם אכל מאכל שהוא \u0003שלישי\u0004 — הריהו נעשה עצמו \u0003שני לקדש,\u0004 ועושה שלישי ורביעי בקודש. \u0003ו\u0004אולם \u0003אין\u0004 הוא נעשה \u0003שני לתרומה,\u0004 ואם נגע בתרומה — אינו פוסל אותה.","וכל זה הוא \u0003בחולין שנעשו על טהרת תרומה.\u0004","ונדייק מכאן: בחולין שנעשו \u0003על טהרת תרומה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 אבל בחולין שנעשו \u0003על טהרת הקדש\u0004 — \u0003לא,\u0004 משמע ש\u0003קסבר\u0004 \u0005[סבור הוא]\u0006 ר' יהושע: \u0003חולין שנעשו על טהרת הקדש\u0004 \u0003לית בהו\u0004 \u0005[אין בהם]\u0006 \u0003שלישי.\u0004","ושואלים: \u0003ולוקמה\u0004 \u0005[ושיעמיד אותה]\u0006"],["\u0003בחולין שנעשו על טהרת תרומה, ו\u0004תאמר שהיא שיטת \u0003ר' יהושע,\u0004 ששני עושה בהם שלישי! ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[לא\u0006 יכול \u0005לעלות על דעתך]\u0006 דבר זה, \u0003דקתני\u0004 \u0005[ש\u0006הרי \u0005הוא שונה]\u0006 במשנתנו דין \u0003בשר, דאי\u0004 \u0005[שאם]\u0006 \u0003ב\u0004חולין שנעשו על טהרת \u0003תרומה\u0004 מדובר, \u0003בשר\u0004 שנאכל על טהרת תרומה \u0003מי איכא\u0004 \u0005[האם יש]?\u0006 הרי אין תרומה נוהגת אלא בפירות!","ומקשים: \u0003אלא מאי\u0004 \u0005[מה\u0006 אתה אומר\u0005],\u0006 שמדובר במשנה \u0003בקדשים,\u0004 כלומר, בבשר חולין שנאכל על טהרת הקודש? והרי משנתנו עוסקת גם בבשר חיה, וכי \u0003חיה בקדשים מי איכא\u0004 \u0005[האם יש]?\u0006 ומשיבים: יש להניח שהנוהגים לאכול בשר בטהרת הקודש, משום שהם רגילים באכילת קדשים — נוהגים כן גם בבשר חיה, מפני ש\u0003בשר בבשר מיחלף\u0004 \u0005[מוחלף],\u0006 אבל \u0003בשר בפירי לא מיחלף\u0004 \u0005[בפירות אינו מוחלף].\u0006","\u0003אמר עולא, חבריא אמרין\u0004 \u0005[החברים אומרים],\u0006 כפי שנאמר לעיל בשם ר' אלעזר, שמדובר במשנתנו \u0003בחולין שנעשו על טהרת הקדש,\u0004 ששני לטומאה עושה בהם שלישי לטומאה, ולכן אם היו מוכשרים בדם לקבל טומאה — אסור היה לאוכלם בידים מסואבות (שניות לטומאה), \u0003ו\u0004ש\u0003לא כ\u0004דברי \u0003ר' יהושע,\u0004 שאמר ששני עושה שלישי בחולין שנעשו על טהרת התרומה, אבל אינו עושה שלישי בחולין הנעשים על טהרת הקודש.","\u0003ואנא אמינא\u0004 \u0005[ואני אומר]\u0006 שמשנתנו שיטת \u0003ר' יהושע היא, ו\u0004מה שאמר ששני עושה שלישי בחולין שנעשו על טהרת התרומה — בלשון \u0003לא מיבעיא קאמר\u0004 \u0005[\u0006\u0005לא נצרכה הוא אומר]:\u0006 \u0003לא מיבעיא\u0004 \u0005[לא נצרכה\u0006 לומר\u0005]\u0006 \u0003חולין שנעשו על טהרת קדש דחמירי\u0004 \u0005[שהם חמורים]\u0006 אומר הוא \u0003דאית בהו\u0004 \u0005[שיש בהם]\u0006 \u0003שלישי\u0004 לטומאה, \u0003אלא אפילו חולין שנעשו על טהרת תרומה נמי אית בהו\u0004 \u0005[גם כן יש בהם]\u0006 \u0003שלישי.\u0004","ושואלים: \u0003מאן חבריא\u0004 \u0005[מי הם החברים]?\u0006 שיטת מי היא? שיטת \u0003רבה בר בר חנה היא,\u0004 ש\u0003אמר רבה בר בר חנה אמר ר' יוחנן: מאי אהדרי\u0004 \u0005[מה השיבו]\u0006 \u0003ר' אליעזר ור' יהושע להדדי\u0004 \u0005[זה לזה]?\u0006 שכאמור לעיל, ר' אליעזר אמר שהאוכל מאכל שהוא ראשון לטומאה נעשה בעצמו ראשון לטומאה, וכן האוכל מאכל שני נעשה שני, וכן האוכל מאכל שלישי נעשה שלישי. ואילו ר' יהושע אמר שהאוכל מאכל שהוא ראשון או שני — נעשה שני, והאוכל מאכל שהוא שלישי — נעשה שני לקודש, אבל לא לתרומה, בחולין שנעשו על טהרת התרומה.","כך \u0003אמר לו ר' אליעזר לר' יהושע:\u0004 מה שאני אומר שדינו של האדם האוכל יהיה כדין המאכל שהכניס לפיו, ולא כרגיל בדיני טומאה, שהנוגע בטומאה יורד בדרגת הטומאה — שהרי \u0003מצינו\u0004 יותר מכך, שדין האיש \u0003ה\u0004\u0003אוכל חמור\u0004 לענין טומאה יותר \u0003מן האוכל\u0004 שהכניס לפיו, ש\u0003אילו נבלת עוף טהור\u0004 כשהיא \u0003בחוץ\u0004 כלומר, כשהוא נוגע בה — \u0003לא מטמא\u0004 כלל, \u0003ואילו\u0004 האדם ה\u0003אוכלה מטמא בגדים\u0004 כשהיא מצויה ב\u0003בית הבליעה\u0004 שלו, \u0003ו\u0004אם כן \u0003אנו היאך לא נעשה\u0004 את ה\u0003אוכל\u0004 חמור לכל הפחות \u0003כמאכל\u0004 שהכניס לפיו?","\u0003ור' יהושע\u0004 אומר: \u0003מנבלת עוף טהור לא גמרינן\u0004 \u0005[אין אנו למדים],\u0006 מפני ש\u0003חידוש הוא,\u0004 הלכה מיוחדת בדיני טומאות, ואין למדים מן החידוש. \u0003אלא\u0004 להיפך, \u0003מצינו שהמאכל חמור מן האוכל,\u0004 ש\u0003אילו מאכל\u0004 מקבל טומאה כשיש בו שיעור \u0003בכביצה, ו\u0004אילו האדם ה\u0003אוכל\u0004 אוכלים טמאים אינו טמא \u0003עד דאכיל\u0004 \u0005[ש\u0006הוא \u0005אוכל]\u0006 \u0003כחצי פרס,\u0004 שהוא שיעור שתי ביצים, \u0003ו\u0004אם כן, \u0003אנו היאך נעשה\u0004 את טומאת האדם ה\u0003אוכל כ\u0004טומאת","\u0003ה\u0004\u0003מאכל? ור' אליעזר,\u0004 מה הוא עונה על כך? לדעתו, את חומרת ה\u0003טומאה משיעורין לא גמרינן\u0004 \u0005[אין אנו למדים],\u0006 ששיעורי הטומאה אינם ענין של חומרה וקולה, ואין הדברים שייכים זה לזה. \u0003ועוד\u0004 מוסיף ר' אליעזר: \u0003לדבריך,\u0004 מה \u0003שאתה אומר על\u0004 מי שאוכל מאכל שהוא \u0003ראשון\u0004 לטומאה שהוא עצמו נעשה \u0003שני\u0004 — \u0003יפה אתה אומר,\u0004 אבל מי שאוכל מאכל שהוא \u0003שני, שני למה\u0004 הוא נעשה?","\u0003אמר לו\u0004 ר' יהושע: \u0003מצינו\u0004 (מצאנו) \u0003שהשני עושה\u0004 את הנוגע בו \u0003שני על ידי משקין,\u0004 שמשקים הנוגעים באוכל שהוא שני לטומאה, עושים אוכל אחר שנגעו בו שני לטומאה.","\u0003אמר לו\u0004 ר' אליעזר: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003משקין נמי\u0004 \u0005[גם כן]\u0006 \u0003תחלה\u0004 (ראשון) לטומאה \u0003הוו\u0004 \u0005[הם]\u0006 נעשים כשנגעו בשני, \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003כל הפוסל בתרומה\u0004 כלומר, השני לטומאה — \u0003מטמא\u0004 את ה\u0003משקין להיות תחלה\u0004 (ראשון) לטומאה, \u0003חוץ מטבול יום\u0004 (אדם שטבל מטומאתו ועדיין לא שקעה השמש), שלמרות שהוא שני לטומאה ופוסל את התרומה, אינו עושה את המשקה שנגע בו ראשון לטומאה.","\u0003ועוד\u0004 הקשה לו ר' אליעזר: לדבריך, שאין דין האדם האוכל חמור מדין המאכל, האוכל מאכל שהוא \u0003שלישי, שני\u0004 לקודש \u0003למה\u0004 הוא נעשה?","אמר לו ר' יהושע: \u0003אף אני לא אמרתי\u0004 דבר זה \u0003אלא ב\u0004חולין הנעשים על טהרת ה\u0003תרומה, שטהרתה\u0004 (מה שנחשב טהור לתרומה)"],["\u0003טומאה היא\u0004 נחשבת \u0003אצל הקדש,\u0004 שאדם המקפיד לאכול תרומה בטהרה נחשב טמא למי שאוכל קדשים. ולכן גם אם אכל דבר שהוא שלישי ופסול בתרומה, ייעשה שני לטמא את הקודש.","\u0003אמר ר' זירא אמר ר' אסי אמר ר' יוחנן אמר ר' ינאי: האוכל\u0004 מאכל שהוא \u0003שלישי\u0004 לטומאה \u0003של חולין שנעשו על טהרת הקדש\u0004 — \u0003נעשה גופו שני לקדש,\u0004 שעושה שלישי ורביעי בקודש.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' זירא לר' אסי\u0004 ממה ששנינו בדברי ר' יהושע: \u0003שלישי\u0004 עושה \u0003שני לקדש ואין\u0004 עושה \u0003שני לתרומה, בחולין שנעשו על טהרת תרומה.\u0004 ונדייק מכאן: בחולין שנעשו \u0003על טהרת תרומה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 שלישי שבהם עושה שני לקודש, אבל בחולין שנעשו \u0003על טהרת הקדש\u0004 — \u0003לא!\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 אין לדייק כך, אלא בלשון \u0003לא מיבעיא קאמר\u0004 \u0005[לא נצרכה אמר],\u0006 כלומר, לא רק בחולין הנעשים על טהרת הקודש, שטהרתו חמורה — האוכל שלישי נעשה שני לקודש, אלא אפילו בחולין הנעשים על טהרת תרומה.","ומתקשים: כיצד אומר כן ר' אסי בשם ר' יוחנן? \u0003והא\u0004 \u0005[והרי]\u0006 לפי הסברו של רבה בר בר חנה בשם ר' יוחנן, \u0003\"אף אני לא אמרתי אלא ב\u0004חולין שנעשו על טהרת \u0003תרומה\" קאמר\u0004 \u0005[אמר]\u0006 ר' יהושע, ומכאן שבחולין שנעשו על טהרת הקודש לא אמר! ומשיבים: \u0003אמוראי נינהו\u0004 \u0005[\u0006מחלוקת \u0005אמוראים היא]\u0006 בהבנת שיטת ר' יהושע, \u0003ואליבא\u0004 \u0005[ועל פי שיטת]\u0006 \u0003ר' יוחנן,\u0004 שחלקו בשיטתו בזה.","\u0003אמר עולא: האוכל שלישי של חולין שנעשו על טהרת תרומה\u0004 — \u0003נפסל גופו מלאכול בתרומה.\u0004","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו\u0006 בכך\u0005]?\u0006 הלוא כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 דבר זה: האוכל \u0003שלישי\u0004 נעשה \u0003שני לקדש, ואין\u0004 הוא נעשה \u0003שני ל\u0004פסול את ה\u0003תרומה,\u0004 והוא \u0003ב\u0004שלישי ל\u0003חולין שנעשו על טהרת תרומה.\u0004 ונדייק מכאן: \u0003שני הוא דלא הוי\u0004 \u0005[שאינו\u0006 נעשה\u0005]\u0006 לתרומה, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003שלישי\u0004 לתרומה \u0003הוי\u0004 \u0005[הוא\u0006 נעשה\u0005],\u0006 ונפסל גופו מלאכול בתרומה!","ומשיבים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003מההיא\u0004 מאותה משנה, איני מוכרח לדייק כך, אלא \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שלענין תרומה \u0003לא שני הוי\u0004 \u0005[הוא]\u0006 \u0003ולא שלישי הוי\u0004 \u0005[הוא],\u0006 שאין מקום לעשות את דינו של האוכל כדין המאכל, \u0003ואיידי דאמר\u0004 \u0005[ו\u0006רק \u0005מתוך שאמר]\u0006 שהוא נעשה \u0003שני בקדש\u0004 — \u0003אמר נמי\u0004 \u0005[גם כן]\u0006 ש\u0003אין\u0004 הוא נעשה \u0003שני בתרומה,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 עולא שלענין תרומה הוא נעשה שלישי, שנפסל גופו מלאכול בתרומה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב המנונא לעולא\u0004 ממה ששנינו במשנה: \u0003הראשון שבחולין טמא,\u0004 שהוא פוסל מאכל חולין שנגע בו, \u0003ומטמא\u0004 תרומה שנגע בה, שהיא פוסלת תרומה אחרת שנגעה בה. \u0003והשני\u0004 שבחולין \u0003פוסל\u0004 את התרומה, שהיא אסורה באכילה, \u0003ו\u0004אולם \u0003אינו מטמא,\u0004 שאינה פוסלת תרומה שנגעה בה. \u0003והשלישי\u0004 שבחולין \u0003נאכל בנזיד הדמע\u0004 שמותר הכהן לתת ולערב (לדמע) תבלין של תרומה בתבשיל כזה ולאוכלו.","\u0003ו\u0004מעתה, \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שהאוכל שלישי של חולין שנעשו על טהרת התרומה \u0003נפסל גופו מלאכול בתרומה,\u0004 וכי \u0003ספינן ליה מידי דפסיל ליה לגופיה\u0004 \u0005[\u0006\u0005מאכילים אותו דבר שפוסל את גופו]\u0006 מלאכול בתרומה? והרי כשהוא אוכל תבשיל זה נמצא שהוא אוכל את התרומה המעורבת בו באיסור! \u0003אמר ליה\u0004 \u0005[לו]\u0006 עולא: \u0003הנח לנזיד הדמע,\u0004"],["\u0003דליכא\u0004 \u0005[שאין\u0006 שם\u0005]\u0006 בתערובת \u0003כזית\u0004 תרומה \u0003בכדי אכילת פרס,\u0004 ואין צורך לנהוג בתערובת כזאת בטהרת התרומה.","בדומה למה שאמר עולא בחולין שנעשו על טהרת התרומה, שהאוכל שלישי שבהם נפסל גופו לאכילת תרומה, \u0003אמר ר' יונתן אמר רבי: האוכל שלישי של תרומה עצמה\u0004 — \u0003אסור\u0004 לו \u0003לאכול\u0004 תרומה, \u0003ומותר ליגע\u0004 בתרומה.","ומעירים: \u0003ואיצטריך\u0004 \u0005[והוצרך]\u0006 מה שאמר \u0003עולא ואיצטריך\u0004 \u0005[והוצרך]\u0006 מה שאמר \u0003ר' יונתן, דאי\u0004 \u0005[שאם]\u0006 \u0003מ\u0004תוך דברי \u0003עולא, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 \u0003בחולין שנעשו על טהרת תרומה, אבל תרומה\u0004 עצמה — \u0003בנגיעה נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור,\u0004 לכן \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 מה שאמר \u0003ר' יונתן. ואי\u0004 \u0005[ואם]\u0006 \u0003מ\u0004תוך דברי \u0003ר' יונתן\u0004 שאמר שהאוכל שלישי של תרומה אסור לאכול תרומה ומותר ליגע בה, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים ב\u0003תרומה\u0004 עצמה, \u0003אבל\u0004 שלישי \u0003ב\u0004\u0003חולין\u0004 שנעשו על טהרת תרומה — \u0003באכילה נמי שרי\u0004 \u0005[גם כן מותרים],\u0006 על כן \u0003צריכי\u0004 \u0005[צריכים]\u0006 שני הדברים להיאמר.","\u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב יצחק בר שמואל בר מרתא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב נחמן, ויתיב וקאמר\u0004 \u0005[ויושב היה ואומר]\u0006 הלכה זו: \u0003האוכל שלישי של חולין שנעשו על טהרת הקדש\u0004 — \u0003טהור לאכול בקדש,\u0004 \u0003שאין לך דבר שעושה רביעי בקדש אלא קדש מקודש בלבד,\u0004 כגון בשר קרבן, אבל לא בחולין שנעשו על טהרת הקודש.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רמי בר חמא\u0004 ממה ששנינו בשם ר' יהושע: האוכל מאכל שהוא \u0003שלישי\u0004 — נעשה \u0003שני לקדש,\u0004 שמטמא שלישי ופוסל רביעי בקודש, \u0003ואין\u0004 הוא נעשה \u0003שני לתרומה,\u0004 לפוסלה, וכל זה \u0003בחולין שנעשו על טהרת תרומה.\u0004 ויש לשאול: לדברי רב יצחק, \u0003אמאי\u0004 \u0005[מדוע]\u0006 הוא נעשה שני לקודש, שעושה שלישי ורביעי? \u0003הא לאו\u0004 \u0005[הרי אין זה]\u0006 \u0003קדש מקודש הוא!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יצחק: \u0003הנח לתרומה, ש\u0004אפילו \u0003טהרתה\u0004 מה שנחשב טהור אצלה — \u0003טומאה היא אצל הקדש,\u0004 ולכן חולין שנעשו על טהרת תרומה מטמאים את הקודש.","\u0003ומנא תימרא\u0004 \u0005[ומנין אתה אומר]\u0006 שכן הוא? \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003בגדי עם הארץ\u0004 שאינם מקפידים על טהרה — הרי הם נחשבים כ\u0003מדרס\u0004 (החפצים שהזב והנדה יושבים או שוכבים עליהם), ומטמאים \u0003ל\u0004גבי ה\u0003פרושין,\u0004 אלה שנזהרים בדיני טומאה ואוכלים חולין שלהם בטהרה. \u0003בגדי פרושין\u0004 נחשבים ל\u0003מדרס ל\u0004גבי הכהנים \u0003אוכלי\u0004 ה\u0003תרומה,\u0004 וכן \u0003בגדי אוכלי תרומה\u0004 נחשבים \u0003מדרס ל\u0004אוכלי \u0003קדש.\u0004","\u0003אמר רבא:\u0004 מכאן אין ראיה, \u0003מדרסות קאמרת\u0004 \u0005[אתה אומר]?\u0006 \u0003שאני\u0004 \u0005[שונים]\u0006 \u0003מדרסות\u0004 של אוכלי תרומה, שיש בהם טעם מיוחד שגזרו עליהם טומאה לגבי הקודש,"],["מחשש \u0003שמא תשב\u0004 (ישבה) \u0003עליהן אשתו נדה, אבל בפירי לא אמרינן\u0004 \u0005[בפירות אין אנו אומרים]\u0006 שמה שנעשה בטהרת תרומה נחשב טמא לקודש. ומעירים, \u0003ור' יצחק, בפירי נמי\u0004 \u0005[בפירות גם כן]\u0006 \u0003אמר,\u0004 שפירות אוכלי תרומה מטמאים את הקודש, ולאו דווקא במדרס.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003ר' ירמיה מדיפתי: ומי אמרינן בפירי\u0004 \u0005[והאם אומרים אנו בפירות]\u0006 שהטהור לתרומה נחשב טמא לקודש? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 אין הכהן רשאי לקבל יין של תרומה מעם הארץ, החשוד על טהרת התרומה, אבל \u0003אם אמר\u0004 לו עם הארץ: \u0003\"הפרשתי לתוכה\u0004 לתוך חבית יין זו \u0003רביעית\u0004 של \u0003קדש\u0004 (יין המיועד לנסכים)\" — \u0003נאמן\u0004 לומר על התרומה שבתוכה שהיא טהורה, מפני שאינו חשוד לטמא את הקודש. \u0003ו\u0004מכאן ש\u0003לא קא מטמא ליה\u0004 \u0005[שאין מטמאה]\u0006 ה\u0003תרומה לקדש. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כדברי רב יצחק, ש\u0003טהרתה\u0004 של תרומה \u0003טומאה היא\u0004 נחשבת \u0003אצל הקדש,\u0004 אם כן \u0003תטמא תרומה לקדש!\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 לגבי \u0003טומאה בחבורין קאמרת\u0004 \u0005[אומר אתה]?\u0006 מתרומה שהיא מצויה יחד עם הקודש בכלי אתה מביא ראיה? \u0003טומאה בחבורין שאני\u0004 \u0005[שונה],\u0006 \u0003דמגו\u0004 \u0005[שמתוך]\u0006 ש\u0003מהימן\u0004 עם הארץ על טהרת ה\u0003קדש\u0004 — \u0003מהימן נמי\u0004 \u0005[גם כן]\u0006 על טהרת ה\u0003תרומה\u0004 המצויה עמו.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב הונא בר נתן\u0004 על רב יצחק ממה ששנינו: \u0003השני שבחולין מטמא משקה חולין,\u0004 שעושה אותו ראשון לטומאה, \u0003ופוסל אוכלי\u0004 (מאכלי) \u0003תרומה,\u0004 שהם פסולים לאכילה, אך אינם מטמאים תרומה אחרת, \u0003והשלישי\u0004 שבחולין \u0003מטמא משקה קדש,\u0004 עושה אותו ראשון לטומאה, \u0003ופוסל אוכלי קדש, בחולין שנעשו על טהרת הקדש.\u0004 והרי זה בניגוד למה שאמר רב יצחק, שהאוכל שלישי בחולין שנעשו על טהרת הקודש טהור לאכול בקודש, ואינו פוסלו!","ומשיבים: דבר זה \u0003תנאי\u0004 \u0005[מחלוקת תנאים]\u0006 \u0003היא, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003חולין שנעשו על טהרת קדש\u0004 — \u0003הרי הן כחולין\u0004 רגילים, ואין בהם כלל שלישי לטומאה.","\u0003ר' אלעזר ברבי צדוק אומר: הרי הן כתרומה, לטמא שנים,\u0004 שאם נגעו בטומאה יש בהם ראשון ושני, \u0003ולפסול אחד,\u0004 שהשני עושה שלישי, אבל השלישי אינו עושה רביעי. ור' יצחק הולך בשיטת ברייתא זו.","ושבים לדון במשנתנו, \u0003ר' שמעון אומר:\u0004 בעלי חיים שלא יצא דם בשחיטתם \u0003הוכשרו בשחיטה\u0004 עצמה לקבלת טומאה. \u0003אמר רב אסי, אומר היה ר' שמעון:\u0004 דווקא \u0003שחיטתו מכשרת ולא דם\u0004 השחיטה.","ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[\u0006האם \u0005נאמר שמסייע לו]\u0006 לרב אסי מה ששנינו במשנה, \u0003ר' שמעון אומר: הוכשרו בשחיטה, מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה: \u0003בשחיטה ולא בדם?\u0004 ודוחים: \u0003לא,\u0004 כוונתו שלא רק בדם הם מוכשרים, אלא \u0003אף בשחיטה.\u0004","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא, \u0003אמר להן ר' שמעון: וכי הדם מכשיר? והלא שחיטה מכשרת!\u0004 ומשיבים: גם מכאן אין ראיה גמורה, ויש להסביר ש\u0003הכי קאמר\u0004 \u0005[כך הוא אומר]\u0006 \u0003להן: וכי דם בלבד מכשיר? אף שחיטה נמי\u0004 \u0005[גם כן]\u0006 \u0003מכשרת.\u0004","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו, \u0003ר' שמעון אומר: דם המת\u0004 (בהמה שמתה מעצמה) \u0003אינו מכשיר\u0004 לקבל טומאה; \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 נדייק מכאן: \u0003הא\u0004 \u0005[אבל]\u0006 \u0003דם שחיטה מכשיר?\u0004 ודוחים: \u0003לא,\u0004 יש לדייק: \u0003הא\u0004 \u0005[אבל]\u0006 \u0003דם חללים\u0004 (הרוגים) \u0003מכשיר,\u0004 כלומר, דם של בהמה שנהרגה, ולא שמתה מעצמה. ומקשים: \u0003אבל דם שחיטה\u0004 לשיטתך, \u0003מאי\u0004 \u0005[מה]\u0006 יהא דינו, \u0003לא מכשיר?\u0004","אם כן \u0003לישמעינן\u0004 \u0005[שישמיע לנו]\u0006 ר' שמעון רק ש\u0003דם שחיטה\u0004 אינו מכשיר, \u0003ו\u0004אנו נבין ש\u0003כל שכן\u0004 ש\u0003דם המת\u0004 אינו מכשיר! ומשיבים: גם אם דם שחיטה מכשיר, עדיין \u0003דם המת איצטריכא ליה\u0004 \u0005[הוצרך לו\u0006 לומר\u0005]\u0006 שאינו מכשיר, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 הואיל ודם חללים מכשיר, מדוע דם המת אינו מכשיר? \u0003מה לי קטליה איהו\u0004 \u0005[אם הרג אותו הוא],\u0006 \u0003מה לי קטליה\u0004 \u0005[אם הרג אותו]\u0006 \u0003מלאך המות?\u0004 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 ר' שמעון שדם המת אינו מכשיר.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו, \u0003ר' שמעון אומר: דם מגפתו\u0004 (פצעו), שיוצא מהפצע, \u0003אינו מכשיר. מאי לאו\u0004 \u0005[האם אין]\u0006 לדייק מכאן: \u0003הא\u0004 \u0005[אבל]\u0006 \u0003דם שחיטה מכשיר?\u0004 ודוחים: \u0003לא,\u0004 הכוונה היא \u0003הא\u0004 \u0005[אבל]\u0006 \u0003דם חללים מכשיר.\u0004 ושואלים: \u0003אבל דם שחיטה מאי\u0004 \u0005[מהו]\u0006 לפי זה, \u0003לא מכשיר?\u0004","אם כן \u0003לשמעינן\u0004 \u0005[שישמיע לנו]\u0006 רק ש\u0003דם שחיטה\u0004 אינו מכשיר, \u0003ו\u0004אנו נבין ש\u0003כל שכן\u0004 ש\u0003דם מגפתו\u0004 אינו מכשיר! ומשיבים: למרות שדם שחיטה אינו מכשיר, עדיין \u0003דם מגפתו איצטריכא ליה\u0004 \u0005[הוצרך לו\u0006 לומר\u0005]\u0006 שגם כן אינו מכשיר, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 הואיל ודם חללים מכשיר, \u0003מה לי קטליה כולה\u0004 \u0005[אם הרג את הבהמה כולה]\u0006 \u0003מה לי קטליה פלגא\u0004 \u0005[אם הרג אותה למחצה],\u0006 לכן הוצרך להשמיענו שאינו מכשיר.","ושואלים: \u0003ומאי שנא\u0004 \u0005[ו\u0006ב\u0005מה שונה]\u0006 \u0003דם חללים\u0004 שהוא \u0003מכשיר\u0004 לדעת ר' שמעון? \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ודם חללים ישתה\"\u0004 (במדבר כג, כד), ומכאן שהוא חשוב משקה; והרי ביחס ל","\u0003דם שחיטה נמי כתיב\u0004 \u0005[גם כן נאמר]:\u0006 \u0003\"על הארץ תשפכנו כמים\"\u0004 (דברים יב, טז), הרי שהושווה למים! ומשיבים: \u0003ההוא\u0004 \u0005[אותו\u0006 פסוק\u0005]\u0006 לא ללמד לענין הכשר לטומאה הוא בא, אלא \u0003למישרי\u0004 \u0005[להתיר]\u0006 \u0003דמן\u0004 של \u0003פסולי המוקדשין בהנאה\u0004 כאילו היו מים \u0003הוא דאתא\u0004 \u0005[שבא],\u0006"],["שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ו\u0004פסולי המוקדשין \u0003אסירי\u0004 \u0005[אסורים]\u0006 \u0003בגיזה ועבודה\u0004 — \u0003דמן\u0004 גם כן נאסר בהנאה ולכן \u0003לבעי\u0004 \u0005[יצטרך]\u0006 \u0003קבורה,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שהוא מותר בהנאה.","\u0003תנא דבי\u0004 \u0005[שנה החכם מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל:\u0004 הכתוב \u0003\"ודם חללים ישתה\"\u0004 (במדבר כג, כד) מלמד כי הדם הנחשב משקה ומכשיר אוכלים לקבל טומאה, הוא דם של חללים, שכבר מתו — \u0003פרט לדם קילוח,\u0004 הדם שמקלח בכח, שהוא דם של חיים, \u0003שאינו מכשיר את הזרעים.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003השוחט\u0004 בהמה \u0003והתיז\u0004 (וניתז) \u0003דם\u0004 השחיטה \u0003על הדלעת\u0004 של תרומה — \u0003רבי אומר: הוכשר\u0004 הדלעת לקבל טומאה בדם זה, \u0003ר' חייא אומר: תולין,\u0004 ספק הוא.","\u0003אמר ר' אושעיא: מאחר שרבי אומר הוכשר, ור' חייא אומר תולין,\u0004 ואין בידינו להכריע ביניהם, \u0003אנו על מי נסמוך? באו ונסמוך על דברי ר' שמעון, שהיה ר' שמעון אומר: שחיטה מכשרת ולא דם.\u0004","ובפירוש הדברים \u0003אמר רב פפא: הכל מודים,\u0004 גם רבי וגם ר' חייא, \u0003היכא דאיתיה\u0004 \u0005[במקום שישנו]\u0006 ה\u0003דם\u0004 על הדלעת \u0003מתחלה ועד סוף\u0004 השחיטה — \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 שדם זה \u0003מכשיר,\u0004 כדין דם שחיטה (וכדעת חכמים החולקים במשנתנו על ר' שמעון). \u0003כי פליגי\u0004 \u0005[כאשר הם חלוקים]\u0006 הרי זה כאשר ניתז הדם על הדלעת בתחילת השחיטה, \u0003ו\u0004\u0003נתקנח הדם\u0004 מן הדלעת \u0003בין\u0004 שחיטת \u0003סימן\u0004 אחד \u0003לסימן\u0004 שני; \u0003רבי סבר\u0004 \u0005[סבור]:\u0006 \u0003ישנה לשחיטה מתחלה ועד סוף\u0004 כלומר, השחיטה קרויה שחיטה מתחילתה עד סופה, \u0003ו\u0004לפיכך \u0003האי\u0004 \u0005[\u0006דם \u0005זה],\u0006 שניתז כבר בתחילת השחיטה, \u0003דם שחיטה הוא\u0004 קרוי, ומכשיר.","ואילו \u0003ר' חייא סבר\u0004 \u0005[סבור]:\u0006 \u0003אינה לשחיטה אלא בסוף, ו\u0004אם כן, \u0003האי\u0004 \u0005[\u0006דם \u0005זה]\u0006 שניתז בתחילה, \u0003דם מכה\u0004 (פצע) \u0003הוא,\u0004 שאינו מכשיר. \u0003ו\u0004לפי זה, \u0003מאי\u0004 \u0005[מה פירוש]\u0006 \u0003תולין\u0004 שאמר ר' חייא? \u0003תולין הדבר עד גמר שחיטה, אי איתיה\u0004 \u0005[אם ישנו]\u0006 ה\u0003דם\u0004 על הדלעת \u0003בסוף שחיטה\u0004 — \u0003מכשיר, ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003לא מכשיר.\u0004","ושואלים: \u0003ומאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 דברי ר' אושעיא \u0003\"באו ונסמוך על דברי ר' שמעון\"?\u0004 והרי \u0003לר' שמעון\u0004 דם שחיטה \u0003לא מכשיר\u0004 כלל, ואילו \u0003לר' חייא\u0004 הוא \u0003מכשיר!\u0004","ומשיבים: \u0003בנתקנח\u0004 הדם קודם סוף השחיטה \u0003מיהו\u0004 \u0005[על כל פנים]\u0006 \u0003אשוו להדדי\u0004 \u0005[הושוו\u0006 דבריהם של ר' שמעון ור' חייא \u0005זה לזה],\u0006 \u0003מר\u0004 \u0005[\u0006\u0005חכם זה]\u0006 סבור ש\u0003לא מכשיר, ומר\u0004 \u0005[ו\u0006גם \u0005חכם זה]\u0006 סבור ש\u0003לא מכשיר,\u0004 אף שטעמיהם שונים, ואם כן \u0003הוה ליה רבי חד\u0004 \u0005[נמצא רבי אחד]\u0006 שסבור שהוא מכשיר, \u0003ואין דבריו של אחד במקום שנים.\u0004","\u0003רב אשי אמר:\u0004 הביטוי \u0003\"תולין\"\u0004 — \u0003לעולם משמע,\u0004 דבר שיש בו ספק בעיקר דינו, ולא דבר שמציאותו עומדת להתברר. \u0003ו\u0004במקרה ש\u0003נתקנח\u0004 הדם קודם גמר השחיטה, \u0003לר' חייא ספוקי מספקא ליה\u0004 \u0005[מסופק לו\u0006 הדבר\u0005]\u0006 בעיקר הדין, \u0003אי\u0004 \u0005[האם]\u0006 \u0003ישנה לשחיטה מתחלה ועד סוף,\u0004 ואם כן הריהו בכלל דם שחיטה ומכשיר, \u0003או אינה לשחיטה אלא בסוף\u0004 ואינו מכשיר. \u0003ו\u0004לפי זה, \u0003מאי\u0004 \u0005[מה פירוש]\u0006 \u0003תולין?\u0004 לא שהדבר תלוי האם יישאר הדם עד סוף השחיטה, אלא שאם נגעה טומאה בדלעת לאחר שנתקנח ממנה הדם — \u0003לא אוכלין\u0004 את דלעת התרומה, שמא נטמאה, \u0003ולא שורפין\u0004 אותה, שמא טהורה היא, ואסור לשורפה.","ומקשים: \u0003ו\u0004לפי זה \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"באו ונסמוך על דברי ר' שמעון\"?\u0004 והרי \u0003ל\u0004דעת \u0003ר' שמעון\u0004 הדם \u0003לא מכשיר\u0004 כלל, והדלעת טהורה, ואילו \u0003לר' חייא ספיקא\u0004 \u0005[ספק]\u0006 הוא! ומשיבים: \u0003לענין שריפה מיהו\u0004 \u0005[על כל פנים]\u0006 \u0003שוו להדדי\u0004 \u0005[שווים הם זה לזה],\u0006 \u0003מר לא שרפיה\u0004 \u0005[חכם זה,\u0006 ר' שמעון, \u0005לא שורף אותו],\u0006 משום שלדעתו לא הוכשרה הדלעת, \u0003ומר לא שרפיה\u0004 \u0005[וחכם זה,\u0006 ר' חייא, גם כן \u0005אינו שורף אותו]\u0006 מספק, ואם כן","\u0003הוה ליה רבי חד\u0004 \u0005[נמצא רבי אחד],\u0006 הסבור שניתן לשורפה, \u0003ואין דבריו של אחד במקום שנים. והכי קאמר\u0004 \u0005[וכך אומר]\u0006 ר' חייא: במקרה \u0003כגון זאת,\u0004 אם נגעה טומאה בדלעת \u0003תולין\u0004 כלומר, \u0003לא אוכלין\u0004 משום שיתכן שבכך הוכשרה ונטמאה, \u0003ולא שורפין,\u0004 שהרי לא ודאי שהוכשרה ונטמאה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' שמעון בן לקיש: צריד\u0004 (יבש) \u0003של מנחות,\u0004 כלומר, סולת יבשה של מנחה, שלא נבללה בשמן, וכך לא הוכשרה במשקה לקבלת טומאה, ומכל מקום כשנגעה בה טומאה הריהי פסולה להקרבה ולאכילה משום \"חיבת הקודש\" המכשירה אותה לקבלת טומאה, האם \u0003מונין בו ראשון ושני,\u0004 כדרך שמונים בכל מאכל שנטמא, שאם נגע באב הטומאה נעשה ראשון לטומאה, ועושה שני, \u0003או אין מונין בו ראשון ושני?\u0004 ומבארים: \u0003כי מהניא\u0004 \u0005[\u0006האם \u0005כאשר מועילה]\u0006 \u0003חבת הקדש\u0004 הרי זה רק \u0003לאפסולי גופיה\u0004 \u0005[לפסול אותו עצמו]\u0006 להקרבה ולאכילה, אבל \u0003למימנא ביה\u0004 \u0005[למנות בו]\u0006 \u0003ראשון ושני\u0004 — \u0003לא, או דלמא לא שנא\u0004 \u0005[שמא אינה שונה],\u0006 וכיון שחיבת הקודש מכשרתו — הרי הוא נעשה כשאר אוכל?","\u0003אמר ר' אלעזר: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא על הפסוק \u0003\"מכל האוכל אשר יאכל\u0004 אשר יבוא עליו מים יטמא\" (ויקרא יא, לד), \u0003אוכל הבא במים\u0004 — \u0003הוכשר\u0004 לקבל טומאה ולמנות בו ראשון ושני, \u0003אוכל שאינו בא במים\u0004 — \u0003לא הוכשר,\u0004 ואם כן הוא הדין לצריד של מנחות.","ותוהים: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003ר' שמעון בן לקיש לית ליה\u0004 \u0005[אין לו,\u0006 אינו יודע\u0005]\u0006 הלכה זו שרק \u0003אוכל הבא במים\u0004 מקבל טומאה? אלא \u0003ר' שמעון בן לקיש הכי קמיבעיא ליה\u0004 \u0005[כך נשאלת לו\u0006 השאלה\u0005]:\u0006 \u0003חבת הקדש\u0004 שמכשירה קדשים לפוסלם להקרבה אם נטמאו, האם \u0003כאוכל הבא במים דמי\u0004 \u0005[נחשב],\u0006 שעושה ראשון ושני, \u0003או לא?\u0004","ומוסיפים: \u0003ר' אלעזר\u0004 שהשיב לו, \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003מיתורי קראי קאמר\u0004 \u0005[מיתורי המקראות הוא אומר]\u0006 ומשם הוא לומד: \u0003מכדי כתיב\u0004 \u0005[הואיל ונאמר]:\u0006 \u0003\"וכי יותן מים על זרע\u0004 ונפל מנבלתם עליו טמא הוא לכם\" (שם לח), אם כן, הכתוב \u0003\"מכל האוכל אשר יאכל\u0004 אשר יבוא עליו מים יטמא\" \u0003למה לי?\u0004"],["\u0003לאו למעוטי\u0004 \u0005[\u0006האם \u0005לא למעט]\u0006 \u0003חיבת הקדש,\u0004 שאינה מכשירה לקבל טומאה כביאת מים, לעשות ראשון ושני? ודוחים: \u0003לא,\u0004 יש לומר ששני הכתובים מלמדים שיש צורך בביאת מים על האוכלים כדי להכשירם לקבלת טומאה, \u0003חד\u0004 \u0005[אחד]\u0006 מדבר \u0003בטומאת מת, וחד\u0004 \u0005[ואחד]\u0006 מדבר \u0003בטומאת שרץ.\u0004","\u0003וצריכי\u0004 \u0005[וצריכים]\u0006 שניהם להיאמר, \u0003דאי אשמעינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 רק ב\u0003טומאת מת,\u0004 היינו אומרים: \u0003התם הוא דבעי\u0004 \u0005[שם הוא שצריך]\u0006 האוכל \u0003הכשר, משום\u0004 שטומאת מת קלה יותר, שהמת \u0003לא מטמא ב\u0004שיעור קטן \u0003כעדשה,\u0004 אלא רק בכזית, \u0003אבל שרץ\u0004 ש\u0003מטמא בכעדשה\u0004 — \u0003אימא לא ליבעי\u0004 \u0005[אמור שלא יצטרך]\u0006 האוכל \u0003הכשר\u0004 כדי להיטמא בו.","\u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 רק ב\u0003שרץ,\u0004 היינו אומרים שדווקא לטומאת שרץ יש צורך בהכשר, \u0003משום\u0004 שטומאתו קלה יותר, שהוא \u0003לא מטמא\u0004 את הנוגע בו \u0003טומאת שבעה\u0004 ימים, \u0003אבל מת\u0004 ש\u0003מטמא טומאת שבעה\u0004 — \u0003אימא לא ליבעי\u0004 \u0005[אמור שלא יצטרך]\u0006 האוכל \u0003הכשר\u0004 כדי להיטמא בו, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שני הכתובים.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב יוסף\u0004 על שיטת ר' אלעזר, שרק אוכל שהוכשר במים מקבל טומאה לעשות ראשון ושני, ממה ששנינו במשנתנו שהשוחט בהמה חיה ועוף ולא יצא מהם דם, \u0003ר' שמעון אומר: הוכשרו בשחיטה,\u0004 ומה שאמר \u0003הוכשרו\u0004 משמעו — \u0003ואפילו למימני בהו\u0004 \u0005[למנות בהם]\u0006 \u0003ראשון ושני.\u0004","ויש לשאול: \u0003אמאי\u0004 \u0005[מדוע]\u0006 הוכשרו? \u0003והא לאו\u0004 \u0005[והרי לא]\u0006 \u0003אוכל הבא במים הוא!\u0004 ומכאן שכל דבר שמכשיר לקבל טומאה עושה ראשון ושני, ובכלל זה חיבת הקודש! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 יש לומר כי אין זה מדין תורה, אלא \u0003עשאוהו\u0004 את השחיטה \u0003כהכשר מים,\u0004 והוא \u0003מדרבנן\u0004 \u0005[מדברי סופרים].\u0006","\u0003אמר ר' זירא, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נוספת ממה ששנינו: \u0003הבוצר\u0004 ענבים \u0003לגת\u0004 (לעשות מהם יין), ובתוך כך זב מן המיץ על אשכול הענבים — \u0003שמאי אומר: הוכשר\u0004 לקבלת טומאה, \u0003הלל אומר: לא הוכשר, ו\u0004בסופו של דבר \u0003שתיק ליה\u0004 \u0005[שתק,\u0006 הודה \u0005לו]\u0006 \u0003הלל לשמאי.\u0004 ויש לשאול: \u0003אמאי\u0004 \u0005[מדוע]\u0006 הודה לו? \u0003והא לאו\u0004 \u0005[והרי לא]\u0006 \u0003אוכל הבא במים הוא,\u0004 שהרי אין משקה מכשיר אלא לרצון! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: עשאוהו כהכשר מים,\u0004 ואולם \u0003מדרבנן\u0004 \u0005[מדברי סופרים]\u0006 הוא.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף: אמינא לך אנא\u0004 \u0005[אומר אני לך]\u0006 ראיה מדברי ר' שמעון ש\u0003הוכשרו בשחיטה, ואת אמרת לי\u0004 \u0005[ואתה אומר לי]\u0006 שהכוונה היא ש\u0003עשאוהו\u0004 חכמים \u0003כהכשר מים, ו\u0004כן \u0003אמר\u0004 \u0005[אומר]\u0006 \u0003לך ר' זירא\u0004 ראיה מן הבוצר לגת, \u0003ואמרת ליה\u0004 \u0005[ואתה אומר לו]:\u0006 \u0003עשאוהו כהכשר מים,\u0004 אם כן ביחס \u0003ל\u0004שאלת \u0003ר' שמעון בן לקיש\u0004 בצריד של מנחות \u0003נמי\u0004 \u0005[גם כן]\u0006 נאמר, שמן התורה אין חיבת הקודש מכשירה, וחכמים \u0003עשאוהו כהכשר מים\u0004 למנות בו ראשון ושני!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003ר' שמעון בן לקיש\u0004 לענין \u0003לתלות קמיבעיא ליה\u0004 \u0005[נשאלה לו השאלה],\u0006 כלומר, לא לאכול ולא לשרוף את הצריד, כדין קודש שנטמא בטומאה שמדברי חכמים? \u0003כי קא מיבעיא ליה\u0004 \u0005[כאשר נשאלה לו]\u0006 השאלה הרי זה לענין \u0003לשרוף\u0004 את הצריד שנטמא, וכדין קודש שנטמא מדין תורה.","ואומרים: \u0003מכלל\u0004 הדברים אתה למד ש\u0003חיבת הקדש\u0004 מכשירה לקבלת טומאת אוכלים \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003מנא לן\u0004 \u0005[מנין לנו]\u0006 דבר זה? \u0003אילימא מדכתיב\u0004 \u0005[אם תאמר ממה שנאמר]\u0006 בבשר קדשים: \u0003\"והבשר אשר יגע בכל טמא\u0004 לא ייאכל באש יישרף\" (ויקרא ז, יט), ויש לברר: \u0003האי\u0004 \u0003בשר דאתכשר במאי\u0004 \u0005[בשר זה שהוכשר, במה]\u0006 הוכשר?","\u0003אילימא דאתכשר\u0004 \u0005[אם תאמר שהוכשר]\u0006 \u0003בדם\u0004 הבהמה — \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' חייא בר אבא אמר ר' יוחנן: מנין לדם קדשים שאינו מכשיר\u0004 אוכלים לקבלת טומאה? \u0003שנאמר:\u0004 \u0003\"לא תאכלנו על הארץ תשפכנו כמים\"\u0004 (דברים יב, כד), ללמד ש\u0003דם הנשפך כמים\u0004 — \u0003מכשיר\u0004 כמו מים, דם \u0003שאינו נשפך כמים,\u0004 אלא מתקבל בכלי כדי לזורקו על המזבח — \u0003אינו מכשיר!\u0004","\u0003אלא\u0004 תאמר \u0003דאיתכשר\u0004 \u0005[שהוכשר]\u0006 הבשר \u0003במשקי בית מטבחיא\u0004 \u0005[\u0006ב\u0005משקים של בית המטבחיים\u0006 במקדש\u0005]\u0006 כגון מים שרחץ בהם את הבשר — \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' יוסי בר' חנינא: משקי בית מטבחיא\u0004 \u0005[בית המטבחיים]\u0006 שבמקדש \u0003לא דיין שהן\u0004 עצמם \u0003דכן\u0004 \u0005[טהורים],\u0006 שאינם מקבלים טומאה, \u0003אלא ש\u0004אף \u0003אין\u0004 הם \u0003מכשירין\u0004 אוכלין לקבלת טומאה! \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003תרגמא\u0004 \u0005[תרגם\u0006 והסבר\u0005]\u0006 את דברי ר' יוסי בר' חנינא לגבי \u0003דם\u0004 בלבד, אבל שאר משקים שבמקדש מכשירים, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"משקי\" קאמר\u0004 \u0005[הוא אומר]\u0006 בלשון רבים! \u0003אלא לאו\u0004 \u0005[האם אין]\u0006 הכוונה \u0003דאתכשר\u0004 \u0005[שהוכשר]\u0006 הבשר \u0003בחבת הקדש?\u0004 ומכאן שחיבת הקודש מכשירה מדין תורה.","ודוחים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 יש לפרש את הכתוב \u0003כ\u0004דברי \u0003רב יהודה אמר שמואל,\u0004 ש\u0003אמר רב יהודה אמר שמואל:\u0004 מדובר ב\u0003כגון שהיתה לו פרה של זבחי שלמים, והעבירה בנחל\u0004 כדי להכין אותה לשחיטה, ו\u0003שחטה ועדיין משקה\u0004 של מי הנחל \u0003טופח עליה,\u0004 וכך הוכשר הבשר לקבל טומאה על ידי משקים, ולא בגלל חיבת הקודש!","\u0003אלא\u0004 ההוכחה היא \u0003מסיפא\u0004 \u0005[מסופו]\u0006 של הכתוב העוסק בקדשים שנטמאו, שנאמר: \"והבשר אשר יגע בכל טמא לא יאכל באש ישרף והבשר כל טהור יאכל בשר\" (ויקרא ז, יט), ומאחר שכבר אמר הכתוב \"והבשר\" הרי שהמלה \u0003\"והבשר\"\u0004 שנאמרה בהמשכו מיותרת, ואמרו חכמים כי היא באה \u0003לרבות עצים ולבונה\u0004 של קודש, שאם נטמאו הריהם נפסלים להקרבה כבשר. ויש לשאול: וכי \u0003עצים ולבונה בני אכילה נינהו\u0004 \u0005[הם],\u0006 שנאמר שהם בכלל \"מכל האוכל אשר יאכל אשר יבוא עליו מים יטמא\" (ויקרא יא, לד)? \u0003אלא\u0004 מכאן למד ר' שמעון בן לקיש ש\u0003חבת הקדש מכשרא להו\u0004 \u0005[מכשירה אותם]\u0006 לקבל טומאה, \u0003ומשויא להו\u0004 \u0005[ועושה אותם]\u0006 כאילו היו \u0003אוכל\u0004 שהוכשר במים. ולפי זה למד כי \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בצריד של מנחה, יש לומר ש\u0003חבת הקדש מכשרתה\u0004 לקבל טומאה."],["\u0003מאי\u0004 \u0005[מה]\u0006 מסקנת הדבר? האם \u0003כי מהניא\u0004 \u0005[כאשר מועילה]\u0006 \u0003חבת הקדש,\u0004 הרי זה \u0003לפסולא דגופיה\u0004 \u0005[לפסול את גופו]\u0006 של הקודש, \u0003אבל למימנא ביה\u0004 \u0005[למנות בו]\u0006 \u0003ראשון ושני לא\u0004 מועילה, \u0003או דלמא לא שנא\u0004 \u0005[שמא אין הבדל],\u0006 ואף לענין זה היא מועילה? שאלה זו לא נפתרה, ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003השוחט את המסוכנת\u0004 (בהמה העומדת למות) — \u0003רבן שמעון בן גמליאל אומר:\u0004 אינה כשרה \u0003עד שתפרכס ביד\u0004 (ברגל הקדמית) \u0003ו\u0004גם \u0003ברגל\u0004 (האחורית), שכך ניכר הדבר שהיתה בה חיות בזמן השחיטה. \u0003ר' אליעזר אומר: דיה אם זינקה,\u0004 כלומר, אם הדם מזנק ממקום השחיטה. \u0003אמר ר' שמעון: השוחט בלילה\u0004 בהמה מסוכנת, \u0003ולמחר השכים ומצא\u0004 שה\u0003כתלים מלאים דם\u0004 — \u0003כשרה,\u0004 שהדבר מעיד \u0003שזינקה, וכמדת\u0004 (וכשיטת) \u0003ר' אליעזר,\u0004 שהכשיר אם זינקה. \u0003וחכמים אומרים:\u0004 השוחט את המסוכנת אינה כשרה \u0003עד שתפרכס או ביד או ברגל, או עד שתכשכש בזנבה.\u0004","ומוסיפים: \u0003אחד בהמה דקה ואחד בהמה גסה\u0004 לענין זה, שמסוכנת צריכה פירכוס כדי להכשירה. \u0003בהמה דקה ש\u0004בשעת השחיטה \u0003פשטה ידה\u0004 שהיתה כפופה \u0003ולא החזירה\u0004 את היד — \u0003פסולה, שאינה אלא\u0004 סימן ל\u0003הוצאת נפש בלבד,\u0004 ואין זה נחשב פירכוס שיש בו סימן של חיים. \u0003במה דברים אמורים\u0004 שיש צורך בסימנים אלו? \u0003שהיתה\u0004 הבהמה \u0003בחזקת מסוכנת, אבל אם היתה בחזקת בריאה, אפילו אין בה אחד מכל הסימנים הללו\u0004 — \u0003כשרה.\u0004","ושואלים: \u0003מסוכנת ממאי\u0004 \u0005[ממה]\u0006 אנו יודעים \u0003דשריא\u0004 \u0005[שהיא מותרת]\u0006 על ידי שחיטה? ושואלים כנגד זה: \u0003וממאי\u0004 \u0003תיסק אדעתין דאסירא\u0004 \u0005[וממה יעלה על דעתנו\u0006 לומר \u0005שהיא אסורה]?\u0006 ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"זאת החיה אשר תאכלו\"\u0004 (ויקרא יא, ב) ודי היה לו \"זאת אשר תאכלו\", אלא מכאן ניתן היה ללמוד כי דווקא \u0003חיה\u0004 (שראויה לחיות) \u0003אכול, ושאינה חיה לא תאכל, והא\u0004 \u0005[וזו]\u0006 שהיא \u0003מסוכנת\u0004 הרי \u0003אינה חיה,\u0004 שהיא עומדת למות. ומנין שהיא מותרת?","ומשיבים, \u0003מדאמר רחמנא\u0004 \u0005[ממה שאמרה התורה]:\u0006 \u0003נבלה לא תאכל\u0004 (\"לא תאכלו כל נבלה\". דברים יד, כא) — \u0003מכלל\u0004 הדברים אתה למד שזו שאינה נבילה אלא רק \u0003מסוכנת שריא\u0004 \u0005[מותרת],\u0006 \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך\u0006 לומר\u0005]\u0006 ש\u0003מסוכנת אסירא\u0004 \u0005[אסורה],\u0006 \u0003השתא מחיים אסירא\u0004 \u0005[עכשיו,\u0006 הרי \u0005מחיים היא אסורה\u0006 כבר\u0005],\u0006 \u0003לאחר מיתה מיבעי\u0004 \u0005[נצרכה לומר]\u0006 שהיא אסורה?","ודוחים: \u0003ודלמא היינו\u0004 \u0005[ושמא זוהי]\u0006 \u0003נבלה היינו\u0004 \u0005[זוהי]\u0006 \u0003מסוכנת,\u0004 שמדובר באותו איסור, שאיסור נבילה חל על הבהמה כבר בחייה, כשהיתה מסוכנת ועומדת למות! ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[לא יעלה על דעתך]\u0006 לומר כן, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וכי ימות מן הבהמה אשר היא לכם לאכלה הנוגע בנבלתה\u0004 יטמא\" (ויקרא יא, לט), ומכאן אתה למד ש\u0003לאחר מיתה הוא דקרייה רחמנא\u0004 \u0005[שקראה אותה התורה]\u0006 \u0003נבלה, מחיים לא אקרי\u0004 \u0005[אינה קרויה]\u0006 \u0003נבלה.\u0004","ומקשים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003לעולם אימא לך\u0004 \u0005[אומר לך]:\u0006 \u0003היינו\u0004 \u0005[זוהי]\u0006 \u0003נבלה היינו\u0004 \u0005[זוהי]\u0006 \u0003מסוכנת,\u0004 שמדובר באותו איסור, ואולם \u0003מחיים,\u0004 אם שחטה כשהיא מסוכנת — עובר עליה רק \u0003ב\u0004איסור \u0003עשה,\u0004 כפי שלמדנו לעיל מ\"זאת החיה אשר תאכלו\" (ויקרא יא, ב), ומכאן שמסוכנת שאינה חיה לא תאכלו, ואילו \u0003לאחר מיתה\u0004 עובר עליה גם \u0003בלאו\u0004 (איסור לא תעשה) של \"לא תאכלו כל נבלה\" (דברים יד, כא)!","\u0003אלא\u0004 הראיה היא ממקום אחר, \u0003מדאמר רחמנא\u0004 \u0005[ממה שאמרה התורה]\u0006 \u0003טרפה לא תאכל\u0004 (\"ובשר בשדה טרפה לא תאכלו\" שמות כב, ל), שבעל חיים שנטרף (ואירע בו נקב או חסרון אחר שהוא עתיד למות ממנו), אסור באכילה — \u0003מכלל\u0004 הדברים אתה למד ש\u0003מסוכנת,\u0004 העומדת למות מחמת חולי \u0003שריא\u0004 \u0005[מותרת],\u0006 \u0003דאי סלקא דעתך\u0004 \u0005[שאם יעלה על דעתך\u0006 לומר\u0005]\u0006 ש\u0003מסוכנת אסירא\u0004 \u0005[אסורה],\u0006 מדוע הוצרך הכתוב לאסור טריפה? \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003מסוכנת דלא מחסרא אסירא\u0004 \u0005[שאין בה חסרון אסורה],\u0006 \u0003טרפה\u0004 שהיא מסוכנת מחמת חסרון שאירע בה \u0003מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שהיא אסורה? אלא מכאן שמסוכנת אינה אסורה.","ומקשים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003היינו\u0004 \u0005[זוהי]\u0006 \u0003טרפה היינו\u0004 \u0005[זוהי]\u0006 \u0003מסוכנת,\u0004 כלומר, גם מסוכנת היא בכלל \"טרפה לא תאכל\", ש\"טריפה\" משמעה כל בהמה העומדת למות, בין אם מחמת חסרון ובין אם מחמת חולי, וממה שנאמר \"וזאת החיה\" למדנו \u0003לעבור עליו\u0004 גם \u0003בעשה ו\u0004גם ב\u0003לא תעשה!\u0004 ודוחים: \u0003אם כן, נבלה דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 שאסור לאוכלה, \u0003למה לי? ומה מחיים,\u0004 כשהיא מסוכנת ועומדת להיעשות נבילה, \u0003קאי עלה\u0004 \u0005[עומד עליה]\u0006 \u0003ב\u0004איסור \u0003לאו ועשה,\u0004 \u0003לאחר מיתה מיבעיא\u0004 \u0005[נצרכה לומר]\u0006 שהיא אסורה גם בלאו וגם בעשה? וכי להיכן נעלם האיסור שהיה בה? אלא מכאן שמסוכנת אינה בכלל איסור טריפה, ולכן הוצרך הכתוב לאסור נבילה.","ומקשים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003היינו\u0004 \u0005[זוהי]\u0006 \u0003נבלה היינו\u0004 \u0005[זוהי]\u0006 \u0003טרפה היינו\u0004 \u0005[זוהי]\u0006 \u0003מסוכנת, ו\u0004מה שנאמר בתורה איסור לא תעשה בנבילה הוא כדי \u0003לעבור עליו\u0004 לאחר מותו \u0003בשני לאוין ועשה!\u0004","\u0003אלא מהכא\u0004 \u0005[מכאן]\u0006 ראיה שמסוכנת מותרת, שנאמר: \u0003\"וחלב נבלה וחלב טרפה יעשה לכל מלאכה ואכל לא תאכלוהו\"\u0004 (ויקרא ז, כד), \u0003ואמר מר\u0004 \u0005[החכם]:\u0006 \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 נאמר איסור זה? וכי משום שהיא נבילה או טריפה יהיה מותר חלבה? אלא \u0003אמרה התורה: יבא איסור נבלה ויחול על איסור חלב,\u0004 שהאוכל חלב נבילה יעבור גם על איסור אכילת חלב וגם על איסור אכילת נבילה, וכן \u0003יבא איסור טרפה ויחול על איסור חלב.\u0004"],["\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך לומר]\u0006 ש\u0003טרפה\u0004 שאסרה התורה באכילה \u0003היינו\u0004 \u0005[זוהי]\u0006 ה\u0003מסוכנת\u0004 העומדת להיעשות נבילה, \u0003לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 \u0003\"חלב נבלה יעשה לכל מלאכה, וחלב טרפה לא תאכלוהו\",\u0004 כלומר, שייכתב איסור האכילה בטריפה בלבד ולא בנבילה, \u0003ואנא אמינא\u0004 \u0005[ואני אומר\u0006 מעצמי\u0005]\u0006 בקל וחומר: \u0003ומה מחיים,\u0004 כשהיא מסוכנת, ועדיין אינה נבילה גמורה, \u0003אתי\u0004 \u0005[בא]\u0006 \u0003איסור טרפה\u0004 ו\u0003חייל\u0004 \u0005[חל]\u0006 על \u0003איסור חלב\u0004 שיש בה, \u0003לאחר מיתה,\u0004 כשהיא נעשית נבילה גמורה, \u0003מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שאיסור נבילה חל על איסור החלב?","\u0003אלא מדכתב רחמנא\u0004 \u0005[מתוך ש\u0006חזרה ו\u0005כתבה התורה]\u0006 איסור חלב ב\u0003נבלה, מכלל\u0004 הדברים אתה למד ש\u0003טרפה\u0004 שאסר הכתוב את חלבה \u0003לאו היינו\u0004 \u0005[אינה זו]\u0006 ה\u0003מסוכנת\u0004 העומדת להיעשות נבילה, אלא טריפה ממש, שיש חסרון בגופה, ודווקא היא נאסרה, ולא המסוכנת, ולכן הוצרכה התורה לאסור חלב נבילה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003מר בר רב אשי, ודלמא\u0004 \u0005[ושמא]\u0006 \u0003לעולם אימא לך\u0004 \u0005[אומר לך]:\u0006 \u0003היינו\u0004 \u0005[זוהי]\u0006 \u0003טרפה היינו\u0004 \u0005[זוהי]\u0006 \u0003מסוכנת, ודקאמרת\u0004 \u0005[ומה שאמרת]:\u0006 אם כן, חלב \u0003נבלה דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003למה לי?\u0004 והרי יש לאוסרה בקל וחומר ממסוכנת! יש לומר שהוא מתייחס \u0003להך נבלה דלא אתיא\u0004 \u0005[לאותה נבלה שאינה באה]\u0006 \u0003מכח מסוכנת,\u0004 שלא היתה מסוכנת קודם שנעשתה נבילה, \u0003והיכי דמי\u0004 \u0005[וכיצד בדיוק מדובר]?\u0006 כגון \u0003ש\u0004לקח בהמה בריאה ו\u0003עשאה גיסטרא\u0004 (שחתך אותה לשנים)! ודוחים: \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 במקרה כזה, \u0003אי אפשר דלא הוי\u0004 \u0005[שלא היתה]\u0006 \u0003מסוכנת פורתא\u0004 \u0005[\u0006זמן \u0005מועט]\u0006 \u0003מקמי דליפסק לרובא\u0004 \u0005[לפני שחתך את הרוב].\u0006","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 מקור אחר לכך שמסוכנת מותרת, ואינה בכלל איסור טריפה, ש\u0003אם כן,\u0004 שגם היא בכלל איסור טריפה, \u0003לימא\u0004 \u0005[שיאמר\u0006 הכתוב\u0005]\u0006 \u0003\"חלב נבלה וטרפה\",\u0004 \u0003\"חלב\u0004 נבילה\" \u0003\"חלב\u0004 טריפה\" \u0003למה לי?\u0004 כלומר, למה חזר הכתוב והזכיר חלב בטריפה? כדי להדגיש ש\u0003זו\u0004 \u0003היא שאין חלבה חלוק מבשרה\u0004 לענין איסור, שגם על הבשר וגם על החלב חל איסור טריפה, \u0003ויש לך\u0004 בהמה \u0003אחרת\u0004 דומה לה \u0003שחלבה חלוק מבשרה, ואיזו זו? מסוכנת,\u0004 שרק חלבה אסור ולא בשרה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור],\u0006 \u0003מהכא\u0004 \u0005[מכאן]\u0006 אפשר ללמוד שמסוכנת מותרת, שאמר הנביא יחזקאל: \u0003\"ואומר אהה ה' אלהים הנה נפשי לא מטומאה ונבלה וטרפה לא אכלתי מנעורי ועד עתה ולא בא בפי בשר פגול\"\u0004 (יחזקאל ד, יד).","ומפרשים: \u0003\"הנה נפשי לא מטומאה\"\u0004 — \u0003שלא הרהרתי\u0004 הרהור עבירה \u0003ביום לבא\u0004 על ידו \u0003לידי טומאה\u0004 של קרי \u0003בלילה. \"ונבלה וטרפה לא אכלתי מנעורי\"\u0004 — \u0003שלא אכלתי בשר \"כוס כוס\"\u0004 \u0005[\"שחוט שחוט\"]\u0006 \u0003מעולם,\u0004 כלומר בשר בהמה מסוכנת, שאומרים לשוחט שיזדרז לשוחטה קודם שתמות. \u0003\"ולא בא בפי בשר פגול\"\u0004 — \u0003שלא אכלתי מבהמה ש\u0004היה בה ספק איסור ו\u0003הורה בה חכם\u0004 להתירה. \u0003משום\u0004 (בשם) \u0003ר' נתן אמרו\u0004 בפירוש דבר זה: \u0003שלא אכלתי מבהמה שלא הורמו מתנותיה,\u0004 זרוע לחיים וקיבה שצריך לתת לכהנים מכל בהמת חולין.","ומעתה, \u0003אי אמרת בשלמא שריא\u0004 \u0005[נניח אם אתה אומר\u0006 שמסוכנת \u0005מותרת]\u0006 — \u0003היינו רבותיה\u0004 \u0005[זוהי גדולתו]\u0006 של \u0003יחזקאל,\u0004 שהקפיד בדברים שמותרים על פי הדין, שלמרות שמסוכנת מותרת — לא אכל מבשרה. \u0003אלא אי אמרת אסירא\u0004 \u0005[אם אומר אתה\u0006 שהיא \u0005אסורה],\u0006 \u0003מאי רבותיה\u0004 \u0005[מה גדולתו]\u0006 של \u0003יחזקאל?\u0004 אלא מכאן משמע שבהמה כזו מותרת מן הדין.","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד היא בדיוק]\u0006 \u0003מסוכנת? אמר רב יהודה אמר רב: כל\u0004 בהמה \u0003שמעמידין אותה ואינה עומדת. רב חנינא בר שלמיא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב אמר:\u0004 סימן זה שאינה עומדת הוא מובהק ש\u0003אפילו\u0004 היא \u0003אוכלת בקעיות\u0004 (חתיכות עץ), שיש לה כח בשיניה, מכל מקום כיון שכשמעמידים אותה אינה עומדת היא נחשבת למסוכנת. \u0003רמי בר יחזקאל אמר:\u0004 \u0003אפילו אוכלת קורות.\u0004","ומעירים: \u0003בסורא מתני הכי\u0004 \u0005[היו שונים כך]\u0006 כפי שאמרנו. \u0003בפומבדיתא מתני הכי\u0004 \u0005[\u0006היו \u0005שונים כך]:\u0006 \u0003היכי דמיא\u0004 \u0005[כיצד היא בדיוק]\u0006 \u0003מסוכנת? אמר רב יהודה אמר רב: כל שמעמידין אותה ואינה עומדת, ואפילו אוכלת בקעיות,\u0004 ולפי מסורת זאת, דברי רב חנינא בר שלמיא נשנו כחלק מדברי רב יהודה בשם רב. \u0003רמי בר יחזקאל אמר: אפילו אוכלת קורות.\u0004","מסופר, \u0003אשכחינהו\u0004 \u0005[מצא אותו]\u0006 \u0003שמואל\u0004 את \u0003תלמידי רב\u0004 אחר מות רב, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 \u0003אמר רב ב\u0004ענין ה\u0003מסוכנת? אמרו ליה\u0004 \u0005[לו],\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב:\u0004"]]};
